def declarative_current_legal_fact_reasons(
        page, visible, rule, stj_source_groups=()):
    source_code, source_groups, outcome_code, outcome_groups = rule
    reasons = []
    missing_source = any(
        not has_declarative_source_url_any(page, *alternatives)
        for alternatives in source_groups)
    if not missing_source:
        missing_source = any(
            not any(has_declarative_stj_source_identity(page, alternative)
                    for alternative in alternatives)
            for alternatives in stj_source_groups)
    if missing_source:
        reasons.append(f'current_legal_fact_source_missing:{source_code}')
    if any(not any(declarative_alternative_affirmed_in_text(
            visible, alternative) for alternative in alternatives)
            for alternatives in outcome_groups):
        reasons.append(f'current_legal_fact_outcome_missing:{outcome_code}')
    return reasons


def declarative_alternative_affirmed_in_text(visible, alternative):
    return any(declarative_alternative_affirmed(
                   tokens, alternative, comma_before, colon_before)
               for tokens, comma_before, colon_before in
               semantic_declarative_legal_fact_clauses(visible))


def declarative_alternative_copular_negated_in_text(visible, alternative):
    alternative_tokens = re.sub(
        r'[^a-z0-9]+', ' ', norm_key(alternative)).split()
    if not alternative_tokens:
        return False
    width = len(alternative_tokens)
    for tokens, comma_before, _ in semantic_declarative_legal_fact_clauses(
            visible):
        for start in range(len(tokens) - width + 1):
            if (tokens[start:start + width] == alternative_tokens and
                    declarative_copular_negates_assertion(
                        tokens, start, comma_before)):
                return True
    return False


def declarative_alternative_affirmed(
        visible_tokens, alternative, comma_before=None, colon_before=None):
    alternative_tokens = re.sub(
        r'[^a-z0-9]+', ' ', norm_key(alternative)).split()
    if not alternative_tokens or len(alternative_tokens) > len(visible_tokens):
        return False
    expected_negative = any(
        token in {'nao', 'nem', 'nunca', 'jamais', 'sem'}
        for token in alternative_tokens)
    width = len(alternative_tokens)
    negative_tokens = {
        'nao', 'nem', 'nunca', 'jamais', 'sem', 'falso', 'falsa', 'incorreto',
        'incorreta', 'revogado', 'revogada', 'revogados', 'revogadas',
        'inaplicavel'}
    # FIX correcao cruzada (Claude Code 2026-07-11): numero de artigo em forma
    # espacada na regra ('art 1 341') deve casar tambem a forma solida que o corpo
    # usa ('art. 1341' -> token '1341'). Sem isto o gate current_legal_fact_outcome_
    # missing REPROVA artigo que ESTA citado (falso-positivo que trava conteudo
    # correto; ex.: imob-rateio-obra-luxo-minoria cita 1341/1342). Reaproveita a
    # semantica do laco principal (guards de negacao local) num alvo de 1 token.
    if (alternative_tokens[0] == 'art' and len(alternative_tokens) >= 2
            and all(tok.isdigit() for tok in alternative_tokens[1:])):
        solid_article = ''.join(alternative_tokens[1:])
        for index, token in enumerate(visible_tokens):
            if token != solid_article:
                continue
            if 'art' not in visible_tokens[max(0, index - 3):index]:
                continue
            if declarative_clause_meta_negates_assertion(
                    visible_tokens, index, comma_before, colon_before):
                continue
            if declarative_copular_negates_assertion(
                    visible_tokens, index, comma_before):
                continue
            if expected_negative:
                return True
            if not declarative_occurrence_locally_negated(
                    visible_tokens, index, 1, negative_tokens,
                    comma_before):
                return True
    for start in range(len(visible_tokens) - width + 1):
        if visible_tokens[start:start + width] != alternative_tokens:
            continue
        if declarative_clause_meta_negates_assertion(
                visible_tokens, start, comma_before, colon_before):
            continue
        # A negative literal is not affirmed when an outer copula denies it:
        # "não é sem cobrança" must not satisfy the rule "sem cobrança".
        if declarative_copular_negates_assertion(
                visible_tokens, start, comma_before):
            continue
        if expected_negative:
            if not declarative_occurrence_negated_before(
                    visible_tokens, start, negative_tokens, comma_before):
                return True
            continue
        if not declarative_occurrence_locally_negated(
                visible_tokens, start, width, negative_tokens,
                comma_before):
            return True
    return False


