def declarative_copular_negates_assertion(
        tokens, assertion_start, comma_before=None):
    left = declarative_negation_scope_left(
        assertion_start, 5, comma_before)
    prefix = tokens[left:assertion_start]
    copulas = {
        'e', 'sao', 'era', 'eram', 'foi', 'foram', 'sera', 'serao',
        'seria', 'seriam'}
    for index, token in enumerate(prefix):
        if token not in {'nao', 'nunca', 'jamais'}:
            continue
        if index + 1 < len(prefix) and prefix[index + 1] in copulas:
            # "não é sem cobrança" nega o predicado, enquanto "não é falso
            # que X" contém uma segunda negação metalinguística e afirma X.
            # Preserve a simetria com o matcher Go para não reprovar a matriz
            # imobiliária correta nem reabrir o falso-verde de literal negativo.
            if (index + 2 < len(prefix) and semantic_token_has_any_prefix(
                    prefix[index + 2], 'fals', 'incorret', 'errad', 'equivoc',
                    'inverid', 'mentir')):
                continue
            return True
    return False


def declarative_clause_meta_negates_assertion(
        tokens, assertion_start, comma_before=None, colon_before=None):
    left = declarative_negation_scope_left(
        assertion_start, 12, comma_before)
    prefix = tokens[left:assertion_start]
    scope_start = declarative_comma_scope_start(
        assertion_start, comma_before)
    # Preserve comma as the ordinary scope boundary, but allow a leading
    # meta-predicate to govern a colon-introduced proposition even when the
    # proposition itself contains a comma ("é falso: o STJ, no Tema 484").
    # Requiring a real colon keeps the previous anti-lookback fix intact.
    if (scope_start > 0 and declarative_has_colon_before(
            assertion_start, colon_before)):
        scope_start = 0
    scope_tokens = tokens[scope_start:]
    scope_assertion_start = assertion_start - scope_start
    leading_meta_predicate = lambda token: token in {
        'falso', 'falsa', 'incorreto', 'incorreta', 'errado', 'errada',
        'equivocado', 'equivocada', 'inveridico', 'inveridica', 'mentira'}
    reporting_noun = lambda token: semantic_token_has_any_prefix(
        token, 'afirm', 'tese', 'aleg')
    truth_predicate = lambda token: semantic_token_has_any_prefix(
        token, 'verdad', 'corret')
    leading_meta_index = -1
    leading_double_negation = False
    if (len(scope_tokens) >= 3 and
            scope_tokens[:2] == ['nao', 'e'] and
            leading_meta_predicate(scope_tokens[2])):
        leading_double_negation = True
    elif (len(scope_tokens) >= 5 and scope_tokens[0] in {'a', 'o'} and
          reporting_noun(scope_tokens[1]) and
          scope_tokens[2:4] == ['nao', 'e'] and
          leading_meta_predicate(scope_tokens[4])):
        leading_double_negation = True
    elif (len(scope_tokens) >= 3 and
          scope_tokens[:2] == ['nao', 'e'] and
          truth_predicate(scope_tokens[2])):
        leading_meta_index = 2
    elif (len(scope_tokens) >= 5 and scope_tokens[0] in {'a', 'o'} and
          reporting_noun(scope_tokens[1]) and
          scope_tokens[2:4] == ['nao', 'e'] and
          truth_predicate(scope_tokens[4])):
        leading_meta_index = 4
    elif (len(scope_tokens) >= 2 and scope_tokens[0] == 'e' and
          leading_meta_predicate(scope_tokens[1])):
        leading_meta_index = 1
    elif scope_tokens and leading_meta_predicate(scope_tokens[0]):
        leading_meta_index = 0
    elif (len(scope_tokens) >= 3 and scope_tokens[0] in {'isso', 'isto'} and
          scope_tokens[1] == 'e' and
          leading_meta_predicate(scope_tokens[2])):
        leading_meta_index = 2
    elif (len(scope_tokens) >= 4 and scope_tokens[0] in {'a', 'o'} and
          reporting_noun(scope_tokens[1]) and scope_tokens[2] == 'e' and
          leading_meta_predicate(scope_tokens[3])):
        leading_meta_index = 3
    elif (len(scope_tokens) >= 2 and
          scope_tokens[0] in {'seria', 'parece'} and
          leading_meta_predicate(scope_tokens[1])):
        leading_meta_index = 1
    if leading_double_negation:
        return False
    if (leading_meta_index >= 0 and
            scope_assertion_start - leading_meta_index <= 10):
        return True
    try:
        last_complement = len(prefix) - 1 - prefix[::-1].index('que')
    except ValueError:
        return False
    if len(prefix) - last_complement > 3:
        return False
    frame = prefix[max(0, last_complement - 8):last_complement + 1]
    if declarative_frame_denies_normative_basis(frame):
        return True
    has_negation = any(token in {'nao', 'nunca', 'jamais'}
                       for token in frame)
    has_truth_or_reporting = any(semantic_token_has_any_prefix(
        token, 'afirm', 'diz', 'sustent', 'aleg', 'declar', 'verdad',
        'corret', 'possivel') for token in frame)
    for index, token in enumerate(frame):
        if not semantic_token_has_any_prefix(
                token, 'fals', 'incorret', 'errad', 'equivoc',
                'inverid', 'mentir'):
            continue
        double_negated = any(
            frame[prior] == 'nao'
            for prior in range(max(0, index - 2), index))
        if not double_negated:
            return True
        return False
    return has_negation and has_truth_or_reporting


def declarative_has_colon_before(assertion_start, colon_before=None):
    if not colon_before:
        return False
    upper = min(assertion_start, len(colon_before) - 1)
    return any(colon_before[boundary]
               for boundary in range(upper, 0, -1))


def declarative_frame_denies_normative_basis(frame):
    normative_prefixes = ('regr', 'norm', 'previs', 'disposit', 'fundament')
    articles_or_quantifiers = {
        'a', 'o', 'algum', 'alguma', 'qualquer', 'um', 'uma'}
    for index, token in enumerate(frame):
        if token not in {'nao', 'nunca', 'jamais'}:
            continue
        if index + 1 >= len(frame):
            continue
        next_token = frame[index + 1]
        if (next_token != 'ha' and
                not semantic_token_has_any_prefix(next_token, 'exist')):
            continue
        basis_index = index + 2
        if (basis_index < len(frame) and
                frame[basis_index] in {'apenas', 'somente', 'so'}):
            continue
        if (basis_index < len(frame) and
                frame[basis_index] in articles_or_quantifiers):
            basis_index += 1
        if (basis_index < len(frame) and
                semantic_token_has_any_prefix(
                    frame[basis_index], *normative_prefixes)):
            return True
    return False


def declarative_occurrence_locally_negated(
        tokens, start, width, negative_tokens, comma_before=None):
    left = declarative_negation_scope_left(start, 2, comma_before)
    right = min(len(tokens), start + width + 1)
    for boundary in range(start + width, right):
        if (comma_before is not None and
                boundary < len(comma_before) and
                comma_before[boundary]):
            right = boundary
            break
    for index in range(left, right):
        if start <= index < start + width:
            continue
        if declarative_token_negates_assertion(
                tokens, index, negative_tokens):
            return True
    return False


def declarative_occurrence_negated_before(
        tokens, start, negative_tokens, comma_before=None):
    left = declarative_negation_scope_left(start, 3, comma_before)
    for index in range(start - 1, left - 1, -1):
        if tokens[index] in {
                'e', 'mas', 'porem', 'contudo', 'todavia', 'entretanto',
                'ou'}:
            return False
        if declarative_token_negates_assertion(
                tokens, index, negative_tokens):
            return True
    return False


def declarative_negation_scope_left(
        assertion_start, max_lookback, comma_before=None):
    left = max(0, assertion_start - max_lookback)
    scope_start = declarative_comma_scope_start(
        assertion_start, comma_before)
    if scope_start > left:
        return scope_start
    return left


def declarative_comma_scope_start(assertion_start, comma_before=None):
    if not comma_before:
        return 0
    upper = min(assertion_start, len(comma_before) - 1)
    for boundary in range(upper, 0, -1):
        if comma_before[boundary]:
            return boundary
    return 0


def declarative_token_negates_assertion(tokens, index, negative_tokens):
    token = tokens[index]
    if semantic_token_has_any_prefix(
            token, 'fals', 'incorret', 'errad', 'equivoc', 'inverid'):
        if any(tokens[prior] == 'nao'
               for prior in range(max(0, index - 2), index)):
            return False
    next_token = tokens[index + 1] if index + 1 < len(tokens) else ''
    if token == 'nao' and next_token in {
            'obstante', 'apenas', 'somente', 'so'}:
        return False
    if token == 'sem' and next_token in {
            'duvida', 'controversia', 'prejuizo'}:
        return False
    return (token in negative_tokens or semantic_token_has_any_prefix(
        token, 'fals', 'incorret', 'errad', 'inaplic'))


