def tributario13_article_clause_associates(clause, article_suffix, *concepts):
    tokens = clause.split()
    for index in range(len(tokens) - 2):
        if (tokens[index] not in {'art', 'artigo'} or
                tokens[index + 1] != '12' or
                tokens[index + 2] != article_suffix):
            continue
        end = len(tokens)
        for next_index in range(index + 3, len(tokens)):
            if tokens[next_index] in {'art', 'artigo'}:
                end = next_index
                break
        segment = ' '.join(tokens[index + 3:end])
        if any(concept in segment for concept in concepts):
            return True
    return False


def semantic_tributario13_stale_assertion(intent, visible):
    """Reject materially stale advice independently of one exact wording."""
    for clause in semantic_legal_fact_clauses(visible):
        meta_negated = lambda *anchors: semantic_anchor_meta_negated(
            clause, *anchors)
        if intent == 'trib-irpf-isencao-unico-imovel-440':
            if ('doacao' in clause and
                    any(part in clause for part in ('quinquenio', 'cinco anos')) and
                    any(part in clause for part in (
                        'nao afeta', 'nao interfere', 'nao altera',
                        'e irrelevante')) and
                    any(part in clause for part in (
                        'isencao', 'carencia', 'beneficio')) and
                    not meta_negated('doacao')):
                return True
        elif intent == 'trib-irpf-isencao-180-dias-outro-imovel':
            if (any(part in clause for part in ('contagem', 'prazo')) and
                    any(part in clause for part in (
                        'comeca', 'inicia', 'passa a contar')) and
                    any(part in clause for part in (
                        'termina de pagar', 'pagamento integral',
                        'recebimento integral', 'preco integral',
                        'quitacao do preco')) and
                    not meta_negated('contagem', 'prazo')):
                return True
        elif intent == 'trib-irpf-fatores-reducao-imovel-antigo':
            if (any(part in clause for part in (
                    'heranca', 'sucessao', 'causa mortis')) and
                    any(part in clause for part in (
                        'desfaz', 'elimina', 'perde', 'desconsidera')) and
                    any(part in clause for part in ('atualizacao', 'rearp')) and
                    not meta_negated('heranca', 'sucessao', 'causa mortis')):
                return True
        elif intent == 'trib-irpf-ganho-capital-venda-parcelada':
            if (any(part in clause for part in (
                    'tributo inteiro', 'imposto inteiro', 'imposto integral',
                    'todo o imposto', 'todo imposto')) and
                    any(part in clause for part in (
                        'recolhido', 'pago', 'vence', 'devido')) and
                    any(part in clause for part in (
                        'assinatura do contrato', 'assinar o contrato',
                        'celebracao do contrato', 'mes seguinte a alienacao')) and
                    not meta_negated(
                        'tributo inteiro', 'imposto inteiro',
                        'imposto integral', 'todo o imposto', 'todo imposto')):
                return True
        elif intent == 'trib-irpf-permuta-imoveis':
            no_cash = any(part in clause for part in (
                'sem diferenca em dinheiro', 'sem torna', 'sem dinheiro'))
            taxed = any(part in clause for part in (
                'e tributada', 'fica tributada', 'sujeita ao imposto',
                'incide imposto', 'tem ganho de capital'))
            denied = any(part in clause for part in (
                'nao e tributada', 'nao fica tributada', 'nao fica sujeita',
                'nao se sujeita', 'nao incide', 'nao tem ganho'))
            if (no_cash and taxed and not denied and
                    not meta_negated('troca de imoveis', 'permuta')):
                return True
        elif intent == 'trib-irpf-venda-carro-usado':
            independent = any(part in clause for part in (
                'cada qual', 'cada um', 'limite proprio', 'limites proprios',
                'limite independente', 'limites independentes'))
            denied = any(part in clause for part in (
                'nao tem limite', 'nao possuem limite', 'devem ser somados',
                'precisam ser somados'))
            if (all(part in clause for part in ('carro', 'moto', '35 mil')) and
                    independent and not denied and
                    not meta_negated('carro e moto')):
                return True
        elif intent == 'trib-irpf-carne-leao-aluguel':
            if (any(part in clause for part in (
                    'administradora', 'imobiliaria', 'administrad')) and
                    any(part in clause for part in (
                        'so e recebido', 'somente e recebido',
                        'apenas e recebido')) and
                    any(part in clause for part in (
                        'chega ao dono', 'chega ao locador',
                        'repasse ao locador', 'repasse ao proprietario')) and
                    not meta_negated('aluguel')):
                return True
        elif intent == 'trib-irpf-carne-leao-atrasado-multa-isolada':
            if (any(part in clause for part in (
                    'dirpf', 'declaracao anual', 'ajuste anual')) and
                    any(part in clause for part in (
                        'penalidade', 'multa isolada', 'multa de 50')) and
                    any(part in clause for part in (
                        'afasta', 'elimina', 'apaga', 'cancela',
                        'impede a cobranca')) and
                    not meta_negated('dirpf', 'declaracao anual',
                                     'ajuste anual')):
                return True
        elif intent == 'trib-irpf-aluguel-imobiliaria-dimob':
            if ('entreg' in clause and
                    any(part in clause for part in (
                        'locador pessoa fisica',
                        'proprietario pessoa fisica')) and
                    not any(part in clause for part in (
                        'nao entrega', 'nao deve entregar',
                        'nao e entregue')) and
                    not meta_negated('entregue', 'entrega', 'entregar')):
                return True
        elif intent == 'trib-irpf-pensao-recebida-isenta':
            if ('pensao' in clause and
                    any(part in clause for part in (
                        'tributavel', 'tributada', 'sofre imposto',
                        'incide imposto')) and
                    any(part in clause for part in ('mensal', 'carne leao')) and
                    not any(part in clause for part in (
                        'nao e tributavel', 'nao e tributada',
                        'nao sofre imposto', 'nao incide imposto',
                        'sem carne leao')) and
                    not meta_negated('pensao')):
                return True
        elif intent == 'trib-irpf-rra-acao-judicial':
            if (tributario13_article_clause_associates(
                    clause, 'a', 'mesmo ano', 'proprio ano',
                    'ano do recebimento') and
                    tributario13_article_clause_associates(
                        clause, 'b', 'anos anteriores',
                        'anos calendario anteriores', 'atrasados') and
                    not meta_negated('art 12 a', 'artigo 12 a')):
                return True
        elif intent == 'trib-irpf-espolio-declaracao-falecido':
            affirmative_channel = any(part in clause for part in (
                'consegue criar', 'pode criar', 'pode ser criada',
                'permite criar', 'criar pelo celular',
                'criada pelo celular'))
            denied_channel = any(part in clause for part in (
                'nao consegue criar', 'nao pode criar',
                'nao pode ser criada', 'nao permite criar'))
            if (all(part in clause for part in ('declaracao final', '2026')) and
                    any(part in clause for part in (
                        'celular', 'aplicativo',
                        'meu imposto de renda on line')) and
                    affirmative_channel and not denied_channel and
                    not meta_negated('declaracao final')):
                return True
        elif intent == 'trib-irpf-deducao-educacao-limite':
            if (any(part in clause for part in (
                    'aproveit', 'transfer', 'complet', 'compens',
                    'redistrib')) and
                    any(part in clause for part in (
                        'saldo', 'excedente', 'limite')) and
                    any(part in clause for part in (
                        'outro filho', 'outro dependente', 'outro familiar',
                        'outra pessoa')) and
                    not any(part in clause for part in (
                        'nao pode', 'nao e possivel', 'nao vai',
                        'nao permite', 'nao autoriza', 'nao se transfere')) and
                    not meta_negated(
                        'aproveitar', 'transferir', 'completar', 'compensar',
                        'redistribuir')):
                return True
    return False


def stale_tributario13_assertion(intent, visible):
    rule = TRIBUTARIO13_STALE_RULES.get(intent)
    if not rule:
        return None
    code, alternatives = rule
    if any(declarative_alternative_affirmed_in_text(visible, alternative)
           for alternative in alternatives):
        return code
    if semantic_tributario13_stale_assertion(intent, visible):
        return code
    return None


