def semantic_criminal13_stale_assertion(intent, visible):
    for clause in semantic_legal_fact_clauses(visible):
        if criminal13_clause_explicitly_nonaffirming(clause):
            continue
        says = lambda *terms: any(term in clause for term in terms)
        meta_negated = lambda *anchors: criminal13_anchor_nonaffirming(
            clause, *anchors)
        if intent == 'crim-bo-online-quando-serve':
            national = says(
                'todos os estados', 'qualquer estado', 'todo o pais',
                'nacionalmente')
            universal = (says('todos os crimes', 'qualquer crime',
                              'toda ocorrencia') and
                         says('aceita', 'admite', 'resolve') and
                         not says('nao aceita', 'nao admite', 'nao resolve'))
            replaces = (says('dispensa', 'substitui',
                             'elimina a necessidade') and
                        says('atendimento presencial', 'exame pericial',
                             'emergencia') and
                        not says('nao dispensa', 'nao substitui',
                                 'nao elimina a necessidade'))
            if ('bo' in clause and (national and universal or replaces) and
                    not meta_negated('bo online', 'boletim eletronico')):
                return True
        elif intent == 'crim-representar-prazo-decadencial':
            if (says('violencia domestica', 'ambito domestico') and
                    'seis meses' in clause and
                    says('continua', 'permanece', 'prazo e', 'aplica se') and
                    'doze meses' not in clause and
                    not says('nao continua', 'nao permanece',
                             'nao se aplica') and
                    not meta_negated('seis meses')):
                return True
        elif intent == 'crim-retratar-representacao':
            wrong_offer = (
                says('violencia domestica', 'lei maria da penha') and
                says('oferecimento da denuncia', 'denuncia oferecida') and
                says('ate', 'antes', 'limite') and
                not says('recebimento', 'recebida') and
                not says('nao basta', 'nao e suficiente', 'nao se limita',
                         'limite nao e antes', 'nao tem como limite'))
            no_request = (
                'audiencia' in clause and 'retrat' in clause and
                says('sem pedido', 'sem manifestacao', 'de oficio',
                     'independentemente da vontade') and
                not says('nao pode ser marcada sem',
                         'nao pode ser designada sem', 'nao ocorre sem',
                         'nao se realiza sem', 'nao e realizada sem'))
            if ((wrong_offer or no_request) and
                    not meta_negated('retratacao', 'audiencia')):
                return True
        elif intent == 'crim-crime-acao-publica-ou-privada':
            always_unconditional = (
                'estelionato' in clause and 'incondicionad' in clause and
                says('sempre', 'em qualquer caso', 'como regra') and
                not says('nao e sempre', 'nao e a regra',
                         'nao e como regra', 'nao e em regra',
                         'nao e incondicionado como regra', 'excecoes'))
            public_blanket = (
                'estelionato' in clause and
                says('qualquer ente publico',
                     'qualquer pessoa juridica de direito publico',
                     'toda pessoa juridica publica') and
                'incondicionad' in clause and
                not says('nao e qualquer ente publico',
                         'nem qualquer ente publico',
                         'nao e qualquer pessoa juridica'))
            if ((always_unconditional or public_blanket) and
                    not meta_negated('estelionato')):
                return True
        elif intent == 'crim-delegacia-nao-registrou-bo':
            if (says('acao privada', 'crime privado') and
                    'policia' in clause and
                    says('nao pode investigar', 'nao cabe inquerito',
                         'deve recusar o registro') and
                    not meta_negated('acao privada', 'crime privado')):
                return True
        elif intent == 'crim-acompanhar-andamento-inquerito':
            absolute_victim = (
                'vitima' in clause and
                says('acesso irrestrito', 'acesso integral') and
                says('todas as diligencias', 'qualquer diligencia',
                     'atos em andamento') and
                not says('nao tem acesso irrestrito',
                         'nao tem acesso integral',
                         'nao possui acesso irrestrito',
                         'nao possui acesso integral',
                         'sem acesso irrestrito', 'sem acesso integral'))
            barred_lawyer = (
                'advogado' in clause and 'sigilo' in clause and
                says('impede qualquer acesso', 'proibe o acesso',
                     'veda o acesso') and 'documentad' in clause and
                not says('nao impede qualquer acesso',
                         'nao proibe o acesso', 'nao veda o acesso'))
            if ((absolute_victim or barred_lawyer) and
                    not meta_negated('acesso', 'sigilo')):
                return True
        elif intent == 'crim-assistente-de-acusacao':
            no_autonomy = (
                'assistente' in clause and
                says('sem autonomia', 'deve repetir', 'obrigado a seguir') and
                'ministerio publico' in clause and
                not says('nao esta sem autonomia', 'nao e sem autonomia',
                         'nao deve repetir', 'nao e obrigado a seguir'))
            no_appeal = (
                'assistente' in clause and 'recorr' in clause and
                says('nao pode', 'nunca pode', 'e proibido'))
            if ((no_autonomy or no_appeal) and
                    not meta_negated('assistente', 'recurso')):
                return True
        elif intent == 'crim-direitos-da-vitima-no-processo':
            if ('vitima' in clause and
                    says('nao precisa ser comunicada',
                         'nao tem direito a comunicacao') and
                    says('soltura', 'audiencia', 'sentenca') and
                    not meta_negated('vitima')):
                return True
        elif intent == 'crim-vitima-discorda-do-arquivamento':
            judicial = (
                'arquivamento' in clause and
                says('homologado pelo juiz', 'revisado pelo juiz',
                     'revisao judicial obrigatoria') and
                not says('antes era homologado pelo juiz',
                         'antes era revisado pelo juiz',
                         'regra anterior', 'modelo anterior'))
            no_new_evidence = (
                'arquivad' in clause and
                says('nunca pode ser reaberto', 'jamais pode ser reaberto') and
                'prova nova' in clause)
            if ((judicial or no_new_evidence) and
                    not meta_negated('arquivamento')):
                return True
        elif intent in {
                'crim-calunia-difamacao-injuria',
                'crim-difamacao-nas-redes'}:
            requires_falsity = (
                'difamacao' in clause and 'fals' in clause and
                says('exige', 'depende', 'so existe', 'pressupoe') and
                not says('nao exige', 'nao depende', 'nao integra') and
                not meta_negated('difamacao'))
            if (requires_falsity and
                    not says('nao a difamacao', 'mas nao a difamacao',
                             'e nao a difamacao',
                             'diferentemente da difamacao')):
                return True
            if intent == 'crim-calunia-difamacao-injuria':
                noncriminal_only = (
                    'difamacao' in clause and
                    says('fato nao e criminoso', 'fato nao pode ser crime',
                         'somente fato nao criminoso',
                         'so abrange fato nao criminoso',
                         'fato criminoso sempre configura calunia') and
                    not says('fato nao precisa ser crime',
                             'nao exige fato criminoso'))
                if noncriminal_only and not meta_negated('difamacao'):
                    return True
        elif intent == 'crim-como-processar-quem-me-ofendeu':
            if ('queixa' in clause and says('boletim', 'bo') and
                    says('substitui', 'dispensa') and
                    not says('nao substitui', 'nao dispensa') and
                    not meta_negated('queixa crime')):
                return True
        elif intent == 'crim-xingamento-racial-injuria-ou-racismo':
            if (says('art 2 a', 'artigo 2 a') and
                    'religiao' in clause and
                    says('inclui', 'abrange', 'contem', 'tambem pune') and
                    not says('nao inclui', 'nao abrange', 'nao contem') and
                    not meta_negated('art 2 a', 'artigo 2 a')):
                return True
        elif intent == 'crim-retratacao-encerra-ofensa':
            injury_benefit = (
                'injuria' in clause and 'retrat' in clause and
                says('isenta', 'extingue', 'encerra', 'apaga') and
                not says('nao isenta', 'nao extingue', 'nao encerra',
                         'nao apaga', 'nao alcanca a injuria',
                         'nao vale para injuria', 'nao inclui a injuria',
                         'nao a injuria'))
            automatic_medium = (
                says('mesmo meio', 'mesmos meios') and
                'retrat' in clause and
                says('automaticamente', 'independentemente de pedido',
                     'sem pedido') and
                not says('nao automaticamente', 'somente a pedido',
                         'a pedido do ofendido', 'mediante pedido'))
            false_admission = (
                'difamacao' in clause and
                says('reconhece que o fato nao e verdadeiro',
                     'reconhecer que o fato nao e verdadeiro',
                     'admite que o fato era falso', 'confessa que mentiu') and
                not says('nao exige', 'nao pressupoe', 'sem confessar',
                         'nao significa', 'nao quer dizer'))
            if ((injury_benefit or automatic_medium or false_admission) and
                    not meta_negated('retratacao', 'injuria', 'difamacao')):
                return True
        elif intent == 'crim-excecao-da-verdade':
            universal_defamation = (
                'difamacao' in clause and 'excecao da verdade' in clause and
                says('sempre cabe', 'qualquer pessoa', 'em todo caso') and
                not says('nao cabe em todo caso',
                         'nao se admite em todo caso',
                         'nao vale contra qualquer pessoa'))
            injury_truth = (
                'injuria' in clause and 'excecao da verdade' in clause and
                says('admite', 'permite', 'cabe') and
                not says('nao admite', 'nao permite', 'nao cabe'))
            if ((universal_defamation or injury_truth) and
                    not meta_negated('excecao da verdade')):
                return True
        elif intent == 'crim-homofobia-e-crime':
            autonomous = (
                'ado 26' in clause and says('criou', 'instituiu') and
                says('tipo penal autonomo', 'crime autonomo') and
                not says('nao criou', 'nao instituiu'))
            any_speech = (
                says('qualquer fala', 'toda critica', 'qualquer critica') and
                says('homofob', 'sexualidade', 'identidade de genero') and
                'crime' in clause and
                not says('nao e crime', 'nem toda critica',
                         'nem qualquer critica', 'nem qualquer fala',
                         'nao transforma qualquer fala'))
            if ((autonomous or any_speech) and
                    not meta_negated('ado 26', 'qualquer fala',
                                     'toda critica')):
                return True
        elif intent == 'crim-intolerancia-religiosa':
            if (says('qualquer critica', 'discordar de dogmas',
                     'criticar instituicoes religiosas') and
                    says('e crime', 'configura crime', 'sempre e crime') and
                    not says('nao e crime', 'nao configura crime') and
                    not meta_negated('critica', 'discordar')):
                return True
    return False


CRIMINAL13_HISTORICAL_ASSERTION_MARKERS = (
    ('regra', 'revogada', 'dizia'),
    ('regra', 'antiga', 'dizia'),
    ('entendimento', 'superado', 'dizia'),
    ('texto', 'historico', 'afirmava'),
    ('historicamente', 'se', 'afirmava'),
    ('antes', 'se', 'afirmava'),
    ('sob', 'a', 'regra', 'anterior'),
    ('na', 'regra', 'anterior'),
)


def criminal13_occurrence_historically_framed(tokens, assertion_start):
    for marker in CRIMINAL13_HISTORICAL_ASSERTION_MARKERS:
        width = len(marker)
        for start in range(assertion_start - width + 1):
            if (tuple(tokens[start:start + width]) == marker and
                    assertion_start - (start + width) <= 3):
                return True
    return False


def criminal13_clause_explicitly_nonaffirming(clause):
    tokens = clause.split()
    for marker in CRIMINAL13_HISTORICAL_ASSERTION_MARKERS:
        width = len(marker)
        for start in range(min(2, len(tokens) - width) + 1):
            if tuple(tokens[start:start + width]) == marker:
                return True
    leading_meta_markers = (
        ('e', 'falso', 'que'),
        ('nao', 'e', 'verdade', 'que'),
        ('e', 'incorreto', 'afirmar', 'que'),
        ('nao', 'procede', 'que'),
    )
    for marker in leading_meta_markers:
        width = len(marker)
        if tuple(tokens[:width]) != marker:
            continue
        remainder = tokens[width:]
        for index, token in enumerate(remainder):
            if token in {'porque', 'pois', 'embora', 'enquanto'}:
                return False
            if (token == 'ja' and index + 1 < len(remainder) and
                    remainder[index + 1] == 'que'):
                return False
        return True
    return False


def criminal13_alternative_historically_framed(tokens, alternative_tokens):
    seen = False
    width = len(alternative_tokens)
    for start in range(len(tokens) - width + 1):
        if tokens[start:start + width] != alternative_tokens:
            continue
        seen = True
        if not criminal13_occurrence_historically_framed(tokens, start):
            return False
    return seen


def criminal13_declarative_alternative_affirmed_in_text(
        visible, alternative):
    alternative_tokens = re.sub(
        r'[^a-z0-9]+', ' ', norm_key(alternative)).split()
    if not alternative_tokens:
        return False
    width = len(alternative_tokens)
    for tokens, comma_before, colon_before in semantic_declarative_legal_fact_clauses(
            visible):
        masked = list(tokens)
        for start in range(len(tokens) - width + 1):
            if (tokens[start:start + width] != alternative_tokens or
                    not criminal13_occurrence_historically_framed(
                        tokens, start)):
                continue
            masked[start:start + width] = ['criminal13historical'] * width
        if declarative_alternative_affirmed(
                masked, alternative, comma_before, colon_before):
            return True
    return False


def criminal13_anchor_nonaffirming(clause, *alternatives):
    if semantic_anchor_meta_negated(clause, *alternatives):
        return True
    tokens = clause.split()
    for alternative in alternatives:
        alternative_tokens = re.sub(
            r'[^a-z0-9]+', ' ', norm_key(alternative)).split()
        if (alternative_tokens and
                criminal13_alternative_historically_framed(
                    tokens, alternative_tokens)):
            return True
    return False


def criminal13_stale_alternative_affirmed(visible, alternative):
    return criminal13_declarative_alternative_affirmed_in_text(
        visible, alternative)


def stale_criminal13_assertion(intent, visible):
    rule = CRIMINAL13_STALE_RULES.get(intent)
    if not rule:
        return None
    code, alternatives = rule
    if any(criminal13_stale_alternative_affirmed(visible, alternative)
           for alternative in alternatives):
        return code
    if semantic_criminal13_stale_assertion(intent, visible):
        return code
    return None


def current_criminal13_legal_fact_reasons(page, intent, visible):
    reasons = []
    for wanted_url, code in CRIMINAL13_SOURCE_REQUIREMENTS.get(intent, ()):
        if not has_exact_official_source_url(page, wanted_url):
            reasons.append('current_legal_fact_source_missing:' + code)
    rule = CRIMINAL13_OUTCOME_RULES.get(intent)
    if not rule:
        return reasons
    outcome_code, outcome_groups = rule
    if any(not any(criminal13_declarative_alternative_affirmed_in_text(
            visible, alternative) for alternative in alternatives)
            for alternatives in outcome_groups):
        reasons.append('current_legal_fact_outcome_missing:' + outcome_code)
    stale_code = stale_criminal13_assertion(intent, visible)
    if stale_code:
        reasons.append('current_legal_fact_stale_assertion:' + stale_code)
    return reasons


