def has_aereo01_official_path(page, hosts, wanted_path):
    allowed_hosts = {host.lower() for host in hosts}
    for source in page.get('official_sources') or []:
        raw_url = (source.get('url') or '').strip()
        try:
            parsed = urllib.parse.urlsplit(raw_url)
            port = parsed.port
        except ValueError:
            continue
        decoded_path = urllib.parse.unquote(parsed.path)
        if (parsed.scheme.lower() != 'https' or parsed.username is not None or
                parsed.password is not None or port not in (None, 443) or
                (parsed.hostname or '').lower() not in allowed_hosts or
                '%' in parsed.path or parsed.query or
                raw_url.split('#', 1)[0].endswith('?') or
                posixpath.normpath(decoded_path) != decoded_path or
                decoded_path != wanted_path):
            continue
        return True
    return False


def aereo_source_endpoint_matches(raw_url, reference_url):
    """Match a blacklisted endpoint despite query/fragment/path variants."""
    try:
        parsed = urllib.parse.urlsplit((raw_url or '').strip())
        reference = urllib.parse.urlsplit(reference_url)
        port = parsed.port
    except (TypeError, ValueError):
        return False
    if (parsed.scheme.lower() != 'https' or port not in (None, 443) or
            (parsed.hostname or '').lower() !=
            (reference.hostname or '').lower()):
        return False
    decoded_path = '/' + urllib.parse.unquote(parsed.path).lstrip('/')
    reference_path = '/' + urllib.parse.unquote(reference.path).lstrip('/')
    return (posixpath.normpath(decoded_path) ==
            posixpath.normpath(reference_path))


def has_aereo_revoked_resolution400_cef_source(page):
    for source in page.get('official_sources') or []:
        raw_url = source.get('url') or ''
        if any(aereo_source_endpoint_matches(raw_url, reference) for reference
               in (AEREO01_RESOLUTION_400_CEF_URL,
                   AEREO01_RESOLUTION_400_CEF_2019_URL)):
            return True
    return False


