def has_aereo02_source_kind(page, kind):
    if kind in {
            'res400_current', 'res400_article12', 'res400_article20',
            'res400_article21',
            'res400_article27', 'res400_article28', 'res400_article29',
            'res400_article30', 'res400_article31'}:
        # Texto compilado vivo da ANAC, atualizado em 04/05/2026. Os CEFs
        # são históricos e a Portaria 8.018/2022 foi revogada em 28/04/2026.
        return has_exact_official_source_url(
            page, AEREO02_RESOLUTION_400_CURRENT_URL)
    exact_sources = {
        'cba': AEREO02_CBA_CAMARA_URL,
        'cdc': AEREO02_CDC_CAMARA_URL,
        'cc': AEREO02_CC_CAMARA_URL,
        'recovery_law': AEREO02_RECOVERY_LAW_CAMARA_URL,
        'stj_delay_damage': AEREO02_STJ_DELAY_DAMAGE_URL,
        'stj_intermediary': AEREO02_STJ_INTERMEDIARY_URL,
        'stj_downgrade': AEREO02_STJ_DOWNGRADE_URL,
        'stj_recovery_tema1051': AEREO02_STJ_RECOVERY_TEMA1051_URL,
        'stj_recovery_plan': AEREO02_STJ_RECOVERY_PLAN_URL,
        'tema1417': AEREO02_TEMA1417_TJSP_URL,
        'stj_error_fare': AEREO02_STJ_ERROR_FARE_DECISION_URL,
    }
    if kind not in exact_sources:
        raise ValueError('unknown aereo-02 source kind: ' + kind)
    return has_exact_official_source_url(page, exact_sources[kind])


def has_aereo02_wrong_downgrade_source(page):
    for source in page.get('official_sources') or []:
        raw_url = source.get('url') or ''
        if not aereo_source_endpoint_matches(
                raw_url, AEREO02_STJ_WRONG_DOWNGRADE_URL):
            continue
        try:
            pairs = urllib.parse.parse_qsl(
                urllib.parse.urlsplit(raw_url).query,
                keep_blank_values=True)
        except ValueError:
            continue
        for key, value in pairs:
            normalized = re.sub(r'''[\s'"]+''', '', value).upper()
            if (key.strip().lower() == 'livre' and normalized in
                    {'@CNOT=021575', 'CNOT=021575'}):
                return True
    return False


def current_aereo02_legal_fact_reasons(page, intent, visible):
    reasons = []
    if intent not in AEREO02_INTENTS:
        return reasons
    for kind, code in AEREO02_SOURCE_REQUIREMENTS[intent]:
        if not has_aereo02_source_kind(page, kind):
            reasons.append('current_legal_fact_source_missing:' + code)
    if has_aereo_revoked_resolution400_cef_source(page):
        reasons.append(
            'current_legal_fact_source_stale:'
            'anac_resolution_400_revoked_cef')
    if (intent == 'aer-reacomodacao-classe-inferior-downgrade' and
            has_aereo02_wrong_downgrade_source(page)):
        reasons.append(
            'current_legal_fact_source_stale:'
            'stj_cnot_021575_unrelated_crypto_precedent')
    outcome_code, outcome_groups = AEREO02_OUTCOME_RULES[intent]
    if any(not any(criminal13_declarative_alternative_affirmed_in_text(
            visible, alternative) for alternative in alternatives)
            for alternatives in outcome_groups):
        reasons.append('current_legal_fact_outcome_missing:' + outcome_code)
    for stale_code, alternatives in AEREO02_STALE_RULES:
        if any(criminal13_stale_alternative_affirmed(
                visible, alternative) for alternative in alternatives):
            reasons.append(
                'current_legal_fact_stale_assertion:' + stale_code)
    return reasons


