def aereo03_source_metadata(page, wanted_url):
    for source in page.get('official_sources') or []:
        if (source.get('url') or '').strip() != wanted_url:
            continue
        return ' '.join((source.get('name') or '',
                         source.get('anchor_claim') or '')).strip()
    return ''


def aereo03_metadata_has_groups(metadata, groups):
    clauses = [metadata]
    clauses.extend(
        clause.strip() for clause in re.split(r'[,;\n]', metadata or '')
        if clause.strip())

    def affirmed(alternative):
        return any(criminal13_declarative_alternative_affirmed_in_text(
            clause, alternative) for clause in clauses)

    return all(any(affirmed(alternative) for alternative in alternatives)
               for alternatives in groups)


def aereo03_source_anchor_reasons(page, kind):
    rule = AEREO03_SOURCE_ANCHOR_RULES.get(kind)
    if not rule:
        return []
    code, groups = rule
    wanted = {
        'anac_des_decision': AEREO03_DES_CONVERSION_DECISION_URL,
        'stj_resp750128': AEREO03_STJ_RESP750128_URL,
        'smaller_aircraft_decision':
            AEREO03_SMALLER_AIRCRAFT_DECISION_URL,
        'rbac121_emd25': AEREO03_RBAC121_EMD25_URL,
        'rbac108_emd08': AEREO03_RBAC108_EMD08_URL,
        'rbac108_emd10': AEREO03_RBAC108_EMD10_URL,
    }[kind]
    metadata = aereo03_source_metadata(page, wanted)
    if not metadata or not aereo03_metadata_has_groups(metadata, groups):
        return ['current_legal_fact_source_anchor_missing:' + code]
    return []


def has_aereo03_source_kind(page, kind):
    exact_sources = {
        'res400_current': AEREO03_RESOLUTION_400_CURRENT_URL,
        'res280': AEREO03_RESOLUTION_280_CURRENT_URL,
        'anacpedia_overbooking': AEREO03_ANACPEDIA_OVERBOOKING_URL,
        'cdc': AEREO03_CDC_CAMARA_URL,
        'anac_des_decision': AEREO03_DES_CONVERSION_DECISION_URL,
        'bcb_converter': AEREO03_BCB_CONVERTER_URL,
        'passenger_cartilha': AEREO03_PASSENGER_CARTILHA_URL,
        'stj_resp750128': AEREO03_STJ_RESP750128_URL,
        'document_guide': AEREO03_DOCUMENT_GUIDE_URL,
        'cnh_guide': AEREO03_CNH_GUIDE_URL,
        'electronic_documents': AEREO03_ELECTRONIC_DOCUMENTS_URL,
        'anac_passenger_service': AEREO03_ANAC_PASSENGER_SERVICE_URL,
        'smaller_aircraft_decision':
            AEREO03_SMALLER_AIRCRAFT_DECISION_URL,
        'cba': AEREO03_CBA_CAMARA_URL,
        'res800': AEREO03_RESOLUTION_800_URL,
        'rbac121_emd25': AEREO03_RBAC121_EMD25_URL,
        'rbac108_emd08': AEREO03_RBAC108_EMD08_URL,
        'rbac108_emd10': AEREO03_RBAC108_EMD10_URL,
        'res799': AEREO03_RESOLUTION_799_URL,
    }
    if kind not in exact_sources:
        raise ValueError('unknown aereo-03 source kind: ' + kind)
    return has_exact_official_source_url(page, exact_sources[kind])


def aereo03_stale_source_reasons(page):
    checks = (
        (AEREO03_RESOLUTION_400_CEF_URL,
         'anac_resolution_400_revoked_cef'),
        (AEREO03_RESOLUTION_400_CEF_2019_URL,
         'anac_resolution_400_revoked_cef'),
        (AEREO03_RESOLUTION_130_REVOKED_URL,
         'anac_resolution_130_revoked'),
    )
    found = []
    for source in page.get('official_sources') or []:
        raw_url = source.get('url') or ''
        canonical = urllib.parse.unquote(raw_url).lower()
        if ('copy_of_anac-passageiro' in canonical and
                'anac_passenger_obsolete_copy_endpoint' not in found):
            found.append('anac_passenger_obsolete_copy_endpoint')
        if ('400-0026' in canonical and
                'anac_unrelated_decision_400_0026' not in found):
            found.append('anac_unrelated_decision_400_0026')
        for reference, code in checks:
            if (aereo_source_endpoint_matches(raw_url, reference) and
                    code not in found):
                found.append(code)
    return found


def aereo03_evaluation_date(value=None):
    if value is None:
        return AEREO03_DIRECT_VALIDATOR_SNAPSHOT_DATE
    if isinstance(value, datetime.datetime):
        if value.tzinfo is None:
            value = value.replace(tzinfo=AEREO03_LEGAL_TIMEZONE)
        return value.astimezone(AEREO03_LEGAL_TIMEZONE).date()
    if isinstance(value, datetime.date):
        return value
    if isinstance(value, str):
        return datetime.date.fromisoformat(value)
    raise TypeError('aereo-03 evaluation date must be date or ISO date')


def aereo03_source_requirements_as_of(intent, evaluation_date=None):
    date_value = aereo03_evaluation_date(evaluation_date)
    requirements = list(AEREO03_SOURCE_REQUIREMENTS[intent])
    temporal = (
        AEREO03_PRE_CUTOFF_SOURCE_REQUIREMENTS if
        date_value < AEREO03_TRANSITION_CUTOFF else
        AEREO03_POST_CUTOFF_SOURCE_REQUIREMENTS)
    requirements.extend(temporal.get(intent, ()))
    return tuple(requirements)


def current_aereo03_legal_fact_reasons(
        page, intent, visible, evaluation_date=None):
    reasons = []
    if intent not in AEREO03_INTENTS:
        return reasons
    date_value = aereo03_evaluation_date(evaluation_date)
    for kind, code in aereo03_source_requirements_as_of(intent, date_value):
        if not has_aereo03_source_kind(page, kind):
            reasons.append('current_legal_fact_source_missing:' + code)
            continue
        reasons.extend(aereo03_source_anchor_reasons(page, kind))
    for code in aereo03_stale_source_reasons(page):
        reasons.append('current_legal_fact_source_stale:' + code)
    outcome_rules = AEREO03_OUTCOME_RULES.get(intent)
    if outcome_rules:
        outcome_code, outcome_groups = outcome_rules
        if any(not any(criminal13_declarative_alternative_affirmed_in_text(
                visible, alternative) for alternative in alternatives)
                for alternatives in outcome_groups):
            reasons.append('current_legal_fact_outcome_missing:' + outcome_code)
    for stale_code, alternatives in AEREO03_STALE_RULES:
        scope = AEREO03_STALE_RULE_INTENTS.get(stale_code, frozenset())
        if scope and intent not in scope:
            continue
        if any(criminal13_stale_alternative_affirmed(
                visible, alternative) for alternative in alternatives):
            reasons.append(
                'current_legal_fact_stale_assertion:' + stale_code)

    temporal_rules = None
    temporal_stale_rules = ()
    if date_value < AEREO03_TRANSITION_CUTOFF:
        temporal_rules = AEREO03_PRE_CUTOFF_OUTCOME_RULES.get(intent)
        if temporal_rules:
            temporal_stale_rules = AEREO03_PRE_CUTOFF_STALE_RULES
    else:
        temporal_rules = AEREO03_POST_CUTOFF_OUTCOME_RULES.get(intent)
        if temporal_rules:
            temporal_stale_rules = AEREO03_POST_CUTOFF_STALE_RULES
    if temporal_rules:
        temporal_code, temporal_groups = temporal_rules
        if any(not any(criminal13_declarative_alternative_affirmed_in_text(
                visible, alternative) for alternative in alternatives)
                for alternatives in temporal_groups):
            reasons.append(
                'current_legal_fact_outcome_missing:' + temporal_code)
    for stale_code, alternatives in temporal_stale_rules:
        if any(criminal13_stale_alternative_affirmed(
                visible, alternative) for alternative in alternatives):
            reasons.append(
                'current_legal_fact_temporal_stale:' + stale_code)
    return reasons


