def aereo04_evaluation_date(value=None):
    if value is None:
        return AEREO04_DIRECT_VALIDATOR_SNAPSHOT_DATE
    if isinstance(value, datetime.datetime):
        if value.tzinfo is None:
            value = value.replace(tzinfo=AEREO04_LEGAL_TIMEZONE)
        return value.astimezone(AEREO04_LEGAL_TIMEZONE).date()
    if isinstance(value, datetime.date):
        return value
    if isinstance(value, str):
        return datetime.date.fromisoformat(value)
    raise TypeError("aereo-04 evaluation date must be date or ISO date")


def aereo04_source_requirements_as_of(intent, evaluation_date=None):
    date_value = aereo04_evaluation_date(evaluation_date)
    requirements = list(AEREO04_SOURCE_REQUIREMENTS[intent])
    if (intent in AEREO04_MONTREAL_CURRENT_LIMIT_INTENTS and
            date_value >= AEREO04_MONTREAL_2024_CUTOFF):
        requirements.append((
            "icao_2024",
            "icao_montreal_2024_baggage_limit_1519_sdr",
        ))
    temporal = (
        AEREO04_PRE_RBAC107_SOURCE_REQUIREMENTS
        if date_value < AEREO04_RBAC107_EMD11_CUTOFF
        else AEREO04_POST_RBAC107_SOURCE_REQUIREMENTS
    )
    requirements.extend(temporal.get(intent, ()))
    return tuple(requirements)


def has_aereo04_source_kind(page, kind):
    wanted = AEREO04_SOURCE_URLS[kind]
    return any(
        (source.get("url") or "") == wanted
        for source in (page.get("official_sources") or [])
    )


def aereo04_source_metadata(page, wanted_url):
    for source in page.get("official_sources") or []:
        if (source.get("url") or "") != wanted_url:
            continue
        return " ".join((
            source.get("name") or "",
            source.get("anchor_claim") or "",
        )).strip()
    return ""


def aereo04_metadata_has_groups(metadata, groups):
    clauses = [metadata]
    clauses.extend(
        clause.strip()
        for clause in re.split(r"[,;\n]", metadata or "")
        if clause.strip()
    )

    def affirmed(alternative):
        return any(
            criminal13_declarative_alternative_affirmed_in_text(
                clause, alternative)
            for clause in clauses
        )

    return all(
        any(affirmed(alternative) for alternative in alternatives)
        for alternatives in groups
    )


