AEREO04_SOURCE_ANCHOR_RULES = {}
for _intent in AEREO04_INTENT_ORDER:
    _requirements = list(AEREO04_SOURCE_REQUIREMENTS[_intent])
    _requirements.extend(
        AEREO04_PRE_RBAC107_SOURCE_REQUIREMENTS.get(_intent, ()))
    _requirements.extend(
        AEREO04_POST_RBAC107_SOURCE_REQUIREMENTS.get(_intent, ()))
    if _intent in AEREO04_MONTREAL_CURRENT_LIMIT_INTENTS:
        _requirements.append(("icao_2024", ""))
    for _kind, _ in _requirements:
        _rule = AEREO04_INTENT_SOURCE_ANCHOR_RULES.get((_intent, _kind))
        if _rule is None:
            _rule = AEREO04_GENERAL_SOURCE_ANCHOR_RULES.get(_kind)
        if _rule is not None:
            AEREO04_SOURCE_ANCHOR_RULES[(_intent, _kind)] = _rule


def aereo04_source_anchor_reasons(page, intent, kind):
    rule = AEREO04_INTENT_SOURCE_ANCHOR_RULES.get((intent, kind))
    if rule is None:
        rule = AEREO04_GENERAL_SOURCE_ANCHOR_RULES.get(kind)
    if rule is None:
        return []
    code, groups = rule
    metadata = aereo04_source_metadata(page, AEREO04_SOURCE_URLS[kind])
    if not metadata or not aereo04_metadata_has_groups(metadata, groups):
        return ["current_legal_fact_source_anchor_missing:" + code]
    return []


def aereo04_canonical_source_text(raw_url):
    raw_url = (raw_url or "").strip()
    try:
        parsed = urllib.parse.urlsplit(raw_url)
        return " ".join((
            parsed.hostname or "",
            urllib.parse.unquote(parsed.path),
            urllib.parse.unquote_plus(parsed.query),
            urllib.parse.unquote(parsed.fragment),
        )).lower()
    except (TypeError, ValueError, UnicodeError):
        return raw_url.lower()


def aereo04_stale_source_reasons(page, evaluation_date=None):
    date_value = aereo04_evaluation_date(evaluation_date)
    found = []

    def add(code):
        if code and code not in found:
            found.append(code)

    for source in page.get("official_sources") or []:
        raw_url = source.get("url") or ""
        canonical = aereo04_canonical_source_text(raw_url)
        if ("web_bagagem_dicas_anac.pdf" in canonical or
                "anac_panfleto_bagagem.pdf" in canonical):
            add("anac_historical_baggage_guide_not_current_rule")
        elif "copy_of_anac-passageiro" in canonical:
            add("anac_obsolete_passenger_copy_endpoint")
        elif ("cef-resolucao-no-400-de-2016" in canonical or
              "anexo-iii-cef-resolucao-no-400" in canonical):
            add("anac_resolution_400_historical_cef")
        elif ("2019_revised_limits" in canonical or
              "revised limits of liability 2019" in canonical):
            add("icao_montreal_2019_limit_not_current_after_2024_12_28")
        elif ("rbac-107-emd-08" in canonical or
              "rbac-107-emd-09" in canonical):
            add("anac_rbac_107_superseded_emendment")
        if (date_value < AEREO04_RBAC107_EMD11_CUTOFF and
                raw_url == AEREO04_RBAC107_EMD11_URL):
            add("anac_rbac_107_emd11_premature_before_2027_02_23")
        if (date_value >= AEREO04_RBAC107_EMD11_CUTOFF and
                raw_url == AEREO04_RBAC107_EMD10_URL):
            add("anac_rbac_107_emd10_expired_from_2027_02_23")
    return found


