def aereo04_outcome_rules_as_of(intent, evaluation_date=None):
    date_value = aereo04_evaluation_date(evaluation_date)
    rules = [AEREO04_OUTCOME_RULES[intent]]
    if intent in AEREO04_MONTREAL_CURRENT_LIMIT_INTENTS:
        montreal = (
            AEREO04_PRE_MONTREAL_2024_OUTCOME_RULES
            if date_value < AEREO04_MONTREAL_2024_CUTOFF
            else AEREO04_POST_MONTREAL_2024_OUTCOME_RULES
        )
        rules.append(montreal[intent])
    if intent in AEREO04_PRE_RBAC107_OUTCOME_RULES:
        rbac = (
            AEREO04_PRE_RBAC107_OUTCOME_RULES
            if date_value < AEREO04_RBAC107_EMD11_CUTOFF
            else AEREO04_POST_RBAC107_OUTCOME_RULES
        )
        rules.append(rbac[intent])
    return tuple(rules)


def aereo04_affirms_exact_current_baggage_limit(visible):
    return any(
        criminal13_declarative_alternative_affirmed_in_text(
            visible, alternative)
        for alternative in (
            "1 519 des",
            "1 519 direitos especiais de saque",
            "1 519 sdr",
        )
    )


def current_aereo04_legal_fact_reasons(
        page, intent, visible, evaluation_date=None):
    if intent not in AEREO04_INTENTS:
        return []
    date_value = aereo04_evaluation_date(evaluation_date)
    reasons = []
    for kind, code in aereo04_source_requirements_as_of(
            intent, date_value):
        if not has_aereo04_source_kind(page, kind):
            reasons.append("current_legal_fact_source_missing:" + code)
            continue
        reasons.extend(aereo04_source_anchor_reasons(page, intent, kind))
    if (aereo04_affirms_exact_current_baggage_limit(visible) and
            intent not in AEREO04_MONTREAL_CURRENT_LIMIT_INTENTS):
        if not has_aereo04_source_kind(page, "icao_2024"):
            reasons.append(
                "current_legal_fact_source_missing:"
                "icao_montreal_2024_exact_1519_claim")
        else:
            reasons.extend(aereo04_source_anchor_reasons(
                page, intent, "icao_2024"))
    for code in aereo04_stale_source_reasons(page, date_value):
        reasons.append("current_legal_fact_source_stale:" + code)

    for outcome_code, groups in aereo04_outcome_rules_as_of(
            intent, date_value):
        if any(
            not any(
                criminal13_declarative_alternative_affirmed_in_text(
                    visible, alternative)
                for alternative in alternatives
            )
            for alternatives in groups
        ):
            reasons.append(
                "current_legal_fact_outcome_missing:" + outcome_code)

    for stale_code, alternatives in AEREO04_STALE_RULES:
        scope = AEREO04_STALE_RULE_INTENTS.get(stale_code, frozenset())
        if scope and intent not in scope:
            continue
        if any(
            criminal13_stale_alternative_affirmed(visible, alternative)
            for alternative in alternatives
        ):
            reasons.append(
                "current_legal_fact_stale_assertion:" + stale_code)

    if (intent in AEREO04_MONTREAL_CURRENT_LIMIT_INTENTS and
            date_value < AEREO04_MONTREAL_2024_CUTOFF):
        for stale_code, alternatives in (
                AEREO04_PRE_MONTREAL_2024_STALE_RULES):
            if any(
                criminal13_stale_alternative_affirmed(
                    visible, alternative)
                for alternative in alternatives
            ):
                reasons.append(
                    "current_legal_fact_temporal_stale:" + stale_code)
                break

    if intent in AEREO04_PRE_RBAC107_OUTCOME_RULES:
        rbac_stale = (
            AEREO04_PRE_RBAC107_STALE_RULES
            if date_value < AEREO04_RBAC107_EMD11_CUTOFF
            else AEREO04_POST_RBAC107_STALE_RULES
        )
        for stale_code, alternatives in rbac_stale:
            if any(
                criminal13_stale_alternative_affirmed(
                    visible, alternative)
                for alternative in alternatives
            ):
                reasons.append(
                    "current_legal_fact_temporal_stale:" + stale_code)
                break
    return reasons


