# Flattened inventory is intentionally derived once from the single source
# matrix, so tests can prove that every one of the 30 requirements has a
# material anchor without maintaining a second, override-prone matrix.
AEREO05_SOURCE_ANCHOR_RULES = {}
for _intent in AEREO05_INTENT_ORDER:
    for _kind, _code in AEREO05_SOURCE_REQUIREMENTS[_intent]:
        _rule = AEREO05_INTENT_SOURCE_ANCHOR_RULES.get((_intent, _kind))
        if _rule is None:
            _rule = AEREO05_GENERAL_SOURCE_ANCHOR_RULES.get(_kind)
        if _rule is not None:
            AEREO05_SOURCE_ANCHOR_RULES[(_intent, _kind)] = _rule


def aereo05_evaluation_date(value=None):
    if value is None:
        return AEREO05_DIRECT_VALIDATOR_SNAPSHOT_DATE
    if isinstance(value, datetime.datetime):
        if value.tzinfo is None:
            value = value.replace(tzinfo=AEREO05_LEGAL_TIMEZONE)
        return value.astimezone(AEREO05_LEGAL_TIMEZONE).date()
    if isinstance(value, datetime.date):
        return value
    if isinstance(value, str):
        return datetime.date.fromisoformat(value)
    raise TypeError('aereo-05 evaluation date must be date or ISO date')


def aereo05_source_for_kind(page, kind):
    wanted = AEREO05_SOURCE_URLS.get(kind)
    if wanted is None:
        return None
    for source in page.get('official_sources') or []:
        # Go compares source.URL literally; do not normalize, trim, or repair.
        if (source.get('url') or '') == wanted:
            return source
    return None


def has_aereo05_source_kind(page, kind):
    return aereo05_source_for_kind(page, kind) is not None


def aereo05_minor_adjacent_anchor_affirmed(visible):
    target = 'assegura assento adjacente para menor de 16 anos'
    for clause in semantic_legal_fact_clauses(visible):
        if target not in clause:
            continue
        if (criminal13_anchor_nonaffirming(clause, target) or
                criminal13_clause_explicitly_nonaffirming(clause) or
                any(marker in clause for marker in (
                    'nao ' + target, 'nem ' + target,
                    'nunca ' + target, 'jamais ' + target))):
            continue
        return True
    return False


def aereo05_anchor_alternative_affirmed(visible, alternative):
    if criminal13_declarative_alternative_affirmed_in_text(
            visible, alternative):
        return True
    return any(
        criminal13_declarative_alternative_affirmed_in_text(
            clause.strip(), alternative)
        for clause in re.split(r'[,;\n]', visible or '')
        if clause.strip())


def aereo05_anchor_group_affirmed(visible, alternatives):
    def explicitly_disclaimed(clause):
        return (criminal13_clause_explicitly_nonaffirming(clause) or
                any(marker in clause for marker in (
                    'nao afirma que', 'nao diz que',
                    'nao sustenta que', 'nao declara que',
                    'e falso que', 'e incorreto afirmar que',
                    'nao e verdade que')))

    normalized_visible = norm_key(visible)
    if not explicitly_disclaimed(normalized_visible):
        if any(
            aereo05_anchor_alternative_affirmed(visible, alternative)
            for alternative in alternatives
        ):
            return True
    for raw_clause in re.split(r'[,;\n\r]', visible or ''):
        clause = norm_key(raw_clause)
        if not clause:
            continue
        # If the whole complement is expressly disclaimed, a shorter
        # alternative inside it must not turn the group green.
        if explicitly_disclaimed(clause):
            continue
        if any(
            aereo05_anchor_alternative_affirmed(
                clause, alternative)
            for alternative in alternatives
        ):
            return True
    return False


def aereo05_source_anchor_reasons(page, intent, kind):
    rule = AEREO05_INTENT_SOURCE_ANCHOR_RULES.get((intent, kind))
    if rule is None:
        rule = AEREO05_GENERAL_SOURCE_ANCHOR_RULES.get(kind)
    if rule is None:
        return []
    source = aereo05_source_for_kind(page, kind)
    if source is None:
        return []
    metadata = ' '.join((source.get('name') or '',
                         source.get('anchor_claim') or ''))
    code, groups = rule
    for group_index, alternatives in enumerate(groups):
        special_minor_group = (
            intent == 'aer-cobranca-escolha-assento-legalidade' and
            kind == 'portaria_13065' and group_index == 0)
        if special_minor_group:
            matched = aereo05_minor_adjacent_anchor_affirmed(metadata)
        else:
            matched = aereo05_anchor_group_affirmed(metadata, alternatives)
        if not matched:
            return ['current_legal_fact_source_anchor_missing:' + code]
    return []


def aereo05_canonical_source_text(raw_url):
    raw_url = (raw_url or '').strip()
    try:
        parsed = urllib.parse.urlsplit(raw_url)
        return ' '.join((
            parsed.hostname or '',
            urllib.parse.unquote(parsed.path),
            urllib.parse.unquote_plus(parsed.query),
            urllib.parse.unquote(parsed.fragment),
        )).lower()
    except (TypeError, ValueError, UnicodeError):
        return raw_url.lower()


def aereo05_stale_source_reasons(page, evaluation_date=None):
    if aereo05_evaluation_date(evaluation_date) < AEREO05_CEF_8018_REVOKED_AT:
        return []
    for source in page.get('official_sources') or []:
        canonical = norm_key(aereo05_canonical_source_text(
            source.get('url') or ''))
        if any(marker in canonical
               for marker in AEREO05_CEF_STALE_SOURCE_MARKERS):
            return [
                'current_legal_fact_source_stale:'
                'anac_portaria_8018_cef_revoked_2026_04_28']
    return []


def aereo05_cef_8018_current_assertion(visible):
    for clause in semantic_legal_fact_clauses(visible):
        has_identifier = (
            any(identifier in clause
                for identifier in AEREO05_CEF_CURRENT_IDENTIFIERS) or
            ('cef' in clause and '2022' in clause))
        asserts_current = any(
            assertion in clause
            for assertion in AEREO05_CEF_CURRENT_ASSERTIONS)
        disclaims_current = any(
            disclaimer in clause
            for disclaimer in AEREO05_CEF_CURRENT_DISCLAIMERS)
        if (has_identifier and asserts_current and
                not disclaims_current and
                not criminal13_clause_explicitly_nonaffirming(clause)):
            return True
    return False


