def aereo05_article12_outcome_group_affirmed(
        intent, group_index, visible):
    if intent != 'aer-remarcacao-taxa-diferenca-tarifaria':
        return None
    handlers = {
        5: aereo05_article12_late_notice_affirmed,
        6: aereo05_article12_threshold_with_nonagreement_affirmed,
        7: aereo05_article12_remedies_affirmed,
        8: aereo05_article12_passenger_choice_affirmed,
    }
    handler = handlers.get(group_index)
    return None if handler is None else handler(visible)


def aereo05_article12_has_consequence(clause):
    return any(marker in clause for marker in (
        'alternativas', 'opcoes', 'reacomodacao', 'reembolso',
        'restituicao', 'direito', 'garante', 'surg',
        'aciona', 'ativa',
    ))


def aereo05_article12_stale_assertion(code, visible):
    for clause in semantic_legal_fact_clauses(visible):
        if criminal13_clause_explicitly_nonaffirming(clause):
            continue
        has_consequence = aereo05_article12_has_consequence(clause)
        if code == (
                'aereo05_carrier_schedule_change_'
                'thresholds_without_nonagreement'):
            if (has_consequence and
                    (aereo05_article12_clause_has_strict_domestic_threshold(
                        clause) or
                     aereo05_article12_clause_has_strict_international_threshold(
                         clause)) and
                    (not aereo05_article12_clause_has_disagreement(clause) or
                     aereo05_article12_clause_waives_disagreement(clause))):
                return True
        elif code == (
                'aereo05_carrier_schedule_change_'
                'late_notice_conditioned_on_nonagreement'):
            conditional_on_disagreement = (
                aereo05_article12_clause_has_disagreement(clause) and
                any(marker in clause for marker in (
                    'so ', 'somente ', 'depende', 'nao basta',
                    'apenas se')))
            denies_autonomous_trigger = (
                has_consequence and any(marker in clause for marker in (
                    'nao basta', 'nao gera', 'nao aciona', 'nao ativa',
                    'nao garante')))
            if (aereo05_article12_late_notice_context(clause) and
                    (conditional_on_disagreement or
                     denies_autonomous_trigger)):
                return True
        elif code == (
                'aereo05_carrier_schedule_change_inclusive_threshold'):
            equal_threshold = any(marker in clause for marker in (
                'exatamente 30 minutos', 'alteracao de 30 minutos',
                'a partir de 30 minutos', 'exatamente trinta minutos',
                'alteracao de trinta minutos', 'exatamente uma hora',
                'alteracao de uma hora', 'a partir de uma hora',
                'exatamente 60 minutos', 'alteracao de 60 minutos',
            ))
            disclaimed = any(marker in clause for marker in (
                'nao garante', 'nao aciona', 'nao ativa', 'nao gera',
                'nao basta', 'nao surg',
            ))
            if equal_threshold and has_consequence and not disclaimed:
                return True
        elif code == (
                'aereo05_carrier_schedule_change_wrong_remedy_or_choice'):
            article12_context = (
                aereo05_article12_late_notice_context(clause) or
                'alteracao programada' in clause or 'art 12' in clause)
            wrong_remedy = any(marker in clause for marker in (
                'reembolso parcial', 'restituicao parcial',
                'apenas credito', 'so credito', 'basta conceder credito',
                'companhia escolhe', 'companhia pode escolher',
                'cabe a companhia escolher', 'transportador escolhe',
                'transportador pode escolher', 'empresa escolhe',
                'empresa pode escolher', 'cabe a empresa escolher',
            ))
            if article12_context and wrong_remedy:
                return True
    return False


def current_aereo05_legal_fact_reasons(
        page, intent, visible, evaluation_date=None):
    if intent not in AEREO05_INTENTS:
        return []
    date_value = aereo05_evaluation_date(evaluation_date)
    reasons = []
    for kind, code in AEREO05_SOURCE_REQUIREMENTS[intent]:
        if not has_aereo05_source_kind(page, kind):
            reasons.append('current_legal_fact_source_missing:' + code)
            continue
        reasons.extend(aereo05_source_anchor_reasons(page, intent, kind))
    reasons.extend(aereo05_stale_source_reasons(page, date_value))

    outcome_code, groups = AEREO05_OUTCOME_RULES[intent]
    for group_index, alternatives in enumerate(groups):
        semantic_match = aereo05_article12_outcome_group_affirmed(
            intent, group_index, visible)
        if semantic_match is None:
            matched = any(
                criminal13_declarative_alternative_affirmed_in_text(
                    visible, alternative)
                for alternative in alternatives)
        else:
            matched = semantic_match
        if not matched:
            reasons.append(
                'current_legal_fact_outcome_missing:' + outcome_code)
            break

    for stale_code, alternatives in AEREO05_STALE_RULES:
        scope = AEREO05_STALE_RULE_INTENTS.get(stale_code, frozenset())
        if scope and intent not in scope:
            continue
        if stale_code.startswith('aereo05_carrier_schedule_change_'):
            if aereo05_article12_stale_assertion(stale_code, visible):
                reasons.append(
                    'current_legal_fact_stale_assertion:' + stale_code)
            continue
        if any(
            criminal13_stale_alternative_affirmed(visible, alternative)
            for alternative in alternatives
        ):
            reasons.append(
                'current_legal_fact_stale_assertion:' + stale_code)
    cef_reason = (
        'current_legal_fact_stale_assertion:'
        'aereo05_cef_8018_revoked_treated_as_current')
    if (aereo05_cef_8018_current_assertion(visible) and
            cef_reason not in reasons):
        reasons.append(cef_reason)
    return reasons


