# A source may be exact and current yet legally irrelevant to a particular
# intent.  REsp 1.966.032 concerns the online cancellation/refund channel; it
# cannot be presented as authority for retroactive flight-mile entitlement.
AEREO06_FORBIDDEN_SOURCE_KINDS = {
    'aer-milhas-nao-creditadas-voo':
        frozenset(('stj_resp_1966032',)),
}

# Flattened inventory: exactly one material anchor per source occurrence.
AEREO06_SOURCE_ANCHOR_RULES = {}
for _intent in AEREO06_INTENT_ORDER:
    for _kind, _code in AEREO06_SOURCE_REQUIREMENTS[_intent]:
        _rule = AEREO06_INTENT_SOURCE_ANCHOR_RULES.get((_intent, _kind))
        if _rule is None:
            _rule = AEREO06_GENERAL_SOURCE_ANCHOR_RULES.get(_kind)
        if _rule is not None:
            AEREO06_SOURCE_ANCHOR_RULES[(_intent, _kind)] = _rule


def aereo06_source_for_kind(page, kind):
    wanted = AEREO06_SOURCE_URLS.get(kind)
    if wanted is None:
        return None
    accepted = (wanted,) + AEREO06_SOURCE_URL_ALTERNATES.get(kind, ())
    for source in page.get('official_sources') or []:
        # Exact parity contract: no trimming, case folding, port repair, or
        # query/fragment normalization is permitted for official identity.
        # Any of the closed, named official surfaces of the same norm
        # counts, each one still compared byte for byte.
        if (source.get('url') or '') in accepted:
            return source
    return None


def has_aereo06_source_kind(page, kind):
    return aereo06_source_for_kind(page, kind) is not None


def aereo06_source_anchor_rule(intent, kind):
    rule = AEREO06_INTENT_SOURCE_ANCHOR_RULES.get((intent, kind))
    if rule is None:
        rule = AEREO06_GENERAL_SOURCE_ANCHOR_RULES.get(kind)
    return rule


def aereo06_source_anchor_reasons(page, intent, kind):
    rule = aereo06_source_anchor_rule(intent, kind)
    if rule is None:
        return ['current_legal_fact_source_anchor_rule_missing:aereo06_' + kind]
    source = aereo06_source_for_kind(page, kind)
    if source is None:
        return []
    metadata = ' '.join((source.get('name') or '',
                         source.get('anchor_claim') or ''))
    code, groups = rule
    if any(not aereo05_anchor_group_affirmed(metadata, alternatives)
           for alternatives in groups):
        return ['current_legal_fact_source_anchor_missing:' + code]
    if any(
        criminal13_stale_alternative_affirmed(metadata, alternative)
        for alternative in AEREO06_MISLEADING_SOURCE_ANCHOR_RULES.get(
            (intent, kind), ())
    ):
        return ['current_legal_fact_source_anchor_missing:' + code]
    return []


def aereo06_forbidden_source_reasons(page, intent):
    reasons = []
    for kind in AEREO06_FORBIDDEN_SOURCE_KINDS.get(intent, frozenset()):
        if has_aereo06_source_kind(page, kind):
            reasons.append(
                'current_legal_fact_source_stale:' + kind +
                '_irrelevant_to_retroactive_flight_mileage')
    return reasons


def current_aereo06_legal_fact_reasons(
        page, intent, visible, evaluation_date=None):
    if intent not in AEREO06_INTENTS:
        return []
    del evaluation_date  # No temporal boundary in this shard.
    reasons = []
    for kind, code in AEREO06_SOURCE_REQUIREMENTS[intent]:
        if not has_aereo06_source_kind(page, kind):
            reasons.append('current_legal_fact_source_missing:' + code)
            continue
        reasons.extend(aereo06_source_anchor_reasons(page, intent, kind))
    reasons.extend(aereo06_forbidden_source_reasons(page, intent))

    outcome_code, groups = AEREO06_OUTCOME_RULES[intent]
    if any(
        not any(
            criminal13_declarative_alternative_affirmed_in_text(
                visible, alternative)
            for alternative in alternatives)
        for alternatives in groups
    ):
        reasons.append('current_legal_fact_outcome_missing:' + outcome_code)
    if intent == 'aer-conta-milhas-bloqueada-fraude':
        human_review_qualifier = (
            'a lei nao garante que a revisao seja feita por uma pessoa natural')
        outcome_reason = 'current_legal_fact_outcome_missing:' + outcome_code
        if (not criminal13_declarative_alternative_affirmed_in_text(
                visible, human_review_qualifier) and
                outcome_reason not in reasons):
            reasons.append(outcome_reason)

    for stale_code, alternatives in AEREO06_STALE_RULES:
        scope = AEREO06_STALE_RULE_INTENTS.get(stale_code, frozenset())
        if scope and intent not in scope:
            continue
        if any(
            criminal13_stale_alternative_affirmed(visible, alternative)
            for alternative in alternatives
        ):
            reasons.append(
                'current_legal_fact_stale_assertion:' + stale_code)
    return reasons


