def aereo08_source_for_kind(page, kind):
    wanted = AEREO08_SOURCE_URLS.get(kind)
    if wanted is None:
        return None
    for source in page.get('official_sources') or []:
        if (source.get('url') or '') == wanted:
            return source
    return None


def aereo08_source_anchor_reasons(page, intent, requirement):
    kind, code, groups = requirement
    source = aereo08_source_for_kind(page, kind)
    if source is None:
        return []
    metadata = ' '.join((source.get('name') or '',
                         source.get('anchor_claim') or ''))
    if any(not aereo05_anchor_group_affirmed(metadata, alternatives)
           for alternatives in groups):
        return ['current_legal_fact_source_anchor_missing:' + code]
    if any(
        criminal13_stale_alternative_affirmed(metadata, alternative)
        for alternative in AEREO08_MISLEADING_ANCHOR_RULES.get(
            (intent, kind), ())
    ):
        return ['current_legal_fact_source_anchor_missing:' + code]
    return []


def aereo08_forbidden_source_reasons(page):
    reasons = []
    for source in page.get('official_sources') or []:
        raw_url = source.get('url') or ''
        for reference, code in AEREO08_FORBIDDEN_SOURCE_URLS.items():
            if aereo08_forbidden_source_matches(raw_url, reference):
                reasons.append('current_legal_fact_source_stale:' + code)
                break
    return reasons


def aereo08_forbidden_source_matches(raw_url, reference_url):
    if not aereo_source_endpoint_matches(raw_url, reference_url):
        return False
    try:
        parsed = urllib.parse.urlsplit((raw_url or '').strip())
        reference = urllib.parse.urlsplit(reference_url)
    except (TypeError, ValueError):
        return False
    wanted_uri = urllib.parse.parse_qs(
        reference.query, keep_blank_values=True).get('uri', ())
    if not wanted_uri:
        return True
    actual_uri = urllib.parse.parse_qs(
        parsed.query, keep_blank_values=True).get('uri', ())
    return wanted_uri[0] in actual_uri


def aereo08_evaluation_date(value=None):
    if value is None:
        return AEREO08_DIRECT_VALIDATOR_SNAPSHOT_DATE
    if isinstance(value, datetime.datetime):
        if value.tzinfo is None:
            value = value.replace(tzinfo=AEREO08_LEGAL_TIMEZONE)
        return value.astimezone(AEREO08_LEGAL_TIMEZONE).date()
    if isinstance(value, datetime.date):
        return value
    if isinstance(value, str):
        return datetime.date.fromisoformat(value)
    raise TypeError('aereo-08 evaluation date must be date or ISO date')


def current_aereo08_legal_fact_reasons(
        page, intent, visible, evaluation_date=None):
    if intent not in AEREO08_INTENTS:
        return []
    date_value = aereo08_evaluation_date(evaluation_date)
    reasons = []
    for requirement in AEREO08_SOURCE_REQUIREMENTS[intent]:
        kind, code, _ = requirement
        if aereo08_source_for_kind(page, kind) is None:
            reasons.append('current_legal_fact_source_missing:' + code)
            continue
        reasons.extend(aereo08_source_anchor_reasons(
            page, intent, requirement))
    reasons.extend(aereo08_forbidden_source_reasons(page))
    outcome_code, groups = AEREO08_OUTCOME_RULES[intent]
    if any(
        not any(
            criminal13_declarative_alternative_affirmed_in_text(
                visible, alternative)
            for alternative in alternatives)
        for alternatives in groups
    ):
        reasons.append('current_legal_fact_outcome_missing:' + outcome_code)
    for stale_code, alternatives in AEREO08_STALE_RULES:
        scope = AEREO08_STALE_RULE_INTENTS.get(stale_code, frozenset())
        if scope and intent not in scope:
            continue
        if any(
            criminal13_stale_alternative_affirmed(visible, alternative)
            for alternative in alternatives
        ):
            reasons.append(
                'current_legal_fact_stale_assertion:' + stale_code)
    if (intent == 'aer-regulamento-europeu-261-indenizacao' and
            date_value >= AEREO08_EU_REFORM_STATUS_RECHECK_AT):
        reasons.append(
            'current_legal_fact_temporal_stale:'
            'aereo08_eu261_reform_status_recheck_required_after_2026_07_20')
    if (intent == 'aer-voo-eua-regras-reembolso' and
            date_value >= AEREO08_US_REFUND_ENFORCEMENT_RECHECK_AT):
        reasons.append(
            'current_legal_fact_temporal_stale:'
            'aereo08_us_renumbering_enforcement_status_'
            'recheck_required_after_2026_07_20')
    return reasons


