def aereo09_source_for_kind(page, kind):
    wanted = AEREO09_SOURCE_URLS.get(kind)
    if wanted is None:
        return None
    for source in page.get('official_sources') or []:
        if (source.get('url') or '') == wanted:
            return source
    return None


def aereo09_source_anchor_reasons(page, intent, requirement):
    kind, code, groups = requirement
    source = aereo09_source_for_kind(page, kind)
    if source is None:
        return []
    metadata = ' '.join((source.get('name') or '',
                         source.get('anchor_claim') or ''))
    if any(not aereo05_anchor_group_affirmed(metadata, alternatives)
           for alternatives in groups):
        return ['current_legal_fact_source_anchor_missing:' + code]
    if any(
        criminal13_stale_alternative_affirmed(metadata, alternative)
        for alternative in AEREO09_MISLEADING_ANCHOR_RULES.get(
            (intent, kind), ())
    ):
        return ['current_legal_fact_source_anchor_missing:' + code]
    return []


def aereo09_forbidden_source_reasons(page):
    reasons = []
    for source in page.get('official_sources') or []:
        raw_url = source.get('url') or ''
        for reference, code in AEREO09_FORBIDDEN_SOURCE_URLS.items():
            if aereo_source_endpoint_matches(raw_url, reference):
                reasons.append(
                    'current_legal_fact_source_stale:' + code)
                break
    return reasons


def current_aereo09_legal_fact_reasons(
        page, intent, visible, evaluation_date=None):
    if intent not in AEREO09_INTENTS:
        return []
    # Sem fato temporal A09: manter a assinatura do dispatcher, mas não
    # transformar evaluation_date em falsa evidência de atualidade.
    del evaluation_date
    reasons = []
    for requirement in AEREO09_SOURCE_REQUIREMENTS[intent]:
        kind, code, _ = requirement
        if aereo09_source_for_kind(page, kind) is None:
            reasons.append(
                'current_legal_fact_source_missing:' + code)
            # Essencial: não chamar anchor helper como substituto do
            # source_missing; ele retorna [] quando a fonte inexiste.
            continue
        reasons.extend(aereo09_source_anchor_reasons(
            page, intent, requirement))
    reasons.extend(aereo09_forbidden_source_reasons(page))
    outcome_code, groups = AEREO09_OUTCOME_RULES[intent]
    if any(
        not any(
            criminal13_declarative_alternative_affirmed_in_text(
                visible, alternative)
            for alternative in alternatives)
        for alternatives in groups
    ):
        reasons.append(
            'current_legal_fact_outcome_missing:' + outcome_code)
    for stale_code, alternatives in AEREO09_STALE_RULES:
        scope = AEREO09_STALE_RULE_INTENTS.get(
            stale_code, frozenset())
        if scope and intent not in scope:
            continue
        if any(
            criminal13_stale_alternative_affirmed(
                visible, alternative)
            for alternative in alternatives
        ):
            reasons.append(
                'current_legal_fact_stale_assertion:' + stale_code)
    return reasons


