def telecom_ppp_source_requirement(kind, code, device_scope, *groups):
    return (kind, code, tuple(groups) + (
        TELECOM_PPP_ARTICLE_90_SCOPE_ALTERNATIVES,
    ) + tuple(tuple(group) for group in device_scope) + (
        TELECOM_PPP_MICRO_FLOOR_ALTERNATIVES,
    ))


def telecom_ppp_scope_rule(code, device_scope):
    return (code, (
        TELECOM_PPP_ARTICLE_90_SCOPE_ALTERNATIVES,
    ) + tuple(tuple(group) for group in device_scope) + (
        TELECOM_PPP_MICRO_FLOOR_ALTERNATIVES,
        TELECOM_PPP_CDC_LGT_ALTERNATIVES,
    ))


def telecom01_ppp_source_requirement(kind, code, device_scope, *groups):
    kind, code, all_groups = telecom_ppp_source_requirement(
        kind, code, device_scope, *groups)
    return (kind, code, all_groups + (
        ('arts 87 a 89 nao integram o art 90',),
        ('o rgc nao impoe ouvidoria as ppp',
         'rgc nao impoe ouvidoria as ppp'),
    ))


