def telecom_requirements_with_lgt(prefix, intent_order, requirements):
    for intent in intent_order:
        code_suffix = intent.removeprefix('tel-').replace('-', '_')
        requirements[intent] = requirements[intent] + ((
            'lgt',
            f'{prefix}_lgt_article_3_user_rights_{code_suffix}',
            TELECOM_LGT_ARTICLE_3_ANCHOR_GROUPS,
        ),)
    return requirements


TELECOM01_SOURCE_REQUIREMENTS = telecom_requirements_with_lgt(
    'telecom01', TELECOM01_INTENT_ORDER, TELECOM01_SOURCE_REQUIREMENTS)

