def current_imobiliario_legal_fact_reasons(page, intent, visible, folded):
    """Current Lei do Inquilinato facts grouped by legal transaction."""
    reasons = []
    rule = IMOBILIARIO05_DECLARATIVE_RULES.get(intent)
    if rule:
        reasons.extend(declarative_current_legal_fact_reasons(
            page, visible, rule,
            IMOBILIARIO05_DECLARATIVE_STJ_SOURCE_GROUPS.get(intent, ())))
        normalized = ' '.join(re.sub(r'[^a-z0-9]+', ' ', folded).split())
        if any(phrase in normalized for phrase in
               IMOBILIARIO05_DECLARATIVE_FORBIDDEN_PHRASES.get(intent, ())):
            reasons.append(
                'current_legal_fact_stale_assertion:' + rule[2] + '_negated')
    if intent in IMOBILIARIO05_REVIEW_STALE_INTENTS:
        reasons.extend(current_imobiliario05_review_stale_reasons(
            intent, visible))
    if (intent == 'imob-lote-atraso-infraestrutura' and
            article_38_source_metadata_misattributes_judicial_deposit(page)):
        append_legal_fact_reason_once(
            reasons,
            'current_legal_fact_stale_assertion:article_38_deposit_misattributed_as_judicial')
    if intent == 'imob-rateio-obra-luxo-minoria':
        if not has_consolidated_statute_article_metadata(
                page, 'l10406compilada.htm',
                '336', '341', '342', '343', '351'):
            reasons.append('current_legal_fact_source_missing:cc_1336_1341_1342_1343_1351_consolidated_metadata')
        if stale_article_1342_unanimity_misattribution(folded):
            reasons.append('current_legal_fact_stale_assertion:article_1342_unanimity_misattributed')
    if intent in IMOBILIARIO06_CORRECTION_STALE_INTENTS:
        reasons.extend(current_imobiliario06_correction_stale_reasons(
            intent, visible))
    if intent in IMOBILIARIO07_LEGAL_FACT_INTENTS:
        reasons.extend(current_imobiliario07_legal_fact_reasons(
            page, intent, visible))
    if intent in IMOBILIARIO08_LEGAL_FACT_INTENTS:
        reasons.extend(current_imobiliario08_legal_fact_reasons(
            page, intent, visible))

    if intent in TENANCY_DEFAULT_INJUNCTION_INTENTS:
        if not has_source_url_part(page, 'l8245.htm#art59'):
            reasons.append('current_legal_fact_source_missing:tenancy_art_59_ix_default_injunction')
        if (not any(part in folded for part in ('art 59', 'artigo 59')) or
                'ix' not in folded or 'inadimplemento' not in folded or
                not any(part in folded for part in
                        ('sem garantia', 'garantia extinta',
                         'garantia foi extinta')) or
                not any(part in folded for part in
                        ('caucao de tres alugueis',
                         'caucao equivalente a tres alugueis')) or
                'elid' not in folded or 'deposito' not in folded or
                not any(part in folded for part in
                        ('totalidade da divida', 'deposito integral da divida'))):
            reasons.append('current_legal_fact_outcome_missing:default_injunction_no_guarantee_three_rents_and_elision')
        if stale_simple_rent_delay_never_supports_injunction(folded):
            reasons.append('current_legal_fact_stale_assertion:simple_rent_delay_never_supports_injunction')

    if intent in TENANCY_RESIDENTIAL_TERMINATION_INTENTS:
        if not has_all_source_url_parts(
                page, 'l8245.htm#art46', 'l8245.htm#art47',
                'l8245.htm#art57'):
            reasons.append('current_legal_fact_source_missing:tenancy_articles_46_47_57_termination')
        has_long_residential = (
            'residencial' in folded and
            any(part in folded for part in ('art 46', 'artigo 46')) and
            any(part in folded for part in
                ('30 meses ou mais', 'igual ou superior a 30 meses')))
        has_short_residential = (
            any(part in folded for part in ('art 47', 'artigo 47')) and
            'verbal' in folded and
            any(part in folded for part in
                ('menos de 30 meses', 'inferior a 30 meses')) and
            'cinco anos' in folded)
        has_non_residential = (
            any(part in folded for part in ('art 57', 'artigo 57')) and
            'nao residencial' in folded)
        if not (has_long_residential and has_short_residential and
                has_non_residential):
            reasons.append('current_legal_fact_outcome_missing:residential_termination_articles_46_47_57_boundaries')
        if stale_any_indefinite_residential_empty_termination(folded):
            reasons.append('current_legal_fact_stale_assertion:any_indefinite_residential_lease_empty_termination')
        if stale_article_47_thirty_day_prorogation(folded):
            reasons.append('current_legal_fact_stale_assertion:art_47_prorogation_requires_30_days')

