def semantic_declarative_legal_fact_clauses(value):
    """Keep comma negation scopes without breaking cross-comma alternatives."""
    protected = re.sub(r'(?<=\d)\.(?=\d)', ' ', value or '')
    protected = re.sub(
        r'\b(art|arts|inc|n|no|resp|aresp)\.\s*', r'\1 ', protected,
        flags=re.IGNORECASE)
    clauses = []
    for sentence in re.findall(r'[^.!?]+(?:[.!?]+|$)', protected):
        if sentence.strip().endswith('?'):
            continue
        for part in re.split(
                r'[;\r\n]+|,\s+(?:e|mas|por[eé]m|contudo|entretanto)\s+',
                sentence, flags=re.IGNORECASE):
            marked_tokens = []
            pending_comma = False
            pending_colon = False
            comma_parts = part.split(',')
            for part_index, comma_part in enumerate(comma_parts):
                colon_parts = comma_part.split(':')
                for colon_index, colon_part in enumerate(colon_parts):
                    fields = re.sub(
                        r'[^a-z0-9]+', ' ', norm_key(colon_part)).split()
                    for field_index, field in enumerate(fields):
                        marked_tokens.append((
                            field,
                            pending_comma and field_index == 0,
                            pending_colon and field_index == 0))
                        pending_comma = False
                        pending_colon = False
                    if colon_index + 1 < len(colon_parts):
                        pending_colon = True
                if part_index + 1 < len(comma_parts):
                    pending_comma = True

            def emit(start, end):
                if start >= end:
                    return
                tokens = [value for value, _, _ in marked_tokens[start:end]]
                comma_before = [False] * (len(tokens) + 1)
                colon_before = [False] * (len(tokens) + 1)
                for index in range(start + 1, end):
                    comma_before[index - start] = marked_tokens[index][1]
                    colon_before[index - start] = marked_tokens[index][2]
                clauses.append((tokens, comma_before, colon_before))

            start = 0
            for index, (token, _, _) in enumerate(marked_tokens):
                if token in {'mas', 'porem', 'contudo', 'entretanto'}:
                    emit(start, index)
                    start = index + 1
            emit(start, len(marked_tokens))
    return clauses


def semantic_legal_fact_clauses(value):
    protected = re.sub(r'(?<=\d)\.(?=\d)', ' ', value or '')
    protected = re.sub(
        r'\b(art|arts|inc|n|no|resp|aresp)\.\s*', r'\1 ', protected,
        flags=re.IGNORECASE)
    clauses = []
    for sentence in re.findall(r'[^.!?]+(?:[.!?]+|$)', protected):
        if sentence.strip().endswith('?'):
            continue
        for part in re.split(
                r'[;\r\n]+|,\s+(?:e|mas|por[eé]m|contudo|entretanto)\s+',
                sentence, flags=re.IGNORECASE):
            normalized = ' '.join(
                re.sub(r'[^a-z0-9]+', ' ', norm_key(part)).split())
            clauses.extend(piece.strip() for piece in re.split(
                r'\b(?:mas|porem|contudo|entretanto)\b', normalized)
                if piece.strip())
    return clauses


def semantic_noise_automatic_force_majeure(clause):
    has_noise = any(part in clause for part in ('barulho', 'ruido'))
    has_third_party = any(part in clause for part in ('terceiro', 'vizinho'))
    has_event = any(part in clause for part in
                    ('forca maior', 'caso fortuito'))
    has_categorical_predicate = (
        any(part in clause for part in
            ('automatic', 'necessariamente', 'sempre', 'inevitavel')) and
        any(part in clause for part in
            (' e forca maior', 'constitui', 'configura', 'caracteriza',
             'equivale')))
    qualified = any(part in clause for part in (
        'nao configura', 'nao e', 'nao constitui', 'nem sempre', 'depende',
        'pode configurar'))
    return (has_noise and has_third_party and has_event and
            has_categorical_predicate and not qualified)


def semantic_article_914_owns_fifteen_day_deadline(clause):
    tokens = clause.split()
    for anchor, token in enumerate(tokens):
        if token != '914':
            continue
        window = tokens[max(0, anchor - 7):anchor + 8]
        window_text = ' '.join(window)
        if (not semantic_tokens_have_any_prefix(window, 'praz') or
                not semantic_tokens_contain_any(window, '15', 'quinze') or
                not semantic_tokens_have_any_prefix(
                    window, 'fix', 'estabelec', 'defin', 'nasc', 'vem',
                    'decorr', 'prev')):
            continue
        if any(part in window_text for part in (
                'nao fixa', 'nao estabelece', 'nao define', 'nao preve',
                'nao nasce', 'nao vem', 'nao decorre')):
            continue
        return True
    return False


