def semantic_article_1343_unanimity_denied(clause):
    has_article = any(part in clause for part in
                      ('art 1 343', 'artigo 1 343'))
    if not has_article or 'unanim' not in clause:
        return False
    denies_requirement = (
        any(part in clause for part in
            ('nao exige', 'nao requer', 'nao demanda', 'nao depende')) or
        (any(part in clause for part in ('dispensa', 'afasta', 'exclui')) and
         not any(part in clause for part in
                 ('nao dispensa', 'nao afasta', 'nao exclui'))))
    lower_threshold = (
        any(part in clause for part in ('basta', 'bastam', 'suficiente')) and
        any(part in clause for part in ('dois tercos', '2 3')))
    return denies_requirement or lower_threshold


