def semantic_clause_has_any_stem(clause, *stems):
    return any(semantic_token_has_any_prefix(token, *stems)
               for token in clause.split())


def semantic_token_has_any_prefix(token, *prefixes):
    return any(token.startswith(prefix) for prefix in prefixes)


def semantic_tokens_have_any_prefix(tokens, *prefixes):
    return any(semantic_token_has_any_prefix(token, *prefixes)
               for token in tokens)


def semantic_tokens_contain_any(tokens, *candidates):
    return any(token in candidates for token in tokens)


def append_legal_fact_reason_once(reasons, reason):
    if reason not in reasons:
        reasons.append(reason)


def has_consolidated_statute_article_metadata(
        page, statute_url_part, *articles):
    statute_url_part = (statute_url_part or '').strip().lower()
    for source in page.get('official_sources') or []:
        source_url = (source.get('url') or '').strip().lower()
        matches_statute = (
            statute_url_part in source_url or
            planalto_part_matches_source(source.get('url'), statute_url_part))
        if not matches_statute or '#art' not in source_url:
            continue
        if (metadata_declares_article_numbers(
                source.get('name'), *articles) and
                metadata_declares_article_numbers(
                    source.get('anchor_claim'), *articles)):
            return True
    return False


