def semantic_clause_has_meta_negated_complement(clause):
    tokens = clause.split()
    return any(declarative_clause_meta_negates_assertion(tokens, start)
               for start in range(1, len(tokens)))


def semantic_anchor_meta_negated(clause, *alternatives):
    tokens = clause.split()
    for alternative in alternatives:
        alternative_tokens = re.sub(
            r'[^a-z0-9]+', ' ', norm_key(alternative)).split()
        if not alternative_tokens or len(alternative_tokens) > len(tokens):
            continue
        width = len(alternative_tokens)
        for start in range(len(tokens) - width + 1):
            if (tokens[start:start + width] == alternative_tokens and
                    declarative_clause_meta_negates_assertion(tokens, start)):
                return True
    return False


def current_imobiliario07_legal_fact_reasons(page, intent, visible):
    rule = IMOBILIARIO07_CURRENT_LEGAL_FACT_RULES.get(intent)
    if not rule:
        return []
    (source_code, planalto_source_groups, stj_source_groups,
     outcome_code, outcome_groups) = rule
    reasons = []
    missing_source = any(
        not any(has_planalto_source_url_part(page, alternative)
                for alternative in alternatives)
        for alternatives in planalto_source_groups)
    if not missing_source:
        missing_source = any(
            not any(has_stj_source_url_part(page, alternative)
                    for alternative in alternatives)
            for alternatives in stj_source_groups)
    if missing_source:
        reasons.append('current_legal_fact_source_missing:' + source_code)
    if any(not any(declarative_alternative_affirmed_in_text(
            visible, alternative) for alternative in alternatives)
            for alternatives in outcome_groups):
        reasons.append('current_legal_fact_outcome_missing:' + outcome_code)
    if (intent == 'imob-arrendamento-rural-vs-locacao' and
            not has_planalto_source_url_part(page, 'd59566.htm#art18')):
        reasons.append(
            'current_legal_fact_source_missing:rural_decree_article_18_fixed_money_and_fruit_equivalence')
    if (intent == 'imob-renovatoria-contrato-verbal' and
            not has_planalto_source_url_part(page, 'l8245.htm#art53')):
        reasons.append(
            'current_legal_fact_source_missing:tenancy_article_53_verbal_commercial_protection')
    reasons.extend(current_imobiliario07_stale_reasons(intent, visible))
    return reasons


