def legal_fact_sentences(value):
    return [norm_key(part) for part in re.split(r'[.!?\r\n]+', value or '')
            if norm_key(part)]


def matrix_branch_unified_clearance_outcome_affirmed(visible):
    """Require the current blocking result in one declarative clause."""
    for clause in semantic_legal_fact_clauses(visible):
        tokens = clause.split()
        has_cross_establishment = (
            ('matriz' in clause and 'filial' in clause) or
            any(part in clause for part in (
                'outro estabelecimento', 'outra filial',
                'demais estabelecimentos', 'qualquer estabelecimento')))
        has_debt = any(part in clause for part in (
            'pendencia fiscal', 'debito', 'divida'))
        has_certificate = any(part in clause for part in (
            'certidao negativa', 'certidao positiva com efeitos de negativa',
            'efeitos de negativa', 'cnd', 'cpend'))
        has_affirmative_block = any(declarative_alternative_affirmed(
            tokens, verb) for verb in (
                'impede', 'obsta', 'bloqueia', 'inviabiliza',
                'contamina', 'compromete', 'prejudica'))
        if (has_cross_establishment and has_debt and has_certificate and
                has_affirmative_block):
            return True
    return False


def stale_matrix_branch_individual_certificate(visible):
    """Reject the superseded establishment-autonomy rule for federal CND/CPEND."""
    for clause in semantic_legal_fact_clauses(visible):
        if any(part in clause for part in (
                'e falso que', 'nao e verdade que', 'nao e correto afirmar',
                'tese superada', 'entendimento superado',
                'precedente superado', 'posicao superada',
                'nao prevalece', 'deixou de prevalecer')):
            continue
        individualized = any(part in clause for part in (
            'regularidade fiscal e individualizada por estabelecimento',
            'regularidade fiscal deve ser individualizada por estabelecimento',
            'certidao e emitida isoladamente por estabelecimento',
            'cada estabelecimento responde apenas pela sua regularidade'))
        independent = any(part in clause for part in (
            'cada cnpj tem direito a certidao independente',
            'cada estabelecimento pode obter certidao independente',
            'autonomia dos estabelecimentos permite obter certidao',
            'autonomia dos estabelecimentos permite a certidao'))
        has_cross_establishment = (
            ('matriz' in clause and 'filial' in clause) or
            any(part in clause for part in (
                'outra filial', 'outro estabelecimento',
                'demais estabelecimentos')))
        has_debt = any(part in clause for part in (
            'debito', 'pendencia', 'divida'))
        has_negative_certificate = any(part in clause for part in (
            'certidao negativa', 'cnd'))
        nonblocking_phrases = (
            'nao impede', 'nao obsta', 'nao bloqueia', 'nao afeta',
            'nao contamina', 'nao compromete', 'nao repercute',
            'nao prejudica', 'nao atinge', 'nao interfere')
        nonblocking_positions = [
            clause.find(part) for part in nonblocking_phrases
            if part in clause]
        says_does_not_block = bool(nonblocking_positions)
        first_nonblocking = min(nonblocking_positions, default=len(clause))
        extinguished_phrases = (
            'credito extinto', 'debito extinto', 'divida extinta',
            'obrigacao extinta', 'debito baixado', 'pendencia baixada',
            'inscricao cancelada', 'debito cancelado', 'credito cancelado')
        has_prior_extinction = any(
            0 <= clause.find(part) < first_nonblocking
            for part in extinguished_phrases)
        if any(part in clause for part in (
                'credito nao extinto', 'debito nao extinto',
                'divida nao extinta', 'nao foi extinto',
                'nao foi baixado', 'nao foi cancelado')):
            has_prior_extinction = False
        if (individualized or independent or
                (has_cross_establishment and has_debt and
                 has_negative_certificate and says_does_not_block and
                 not has_prior_extinction)):
            return True
    return False


