def _portfolio_sidecar_path():
    """Caminho do índice incremental do portfólio (dinâmico: respeita ``ROOT``)."""
    return os.path.join(
        ROOT, '.cache', 'audit-v2-pages', 'portfolio-index.json')


def _portfolio_sidecar_header():
    """Cabeçalho que invalida o índice inteiro quando muda a lógica do auditor.

    Reutiliza o mesmo ``source_fingerprint`` do índice per-shard: qualquer
    alteração no auditor (inclusive nesta função de parse) troca o fingerprint e
    força re-parse completo. Um portfólio nunca é servido por uma versão de
    lógica diferente da que o produziria agora.
    """
    return {
        'schema_version': PORTFOLIO_SIDECAR_SCHEMA_VERSION,
        'source_fingerprint': _shard_sidecar_source_fingerprint(),
    }


def _portfolio_file_identity(path):
    """Assinatura barata do snapshot de disco, sem ler nem hashear o conteúdo.

    Espelha exatamente a identidade que ``read_target_snapshot`` usa para
    detectar reescrita em curso (dev/ino/tamanho/mtime_ns/ctime_ns). Devolve
    ``None`` (nunca cacheável) para não-arquivo/erro — fail-closed em re-parse.
    """
    try:
        info = os.stat(path, follow_symlinks=False)
    except OSError:
        return None
    if not stat.S_ISREG(info.st_mode):
        return None
    return [info.st_dev, info.st_ino, info.st_size,
            info.st_mtime_ns, info.st_ctime_ns]


def _load_portfolio_sidecar(header):
    """Lê o índice; ``{}`` em qualquer corrupção/ausência/cabeçalho divergente.

    Fail-safe: índice ilegível, truncado, de outra época de auditoria ou com
    entrada malformada vira miss (re-parse completo do arquivo), nunca um valor
    velho. Cada entrada só é aceita com identidade de disco íntegra (5 inteiros)
    e blob reduzido bem-formado (todos os valores são vetores de 4 campos).
    """
    try:
        with open(_portfolio_sidecar_path(), 'rb') as handle:
            payload = handle.read()
    except OSError:
        return {}
    try:
        document = json.loads(payload)
    except (ValueError, UnicodeDecodeError):
        return {}
    if (not isinstance(document, dict) or
            document.get('header') != header or
            not isinstance(document.get('files'), dict)):
        return {}
    files = {}
    for path, entry in document['files'].items():
        if not isinstance(entry, dict):
            continue
        identity = entry.get('identity')
        entries = entry.get('entries')
        if not (isinstance(identity, list) and len(identity) == 5 and
                all(type(value) is int for value in identity) and
                isinstance(entries, dict)):
            continue
        if all(isinstance(fields, list) and len(fields) == len(_PORTFOLIO_FIELDS)
               for fields in entries.values()):
            files[path] = entry
    return files


def _store_portfolio_sidecar(header, files, entries_by_file, identities):
    """Persiste atomicamente o índice do conjunto atual de arquivos.

    Só grava arquivos cacheáveis: identidade de disco real e todas as chaves
    ``intent_id`` já em ``str`` (uma chave não-``str`` viraria string no JSON e
    mudaria o veredito — nesses casos o arquivo fica fora do índice e é sempre
    re-parseado). I/O é best-effort; falha nunca quebra a auditoria.
    """
    persistable = {}
    for path in files:
        identity = identities.get(path)
        entries = entries_by_file.get(path)
        if identity is None or not isinstance(entries, dict):
            continue
        if not all(isinstance(key, str) for key in entries):
            continue
        persistable[path] = {'identity': identity, 'entries': entries}
    if not persistable:
        return
    try:
        serialized = json.dumps(
            {'header': header, 'files': persistable},
            ensure_ascii=False, sort_keys=True).encode('utf-8')
    except (TypeError, ValueError):
        return
    path = _portfolio_sidecar_path()
    temporary = None
    try:
        os.makedirs(os.path.dirname(path), exist_ok=True)
        temporary = f'{path}.tmp.{os.getpid()}'
        with open(temporary, 'wb') as handle:
            handle.write(serialized)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temporary, path)
    except OSError:
        if temporary is not None:
            try:
                os.unlink(temporary)
            except OSError:
                pass


def _parse_portfolio_file(pf):
    """Parseia um shard do portfólio em ``({intent_id: [4 campos]}, owners)``.

    Mesmas validações da leitura fria (snapshot canônico, chave obrigatória,
    duplicidade intra-arquivo) e mesma forma de exceção envolvida por linha.
    """
    payload = read_target_snapshot(pf, max_bytes=64 * 1024 * 1024)
    if not payload.endswith(b'\n') or b'\r' in payload:
        raise ValueError(f'portfolio JSONL não finalizado/canônico: {pf}')
    entries = {}
    owners = {}
    for line_number, line in enumerate(
            payload.decode('utf-8').split('\n'), 1):
        if not line:
            continue
        try:
            r = json.loads(
                line,
                object_pairs_hook=_json_object_without_duplicate_keys)
            intent_id = r['intent_id']
            if intent_id in entries:
                raise ValueError(
                    'portfolio intent_id duplicado: '
                    f'{intent_id}:{owners[intent_id]}:{pf}:{line_number}')
            entries[intent_id] = [r.get(field) for field in _PORTFOLIO_FIELDS]
            owners[intent_id] = f'{pf}:{line_number}'
        except (json.JSONDecodeError, KeyError, TypeError, ValueError) as exc:
            raise ValueError(
                f'portfolio JSONL inválido {pf}:{line_number}: {exc}') from exc
    return entries, owners


def load_portfolio():
    """Carrega o portfólio com índice incremental por ``stat`` de arquivo.

    Reaproveita o blob reduzido ``{intent_id: [page_type, lane, practice_area,
    family]}`` de cada shard cujo snapshot de disco não mudou; re-parseia só o
    delta. Fail-closed: índice ausente, cabeçalho divergente ou ``stat``
    diferente força o parse completo do arquivo. O veredito é idêntico ao da
    leitura fria — o cabeçalho invalida o índice inteiro em qualquer mudança de
    lógica do auditor.
    """
    files = sorted(glob.glob(
        os.path.join(ROOT, 'data/editorial/portfolio_v2/*.jsonl')))
    header = _portfolio_sidecar_header()
    cached_index = _load_portfolio_sidecar(header)
    pt = {}
    owners = {}
    identities = {}
    entries_by_file = {}
    for pf in files:
        identity = _portfolio_file_identity(pf)
        identities[pf] = identity
        entry = cached_index.get(pf)
        if (identity is not None and entry is not None and
                entry.get('identity') == identity):
            file_entries = entry['entries']
        else:
            file_entries, _ = _parse_portfolio_file(pf)
        entries_by_file[pf] = file_entries
        for intent_id, fields in file_entries.items():
            if intent_id in pt:
                raise ValueError(
                    'portfolio intent_id duplicado entre shards: '
                    f'{intent_id}:{owners[intent_id]}:{pf}')
            pt[intent_id] = {
                field: fields[index]
                for index, field in enumerate(_PORTFOLIO_FIELDS)
            }
            owners[intent_id] = pf
    _store_portfolio_sidecar(header, files, entries_by_file, identities)
    return pt


def is_canonical_calendar_range_ngram(tokens):
    """Ignore only date-dominated ranges, never surrounding editorial prose.

    The n-gram anti-template gate measures authorial reuse. Calendar facts are
    not authorial: every accurate page may need the same official start/end
    dates. Requiring the complete token vector ``de DAY de MONTH de YEAR a DAY
    de MONTH de YEAR`` keeps article numbers, monetary values, fragments and
    surrounding prose in scope.
    """
    return (
        len(tokens) == NGRAM
        and tokens[0] in {'de', 'desde', 'entre'}
        and re.fullmatch(r'\d{1,2}(?:º|ª)?', tokens[1]) is not None
        and tokens[2] == 'de'
        and tokens[3] in PTBR_CALENDAR_MONTHS
        and tokens[4] == 'de'
        and re.fullmatch(r'\d{4}', tokens[5]) is not None
        and tokens[6] in {'a', 'ate', 'e'}
        and re.fullmatch(r'\d{1,2}(?:º|ª)?', tokens[7]) is not None
        and tokens[8] == 'de'
        and tokens[9] in PTBR_CALENDAR_MONTHS
        and tokens[10] == 'de'
        and re.fullmatch(r'\d{4}', tokens[11]) is not None)


def is_canonical_effective_date_ngram(tokens):
    """Recognize a statute's effective-date statement as a legal fact.

    ``Lei 15.040/2024 entrou em vigor em 11 de dezembro de 2025`` is no
    more authorial than a date range. The exact ``entrou em vigor`` marker,
    a written month and a complete year keep this branch deliberately
    narrower than generic sentences that merely mention dates.
    """
    # Os únicos formatos dispensados são as três janelas sobrepostas da
    # afirmação normativa canônica completa:
    # ``A Lei 15.040/2024 entrou em vigor em 11 de dezembro de 2025``.
    # Nenhuma posição admite prosa editorial livre.
    if len(tokens) != NGRAM:
        return False

    def law_number_at(index):
        return (
            re.fullmatch(r'\d{1,3}', tokens[index]) is not None
            and re.fullmatch(r'\d{3}', tokens[index + 1]) is not None
            and re.fullmatch(r'\d{4}', tokens[index + 2]) is not None)

    prefix = (
        tuple(tokens[:2]) == ('a', 'lei')
        and law_number_at(2)
        and tuple(tokens[5:9]) == ('entrou', 'em', 'vigor', 'em')
        and re.fullmatch(r'\d{1,2}', tokens[9]) is not None
        and tokens[10] == 'de'
        and tokens[11] in PTBR_CALENDAR_MONTHS)
    middle = (
        tokens[0] == 'lei'
        and law_number_at(1)
        and tuple(tokens[4:8]) == ('entrou', 'em', 'vigor', 'em')
        and re.fullmatch(r'\d{1,2}', tokens[8]) is not None
        and tokens[9] == 'de'
        and tokens[10] in PTBR_CALENDAR_MONTHS
        and tokens[11] == 'de')
    suffix = (
        law_number_at(0)
        and tuple(tokens[3:7]) == ('entrou', 'em', 'vigor', 'em')
        and re.fullmatch(r'\d{1,2}', tokens[7]) is not None
        and tokens[8] == 'de'
        and tokens[9] in PTBR_CALENDAR_MONTHS
        and tokens[10] == 'de'
        and re.fullmatch(r'\d{4}', tokens[11]) is not None)
    return prefix or middle or suffix


def is_canonical_calendar_fact_ngram(tokens):
    return (is_canonical_calendar_range_ngram(tokens)
            or is_canonical_effective_date_ngram(tokens))


def page_ngrams(page):
    grams = set()
    for part in visible_parts(page):
        toks = words_of(part)
        for i in range(len(toks) - NGRAM + 1):
            gram = tuple(toks[i:i + NGRAM])
            if is_canonical_calendar_fact_ngram(gram):
                continue
            # O hash compacto é só pré-filtro; todo encontro é confirmado
            # pelos doze tokens exatos antes de bloquear uma página.
            grams.add(hash(gram))
    return grams


def exact_page_ngrams(page):
    """Retorna n-gramas exatos para comparação alvo-versus-estoque."""
    grams = set()
    for part in visible_parts(page):
        tokens = words_of(part)
        grams.update(
            gram for i in range(len(tokens) - NGRAM + 1)
            if not is_canonical_calendar_fact_ngram(
                gram := tuple(tokens[i:i + NGRAM])))
    return grams


DEFAULT_OFFICIAL_SOURCE_MAXIMUM = 5
CANONICAL_SIX_SOURCE_MAXIMUM = 6
CANONICAL_SIX_SOURCE_INTENTS = frozenset((
    'tel-linha-no-meu-cpf-fraude',
    'tel-roaming-internacional-conta-alta',
))


def official_source_maximum(page):
    """Mantém cinco como teto e abre seis só para matrizes canônicas 6/6.

    A exceção é deliberadamente fechada: adicionar uma sétima classe à matriz
    não amplia o orçamento por acidente, e um intent fora da allowlist nunca
    herda o teto maior apenas por possuir muitas dicas de fonte no portfólio.
    """
    intent = page.get('intent_id') if isinstance(page, dict) else None
    if intent not in CANONICAL_SIX_SOURCE_INTENTS:
        return DEFAULT_OFFICIAL_SOURCE_MAXIMUM
    requirements = TELECOM01_SOURCE_REQUIREMENTS.get(intent, ())
    required_kinds = {requirement[0] for requirement in requirements}
    required_urls = {
        TELECOM01_SOURCE_URLS.get(kind) for kind in required_kinds
    }
    if (len(requirements) == CANONICAL_SIX_SOURCE_MAXIMUM
            and len(required_kinds) == CANONICAL_SIX_SOURCE_MAXIMUM
            and None not in required_urls
            and len(required_urls) == CANONICAL_SIX_SOURCE_MAXIMUM):
        return CANONICAL_SIX_SOURCE_MAXIMUM
    return DEFAULT_OFFICIAL_SOURCE_MAXIMUM


def same_input_file(first, second):
    """Compara identidade de arquivo; realpath sozinho não cobre hardlinks."""
    try:
        return os.path.samefile(first, second)
    except OSError:
        return (os.path.realpath(os.path.abspath(first)) ==
                os.path.realpath(os.path.abspath(second)))


def shared_exact_ngram(first, second, pair_cache, page_cache):
    """Return one deterministic exact shared n-gram after the hash prefilter.

    Exact profiles are built lazily only for pages that share a compact hash.
    This keeps the global scan bounded while avoiding reconstruction of the
    same page profile for every peer and gives repair tooling an actionable
    normalized phrase instead of only ``intent~peer``.
    """
    key = tuple(sorted((id(first), id(second))))
    if key in pair_cache:
        return pair_cache[key]
    first_key = id(first)
    second_key = id(second)
    if first_key not in page_cache:
        page_cache[first_key] = exact_page_ngrams(first)
    if second_key not in page_cache:
        page_cache[second_key] = exact_page_ngrams(second)
    first_grams = page_cache[first_key]
    second_grams = page_cache[second_key]
    common = first_grams.intersection(second_grams)
    shared = min(common) if common else None
    pair_cache[key] = shared
    return shared


def pages_share_exact_ngram(first, second, pair_cache, page_cache):
    """Confirma a igualdade textual quando o hash compacto coincide."""
    return shared_exact_ngram(
        first, second, pair_cache, page_cache) is not None


def exact_ngram_field(page, gram):
    """Locate the first visible field containing an exact normalized gram."""
    for field, value in labeled_visible_parts(page):
        tokens = words_of(value)
        if any(tuple(tokens[i:i + NGRAM]) == gram
               for i in range(len(tokens) - NGRAM + 1)):
            return field
    return '(campo_nao_localizado)'


def ngram_evidence(target_intent, peer_intent, target_page, peer_page, gram):
    """Build non-blocking, deterministic evidence for one directed edge."""
    return {
        'target': f'{target_intent}~{peer_intent}',
        'phrase': ' '.join(gram),
        'field': exact_ngram_field(target_page, gram),
        'peer_field': exact_ngram_field(peer_page, gram),
    }


# Blocos legais REVOGADOS (familia inteira, extensivel): cada entrada cobre
# um diploma + faixa de artigos revogados por lei posterior ja vigente.
# Pagina que usa fonte com ancora nesses dispositivos, ou que os cita no
# texto visivel, precisa tratar a transicao no MESMO registro (mencionar a
# lei revogadora, "revogado/revogada" ou "na vigencia"); caso contrario o
# leitor e mandado para regra morta — defeito fonte_revogada. Proximas
# revogacoes: adicionar entrada aqui, sem tocar na deteccao.
REVOKED_LEGAL_SOURCES = (
    {
        # Lei 10.406/2002 (Codigo Civil), arts. 757 a 802 (contrato de
        # seguro): revogados pelo art. 133 da Lei 15.040/2024 (Marco Legal
        # dos Seguros), vigente desde dez/2025 (art. 134 — 1 ano da
        # publicacao no DOU de 10.12.2024). Conferido no texto oficial do
        # Planalto em 2026-07-14. O mesmo art. 133 tambem revoga o inciso
        # II do § 1º do art. 206 do CC e os arts. 9º a 14 do DL 73/1966,
        # mas deteccao por numero inteiro de artigo geraria falso positivo
        # (o caput do art. 206 segue vigente) — fica fora de proposito.
        'law': 'l10406',
        'law_names': ('codigo civil', 'cc'),
        'articles': range(757, 803),
        'revoked_by': 'Lei 15.040/2024, art. 133',
        'exemption_terms': ('15.040',),
        'note': 'Contrato de seguro migrou do CC para a Lei 15.040/2024.',
    },
)

# Marcadores genericos de transicao tratada (comparados no fold sem acento):
# "revogado(s)/revogada(s)" e "na vigencia" isentam o registro, junto com o
# numero da lei revogadora declarado em exemption_terms.
REVOKED_SOURCE_TRANSITION_RE = re.compile(
    r'\brevogad[oa]s?\b|\bna vigencia\b')


def revoked_source_transition_denied(value):
    """True when a field denies, rather than explains, the revocation."""
    negative_tokens = {'nao', 'nem', 'nunca', 'jamais', 'sem'}
    for clause in semantic_legal_fact_clauses(value):
        tokens = clause.split()
        for index, token in enumerate(tokens):
            if not token.startswith('revog'):
                continue
            if (declarative_occurrence_locally_negated(
                    tokens, index, 1, negative_tokens) or
                    semantic_anchor_meta_negated(clause, token)):
                return True
    return False


def revoked_source_affirmative_transition(value):
    """Accept an affirmative revoked/revogada marker, never its negation."""
    if not REVOKED_SOURCE_TRANSITION_RE.search(value):
        return False
    negative_tokens = {'nao', 'nem', 'nunca', 'jamais', 'sem'}
    for clause in semantic_legal_fact_clauses(value):
        tokens = clause.split()
        for index, token in enumerate(tokens):
            if not REVOKED_SOURCE_TRANSITION_RE.fullmatch(token):
                continue
            if (declarative_occurrence_locally_negated(
                    tokens, index, 1, negative_tokens) or
                    semantic_anchor_meta_negated(clause, token)):
                continue
            return True
    return False


def revoked_source_transition_treated(values, entry):
    """Record-level transition boundary shared by visible/source metadata."""
    for value in values:
        if 'na vigencia' in value:
            return True
        if (any(term in value for term in entry['exemption_terms']) and
                not revoked_source_transition_denied(value)):
            return True
        if revoked_source_affirmative_transition(value):
            return True
    return False


def revoked_source_citation_re(entry):
    """Citacao textual "art(s). N(, N | e N | a N)* do <diploma>" (fold)."""
    law_names = '|'.join(re.escape(name) for name in entry['law_names'])
    return re.compile(
        r'\bart(?:igo)?s?\.?\s*'
        r'(\d{1,4}(?:\s*(?:,|e|ao|ate|a)\s*\d{1,4})*)'
        r'\s+d[oe]\s+(?:' + law_names + r')\b')


def revoked_source_defects(page):
    """fonte_revogada: apoio em dispositivo revogado sem tratar a transicao.

    Retorna evidencias 'campo:artN[_N...]' (uma por campo) quando o registro
    (a) tem official_source com ancora #artN em diploma/faixa revogados de
    REVOKED_LEGAL_SOURCES, ou (b) cita "art. N do <diploma>" no texto
    visivel (title/h1/meta/opening/sections/faq), e NAO menciona a
    transicao em nenhum lugar do registro (lei revogadora, "revogado/
    revogada", "na vigencia" — inclusive em name/anchor_claim das fontes).
    Pagina que explica a revogacao trata a transicao e nao e defeito.
    """
    findings = []
    folded_fields = [
        (field, deaccent(value).lower())
        for field, value in labeled_visible_parts(page)]
    sources = [source for source in (page.get('official_sources') or [])
               if isinstance(source, dict)]
    record_folds = (
        [fold for _, fold in folded_fields] +
        [deaccent(str(source.get(key) or '')).lower()
         for source in sources for key in ('name', 'anchor_claim')])
    for entry in REVOKED_LEGAL_SOURCES:
        if revoked_source_transition_treated(record_folds, entry):
            continue
        articles = entry['articles']
        hits_by_field = {}
        for index, source in enumerate(sources):
            url = str(source.get('url') or '').lower()
            if entry['law'] not in url:
                continue
            anchored = sorted(
                int(m.group(1)) for m in re.finditer(r'#art(\d+)', url)
                if int(m.group(1)) in articles)
            if anchored:
                hits_by_field[f'official_sources[{index}].url'] = anchored
        citation_re = revoked_source_citation_re(entry)
        for field, fold in folded_fields:
            cited = sorted({
                int(number)
                for match in citation_re.finditer(fold)
                for number in re.findall(r'\d+', match.group(1))
                if int(number) in articles})
            if cited:
                hits_by_field[field] = cited
        for field, hit_articles in hits_by_field.items():
            findings.append(
                field + ':art' +
                '_'.join(str(number) for number in hit_articles))
    return findings


def read_target_snapshot(path, max_bytes=TARGET_SNAPSHOT_MAX_BYTES):
    """Read one immutable byte snapshot of a finalized shard.

    The descriptor is opened without following a terminal symlink when the
    platform supports it.  Metadata is checked before and after the bounded
    read so the caller never silently audits a partial in-place rewrite.
    Cross-process changes after this read are detected by matching this
    snapshot's SHA-256 to the independently produced Go query report.
    """
    flags = os.O_RDONLY
    flags |= getattr(os, 'O_CLOEXEC', 0)
    flags |= getattr(os, 'O_NOFOLLOW', 0)
    descriptor = os.open(os.fspath(path), flags)
    try:
        before = os.fstat(descriptor)
        if not stat.S_ISREG(before.st_mode):
            raise OSError(f'target shard is not a regular file: {path}')
        if before.st_size < 0 or before.st_size > max_bytes:
            raise OSError(
                f'target shard exceeds snapshot limit: '
                f'bytes={before.st_size} max={max_bytes}')
        chunks = []
        remaining = max_bytes + 1
        while remaining > 0:
            chunk = os.read(descriptor, min(1024 * 1024, remaining))
            if not chunk:
                break
            chunks.append(chunk)
            remaining -= len(chunk)
        payload = b''.join(chunks)
        after = os.fstat(descriptor)
    finally:
        os.close(descriptor)
    before_identity = (
        before.st_dev, before.st_ino, before.st_size,
        before.st_mtime_ns, before.st_ctime_ns)
    after_identity = (
        after.st_dev, after.st_ino, after.st_size,
        after.st_mtime_ns, after.st_ctime_ns)
    if before_identity != after_identity or len(payload) != before.st_size:
        raise OSError(f'target shard changed while snapshotting: {path}')
    if len(payload) > max_bytes:
        raise OSError(
            f'target shard exceeds snapshot limit: '
            f'bytes>{max_bytes}')
    return payload


_ACTIVE_PRIVATE_FALSE_CONTROLS = (
    'public', 'publication_allowed', 'publication_candidate',
    'render_allowed', 'sitemap_allowed', 'indexable', 'approval',
    'publicly_indexable', 'manifest_allowed',
)


def private_state_open_controls(page):
    """Return controls that contradict a private V2 record.

    This mirrors the fail-closed product contract enforced by
    ``check-v2-finalized-commit`` and the Go ingest. Historical absence is a
    closed zero value, but a materialized control must use the exact closed
    representation; ``0``, ``null`` and whitespace are not aliases for
    ``false`` or the empty public path. Tombstones remain private records too:
    checking before the ``skipped`` fast path prevents a malformed historical
    row from bypassing publication closure merely because it is inactive.
    """
    open_controls = [
        field for field in _ACTIVE_PRIVATE_FALSE_CONTROLS
        if field in page and page[field] is not False
    ]
    if ('index_policy' in page and
            page.get('index_policy') != 'noindex'):
        open_controls.append('index_policy')
    if 'public_path' in page and page.get('public_path') != '':
        open_controls.append('public_path')
    return open_controls


def audit_file(path, portfolio, expect_n=None, collect_pages=False,
               snapshot_bytes=None):
    defects = collections.defaultdict(list)
    pages = []
    page_lines = []
    bad_lines = 0
    if snapshot_bytes is None:
        snapshot_bytes = read_target_snapshot(path)
    if not isinstance(snapshot_bytes, bytes):
        raise TypeError('snapshot_bytes must be bytes')
    if not snapshot_bytes.endswith(b'\n'):
        defects['json_invalido'].append('jsonl_sem_lf_terminal')
    if b'\r' in snapshot_bytes:
        defects['json_invalido'].append('jsonl_cr_ou_crlf_nao_canonico')
    decoded_snapshot = snapshot_bytes.decode('utf-8')
    # JSONL records are delimited by LF. ``str.splitlines`` would also split
    # the valid JSON characters U+2028/U+2029 when they occur inside a string.
    for idx, line in enumerate(decoded_snapshot.split('\n'), 1):
        if not line.strip():
            continue
        try:
            page = json.loads(
                line, object_pairs_hook=_json_object_without_duplicate_keys)
            if not isinstance(page, dict):
                raise TypeError('pagina JSON deve ser objeto')
            pages.append(page)
            page_lines.append(idx)
        except (json.JSONDecodeError, TypeError):
            bad_lines += 1
            defects['json_invalido'].append(f'linha_{idx}')
    active_page_count = sum(1 for page in pages if not page.get('skipped'))
    if active_page_count > INCREMENTAL_TARGET_MAX_PAGES:
        defects['distinctness_target_page_budget_exceeded'].append(
            f'pages={active_page_count} max={INCREMENTAL_TARGET_MAX_PAGES}')
        result = {
            'file': os.path.relpath(path, ROOT),
            'pages': len(pages),
            'active_pages': active_page_count,
            'defects': dict(defects),
            'ok': False,
        }
        if collect_pages:
            result['_loaded_pages'] = pages
            result['_loaded_page_lines'] = page_lines
            result['_page_gram_sets'] = []
            result['_snapshot_digest'] = hashlib.sha256(
                snapshot_bytes).hexdigest()
        return result
    title_ct = collections.Counter(norm_key(p.get('title')) for p in pages if not p.get('skipped'))
    meta_ct = collections.Counter(norm_key(p.get('meta_description')) for p in pages if not p.get('skipped'))
    h1_ct = collections.Counter(norm_key(p.get('h1')) for p in pages if not p.get('skipped'))
    head_ct = collections.Counter()
    # Um único instante governa proveniência e transições jurídicas durante
    # toda a auditoria. Isso evita que um lote atravesse meia-noite com
    # decisões divergentes entre páginas e mantém o relógio injetável nos
    # checks diretos.
    validation_now = datetime.datetime.now(datetime.timezone.utc)
    for p in pages:
        if p.get('skipped'):
            continue
        for s in p.get('sections', []) or []:
            head_ct[norm_key(s.get('heading'))] += 1
    seen_ngrams = {}
    exact_ngram_pair_cache = {}
    exact_ngram_page_cache = {}
    local_ngram_peers = collections.defaultdict(set)
    local_ngram_shared = {}
    page_gram_sets = [None] * len(pages)
    for page_index, p in enumerate(pages):
        intent_id = p.get('intent_id')
        iid = intent_id or '(sem-intent)'
        for control in private_state_open_controls(p):
            defects['public_state_open'].append(f'{iid}:{control}')
        if p.get('skipped'):
            if not p.get('intent_id') or not (p.get('skip_reason') or '').strip():
                defects['tombstone_invalido'].append(iid)
            else:
                defects['skipped'].append(iid)
            continue
        # O ingest Go fecha para toda pagina ativa cujo intent_id nao pertence
        # ao portfolio. O auditor Python precisa expor o mesmo bloqueio sem
        # abandonar os demais diagnosticos do registro: um orphan pode ter,
        # simultaneamente, defeitos editoriais que o reconciliador deve ver.
        if intent_id and intent_id not in portfolio:
            defects['intent_fora_portfolio'].append(intent_id)
        elif intent_id:
            portfolio_meta = portfolio[intent_id]
            # Legacy shards may omit derived portfolio metadata entirely. If
            # a writer materializes the field, however, it must not contradict
            # the canonical contract (for example ``guide`` in place of
            # ``guia_problema``).
            if ('page_type' in p and
                    p.get('page_type') != portfolio_meta.get('page_type')):
                defects['portfolio_page_type_mismatch'].append(iid)
            if ('lane' in p and
                    p.get('lane') != portfolio_meta.get('lane')):
                defects['portfolio_lane_mismatch'].append(iid)
            if ('practice_area' in p and
                    p.get('practice_area') !=
                    portfolio_meta.get('practice_area')):
                defects['portfolio_practice_area_mismatch'].append(iid)
            if ('family' in p and
                    p.get('family') != portfolio_meta.get('family')):
                defects['portfolio_family_mismatch'].append(iid)
        grams = page_ngrams(p)
        page_gram_sets[page_index] = grams
        if not p.get('intent_id') or not p.get('sections') or not (p.get('opening') or '').strip():
            defects['estrutura'].append(iid)
            continue
        meta = load_meta(portfolio, p)
        title = (p.get('title') or '').strip()
        if not (20 <= len(title) <= 65):
            defects['title_len'].append(iid)
        if title and title_ct[norm_key(title)] > 1:
            defects['title_dup'].append(iid)
        ml = len((p.get('meta_description') or '').strip())
        if not (70 <= ml <= 160):
            defects['meta_len'].append(iid)
        if meta_ct[norm_key(p.get('meta_description'))] > 1:
            defects['meta_dup'].append(iid)
        h1 = (p.get('h1') or '').strip()
        if not h1:
            defects['h1_vazio'].append(iid)
        elif norm_key(h1) == norm_key(title):
            defects['h1_igual_title'].append(iid)
        elif h1_ct[norm_key(h1)] > 1:
            defects['h1_dup'].append(iid)
        for field, value in labeled_visible_parts(p):
            if MALFORMED_PTBR_COM_ACRONYM_CONTINUITY_RE.search(value):
                defects['ptbr_conectivo_mecanico'].append(
                    f'{iid}:{field}')
                break
        for field, value in labeled_visible_parts(p):
            escaped = literal_control_escape(value)
            if escaped:
                defects['escape_controle_literal'].append(
                    f'{iid}:{field}:{escaped[1]}')
                break
        for field, value in labeled_visible_parts(p):
            ending = terminal_fragment(value)
            if ending:
                defects['fragmento_terminal'].append(
                    f'{iid}:{field}:{ending.replace(" ", "_")}')
                break
        real = body_word_count(p)
        band = BANDS.get(meta['page_type'])
        if band:
            lo, hi = band
            if real < lo * 9 // 10:
                defects['faixa_thin'].append(iid)
            elif real > hi * 11 // 10:
                defects['faixa_esticada'].append(iid)
        declared = p.get('word_count')
        if (not isinstance(declared, int) or isinstance(declared, bool) or
                declared <= 0):
            defects['word_count_missing_or_invalid'].append(iid)
        elif real > 0 and abs(declared - real) * 10 > real:
            defects['wc_incoerente'].append(iid)
        sources = p.get('official_sources', []) or []
        good_hosts = [s for s in sources if source_host_allowed(s.get('url'))]
        if len(good_hosts) < 2:
            defects['fontes_min'].append(iid)
        if len(sources) > official_source_maximum(p):
            defects['fontes_max'].append(iid)
        if len(good_hosts) != len(sources):
            defects['fontes_host'].append(iid)
        normalized_sources = {}
        for source_index, source in enumerate(sources):
            if not (source.get('name') or '').strip():
                defects['official_source_name_missing'].append(iid)
            if not (source.get('anchor_claim') or '').strip():
                defects['official_source_anchor_claim_missing'].append(iid)
            verified_at = parse_source_verified_at(source.get('verified_at'))
            if verified_at is None:
                defects['official_source_verified_at_invalid'].append(iid)
            elif verified_at > validation_now:
                defects['official_source_verified_at_future'].append(iid)
            status = source.get('http_status')
            if (not isinstance(status, int) or isinstance(status, bool) or
                    status not in {200, 203, 206}):
                defects['official_source_http_status_invalid'].append(iid)
            source_url = (source.get('url') or '').strip()
            if not source_host_allowed(source_url):
                continue
            if not source_has_significant_path(source_url):
                defects['official_source_root_url_not_specific'].append(iid)
            elif source_is_institution_homepage(source_url):
                defects['official_source_homepage_not_specific'].append(iid)
            normalized = normalized_source_url(source_url)
            if normalized in normalized_sources:
                defects['official_source_url_duplicate'].append(iid)
            else:
                normalized_sources[normalized] = source_index
        for reason in current_legal_fact_reasons(
                p, evaluation_date=validation_now):
            defects['current_legal_fact'].append(f'{iid}:{reason}')
        # Granularidade de artigo (WRITING_SPEC §2, espelha o gate Go
        # public_source_label_missing_article_granularity): fonte com ancora
        # #artN de CDC (l8078) ou Codigo Civil (l10406) exige o dispositivo
        # citado no corpo quando o corpo menciona o diploma.
        body_norm = norm_key(' '.join(
            [p.get('opening') or ''] +
            [s.get('text') or '' for s in (p.get('sections') or [])] +
            [q.get('a') or '' for q in (p.get('faq') or [])]))
        for s in sources:
            url = (s.get('url') or '').lower()
            m = re.search(r'#art(\d+)', url)
            if not m:
                continue
            art = m.group(1)
            diploma = None
            if 'l8078' in url:
                diploma = 'defesa do consumidor'
            elif 'l10406' in url:
                diploma = 'codigo civil'
            # Citação em lista ("arts. 186 e 927") é estilo legítimo: basta o
            # NÚMERO do artigo presente no corpo (em texto jurídico o número
            # aparece como dispositivo).
            if (diploma and diploma in body_norm and
                    not article_number_is_cited(body_norm, art)):
                defects['fonte_artigo_nao_citado'].append(iid)
                break
        # Transicao legislativa (REVOKED_LEGAL_SOURCES, ex.: Lei 15.040/2024
        # x arts. 757-802 do CC): fonte com ancora ou citacao textual de
        # dispositivo revogado sem explicar a revogacao no proprio registro.
        for finding in revoked_source_defects(p):
            defects['fonte_revogada'].append(f'{iid}:{finding}')
        lane = p.get('lane')
        if lane not in ('comercial', 'informativa') or (
                meta['lane'] and lane != meta['lane']):
            defects['lane'].append(iid)
        total_sections = len(p.get('sections', []) or []) + (1 if p.get('faq') else 0)
        if total_sections < MIN_SECTIONS.get(meta['page_type'], DEFAULT_MIN_SECTIONS):
            defects['secoes_min'].append(iid)
        topics = [t for t in (p.get('internal_link_topics') or []) if str(t).strip()]
        if len(topics) < 2:
            defects['links_internos'].append(iid)
        if len(p.get('faq', []) or []) > MAX_FAQ:
            defects['faq_max'].append(iid)
        for s in p.get('sections', []) or []:
            if is_generic_heading(s.get('heading')):
                defects['heading_generico'].append(iid)
                break
        for s in p.get('sections', []) or []:
            if head_ct[norm_key(s.get('heading'))] > 1:
                defects['heading_dup_arquivo'].append(iid)
                break
        for g in grams:
            entry = seen_ngrams.get(g)
            if entry is None:
                seen_ngrams[g] = (page_index, iid, p)
                continue
            representatives = entry if isinstance(entry, list) else [entry]
            for owner_index, owner_iid, owner_page in representatives:
                shared = shared_exact_ngram(
                    owner_page, p, exact_ngram_pair_cache,
                    exact_ngram_page_cache)
                if shared is not None:
                    local_ngram_peers[page_index].add(
                        (owner_index, owner_iid))
                    local_ngram_peers[owner_index].add((page_index, iid))
                    local_ngram_shared[(page_index, owner_index)] = shared
                    local_ngram_shared[(owner_index, page_index)] = shared
            current = (page_index, iid, p)
            if isinstance(entry, list):
                entry.append(current)
            else:
                seen_ngrams[g] = [entry, current]
        joined = ' '.join(visible_parts(p))
        if VOCAB_RE.search(joined):
            defects['vocab_interno'].append(iid)
        if p.get('needs_source_research'):
            defects['fonte_nao_verificada'].append(iid)
    for page_index, peers in sorted(local_ngram_peers.items()):
        iid = pages[page_index].get('intent_id') or '(sem-intent)'
        for peer_index, peer_iid in sorted(peers):
            defects['ngram_dup'].append(f'{iid}~{peer_iid}')
    result = {
        'file': os.path.relpath(path, ROOT),
        'pages': len(pages),
        'active_pages': sum(1 for page in pages if not page.get('skipped')),
        'defects': {k: sorted(set(v)) for k, v in defects.items() if v},
    }
    local_evidence = []
    for page_index, peers in sorted(local_ngram_peers.items()):
        iid = pages[page_index].get('intent_id') or '(sem-intent)'
        for peer_index, peer_iid in sorted(peers):
            gram = local_ngram_shared[(page_index, peer_index)]
            local_evidence.append(ngram_evidence(
                iid, peer_iid, pages[page_index], pages[peer_index], gram))
    if local_evidence:
        result['evidence'] = {'ngram_dup': local_evidence}
    if expect_n is not None and len(pages) != expect_n:
        result['defects']['contagem'] = [f'esperado={expect_n} real={len(pages)}']
    # 'skipped' informa mas nao reprova sozinho (tombstone honesto e valido).
    blocking = {k: v for k, v in result['defects'].items() if k != 'skipped'}
    result['ok'] = not blocking
    if collect_pages:
        result['_loaded_pages'] = pages
        result['_loaded_page_lines'] = page_lines
        result['_page_gram_sets'] = page_gram_sets
        result['_snapshot_digest'] = hashlib.sha256(
            snapshot_bytes).hexdigest()
    return result


def load_meta(portfolio, page):
    info = portfolio.get(page.get('intent_id'), {})
    return {'page_type': info.get('page_type'), 'lane': info.get('lane')}


def is_finalized_v2_path(path):
    """Return true only for canonical shards, never writer staging files."""
    name = os.path.basename(path).lower()
    if not name.endswith('.jsonl') or name.startswith('.'):
        return False
    return not any(marker in name for marker in (
        '.partial.', '.candidate.', '.tmp.', '.stale.', '.poisoned.'))


def supersession_archive_issue(fname, page, target, source_line,
                                canonical_line, cache, consumed=None,
                                root=None, trusted_archives=None):
    root = os.path.abspath(ROOT if root is None else os.fspath(root))
    if trusted_archives is None:
        trusted_archives = TRUSTED_SUPERSESSION_ARCHIVE_SHA256
    archive_rel = page.get('supersession_archive')
    record_sha = page.get('superseded_record_sha256')
    if (page.get('index_policy') != 'noindex' or
            any(page.get(flag) is not False for flag in (
                'render_allowed', 'sitemap_allowed',
                'publication_allowed')) or
            any(page.get(flag) is not None and page.get(flag) is not False
                for flag in ('approval', 'publicly_indexable')) or
            (page.get('public_path') is not None and
             (not isinstance(page.get('public_path'), str) or
              bool(page.get('public_path').strip())))):
        return 'tombstone_public_flags_invalid'
    if (not isinstance(archive_rel, str) or not archive_rel.strip() or
            archive_rel != archive_rel.strip() or
            not archive_rel.startswith('data/editorial/v2_superseded/') or
            posixpath.normpath(archive_rel) != archive_rel or
            not archive_rel.endswith('.jsonl')):
        return 'archive_path_invalid'
    if (not isinstance(record_sha, str) or
            re.fullmatch(r'[0-9a-fA-F]{64}', record_sha.strip()) is None):
        return 'archive_hash_invalid'
    record_sha = record_sha.strip().lower()
    root_real = os.path.realpath(root)
    archive_root = os.path.join(
        root_real, 'data', 'editorial', 'v2_superseded')
    archive_path = os.path.abspath(os.path.join(
        root_real, *archive_rel.split('/')))
    try:
        if os.path.commonpath((archive_root, archive_path)) != archive_root:
            return 'archive_path_invalid'
    except ValueError:
        return 'archive_path_invalid'
    if (os.path.realpath(archive_root) != archive_root or
            (os.path.lexists(archive_path) and
             os.path.realpath(archive_path) != archive_path)):
        return 'archive_path_invalid'
    expected_archive_sha = trusted_archives.get(archive_rel)
    if (not isinstance(expected_archive_sha, str) or
            re.fullmatch(r'[0-9a-f]{64}', expected_archive_sha) is None):
        return 'archive_untrusted'
    if archive_path not in cache:
        try:
            # Import tardio evita ciclo no startup: o produtor usa este
            # auditor para DEC-020 e o auditor usa apenas seu reader seguro.
            # Fallback de sys.path: invocado como SCRIPT (python3
            # tools/audit_v2_pages.py --global), sys.path[0] é tools/ e o
            # pacote 'tools' não resolve — quebrava o audit_global inteiro
            # com ModuleNotFoundError (visto 2026-07-14 no relaunch-review).
            try:
                from tools import generate_v2_review_queue as queue_producer
            except ModuleNotFoundError:
                import sys as _sys
                _repo_root = os.path.dirname(
                    os.path.dirname(os.path.abspath(__file__)))
                if _repo_root not in _sys.path:
                    _sys.path.insert(0, _repo_root)
                from tools import generate_v2_review_queue as queue_producer
            snapshot = queue_producer.read_regular_file_snapshot(
                archive_path, max_bytes=64 * 1024 * 1024)
            if snapshot.digest != expected_archive_sha:
                return 'archive_digest_mismatch'
            records = []
            if (not snapshot.payload or
                    not snapshot.payload.endswith(b'\n')):
                raise ValueError('archive sem newline terminal')
            for line_number, line in enumerate(
                    snapshot.payload[:-1].split(b'\n'), 1):
                if not line:
                    raise ValueError('blank archive line')
                record = queue_producer.decode_json_no_duplicate_keys(
                    line, f'{archive_rel}:{line_number}')
                if not isinstance(record, dict):
                    raise ValueError('archive record is not an object')
                records.append(record)
            cache[archive_path] = (records, snapshot.digest)
        except (OSError, UnicodeDecodeError, ValueError,
                json.JSONDecodeError):
            cache[archive_path] = None
    cached_archive = cache[archive_path]
    if cached_archive is None:
        return 'archive_invalid'
    records, _ = cached_archive
    iid = (page.get('intent_id') or '').strip()
    matches = [record for record in records if
               (record.get('intent_id') or '').strip() == iid and
               (record.get('source_shard') or '').strip() ==
               os.path.basename(fname) and
               (record.get('source_record_sha256') or '').strip().lower() ==
               record_sha]
    if len(matches) != 1:
        return 'archive_record_not_unique'
    record = matches[0]
    positive_int = lambda value: (
        isinstance(value, int) and not isinstance(value, bool) and value > 0)
    valid_sha256 = lambda value: (
        isinstance(value, str) and value == value.strip() and
        re.fullmatch(r'[0-9a-fA-F]{64}', value) is not None)
    checked_at = record.get('checked_at')
    if (type(record.get('schema_version')) is not int or
            record.get('schema_version') != 1 or
            not positive_int(source_line) or
            not positive_int(canonical_line) or
            not positive_int(record.get('source_line')) or
            not positive_int(record.get('canonical_line')) or
            record.get('source_line') != source_line or
            record.get('canonical_line') != canonical_line or
            not valid_sha256(record.get('source_shard_sha256')) or
            not valid_sha256(record.get('canonical_shard_sha256')) or
            record.get('index_policy') != 'noindex' or
            not isinstance(checked_at, str) or
            checked_at != checked_at.strip() or
            parse_source_verified_at(checked_at) is None):
        return 'archive_record_metadata_invalid'
    if (record.get('record_type') != 'v2_duplicate_intent_supersession' or
            (record.get('canonical_shard') or '').strip() != target or
            any(record.get(flag) is not False for flag in (
                'render_allowed', 'sitemap_allowed',
                'publication_allowed')) or
            any(record.get(flag) is not None and
                record.get(flag) is not False
                for flag in ('approval', 'publicly_indexable')) or
            (record.get('public_path') is not None and
             (not isinstance(record.get('public_path'), str) or
              bool(record.get('public_path').strip())))):
        return 'archive_record_invalid'
    original_line = record.get('original_line')
    if (not isinstance(original_line, str) or
            hashlib.sha256(original_line.encode('utf-8')).hexdigest() !=
            record_sha):
        return 'archive_original_hash_mismatch'
    try:
        from tools import generate_v2_review_queue as queue_producer
        original = queue_producer.decode_json_no_duplicate_keys(
            original_line, 'supersession original_line')
    except (TypeError, ValueError):
        return 'archive_original_invalid'
    if (not isinstance(original, dict) or original.get('skipped') or
            (original.get('intent_id') or '').strip() != iid):
        return 'archive_original_not_active_intent'
    if consumed is not None:
        claim = (archive_rel, os.path.basename(fname), iid, record_sha)
        if claim in consumed:
            return 'archive_record_reused'
        consumed.add(claim)
    return ''


def _trusted_supersession_archive_records(root, archive_rel,
                                          trusted_archives, cache):
    """Load one SHA-pinned supersession archive through the shared cache.

    Same trust, path-safety and digest discipline as
    ``supersession_archive_issue``; any failure returns ``None`` instead of an
    issue code because the caller only uses the rows as optional evidence —
    an archive that does not authenticate simply authenticates nothing.
    """
    if (not isinstance(archive_rel, str) or not archive_rel.strip() or
            archive_rel != archive_rel.strip() or
            not archive_rel.startswith('data/editorial/v2_superseded/') or
            posixpath.normpath(archive_rel) != archive_rel or
            not archive_rel.endswith('.jsonl')):
        return None
    expected_archive_sha = trusted_archives.get(archive_rel)
    if (not isinstance(expected_archive_sha, str) or
            re.fullmatch(r'[0-9a-f]{64}', expected_archive_sha) is None):
        return None
    root_real = os.path.realpath(root)
    archive_root = os.path.join(
        root_real, 'data', 'editorial', 'v2_superseded')
    archive_path = os.path.abspath(os.path.join(
        root_real, *archive_rel.split('/')))
    try:
        if os.path.commonpath((archive_root, archive_path)) != archive_root:
            return None
    except ValueError:
        return None
    if (os.path.realpath(archive_root) != archive_root or
            (os.path.lexists(archive_path) and
             os.path.realpath(archive_path) != archive_path)):
        return None
    if archive_path not in cache:
        try:
            try:
                from tools import generate_v2_review_queue as queue_producer
            except ModuleNotFoundError:
                import sys as _sys
                _repo_root = os.path.dirname(
                    os.path.dirname(os.path.abspath(__file__)))
                if _repo_root not in _sys.path:
                    _sys.path.insert(0, _repo_root)
                from tools import generate_v2_review_queue as queue_producer
            snapshot = queue_producer.read_regular_file_snapshot(
                archive_path, max_bytes=64 * 1024 * 1024)
            if snapshot.digest != expected_archive_sha:
                return None
            records = []
            if (not snapshot.payload or
                    not snapshot.payload.endswith(b'\n')):
                raise ValueError('archive sem newline terminal')
            for line_number, line in enumerate(
                    snapshot.payload[:-1].split(b'\n'), 1):
                if not line:
                    raise ValueError('blank archive line')
                record = queue_producer.decode_json_no_duplicate_keys(
                    line, f'{archive_rel}:{line_number}')
                if not isinstance(record, dict):
                    raise ValueError('archive record is not an object')
                records.append(record)
            cache[archive_path] = (records, snapshot.digest)
        except (OSError, UnicodeDecodeError, ValueError,
                json.JSONDecodeError):
            cache[archive_path] = None
    cached_archive = cache[archive_path]
    if cached_archive is None:
        return None
    records, _ = cached_archive
    return records


def _restored_original_claim(record, pages_dir, file_set,
                             occurrences_by_intent,
                             active_by_file_intent,
                             active_raw_by_file_intent):
    """Authenticate one archived original restored as the sole active line.

    Mirror of the ``ExactActiveSources`` acceptance of the Go supersession
    gate (``internal/v2supersessionintegrity/integrity.go``): the trusted
    archive row must be structurally closed, the live record must sit in the
    exact ``source_shard`` with bytes identical to the archived preimage
    (``original_line``/``source_record_sha256``), and the intent must have no
    other occurrence — active or tombstone — anywhere in the finalized stock.
    Returns ``((source_shard, intent_id), source_record_sha256)`` or ``None``.
    """
    if not isinstance(record, dict):
        return None
    positive_int = lambda value: (
        isinstance(value, int) and not isinstance(value, bool) and value > 0)
    valid_sha256 = lambda value: (
        isinstance(value, str) and value == value.strip() and
        re.fullmatch(r'[0-9a-fA-F]{64}', value) is not None)
    iid = record.get('intent_id')
    source = record.get('source_shard')
    canonical = record.get('canonical_shard')
    record_sha = record.get('source_record_sha256')
    checked_at = record.get('checked_at')
    if (record.get('record_type') != 'v2_duplicate_intent_supersession' or
            type(record.get('schema_version')) is not int or
            record.get('schema_version') != 1 or
            not isinstance(iid, str) or not iid or iid != iid.strip() or
            not isinstance(source, str) or not source or
            source != source.strip() or
            source != os.path.basename(source) or source in ('.', '..') or
            not source.endswith('.jsonl') or
            not isinstance(canonical, str) or not canonical or
            canonical != canonical.strip() or
            canonical != os.path.basename(canonical) or
            canonical in ('.', '..') or
            not positive_int(record.get('source_line')) or
            not positive_int(record.get('canonical_line')) or
            not valid_sha256(record_sha) or
            not valid_sha256(record.get('source_shard_sha256')) or
            not valid_sha256(record.get('canonical_shard_sha256')) or
            record.get('index_policy') != 'noindex' or
            any(record.get(flag) is not False for flag in (
                'render_allowed', 'sitemap_allowed',
                'publication_allowed')) or
            any(record.get(flag) is not None and
                record.get(flag) is not False
                for flag in ('approval', 'publicly_indexable')) or
            (record.get('public_path') is not None and
             (not isinstance(record.get('public_path'), str) or
              bool(record.get('public_path').strip()))) or
            not isinstance(checked_at, str) or
            checked_at != checked_at.strip() or
            parse_source_verified_at(checked_at) is None):
        return None
    record_sha = record_sha.strip().lower()
    original_line = record.get('original_line')
    if (not isinstance(original_line, str) or
            hashlib.sha256(original_line.encode('utf-8')).hexdigest() !=
            record_sha):
        return None
    try:
        from tools import generate_v2_review_queue as queue_producer
        original = queue_producer.decode_json_no_duplicate_keys(
            original_line, 'supersession original_line')
    except (TypeError, ValueError):
        return None
    if (not isinstance(original, dict) or original.get('skipped') or
            (original.get('intent_id') or '').strip() != iid):
        return None
    source_file = os.path.join(pages_dir, source)
    if source_file not in file_set:
        return None
    if occurrences_by_intent.get(iid, 0) != 1:
        return None
    if active_by_file_intent.get((source_file, iid), 0) != 1:
        return None
    live_raw = active_raw_by_file_intent.get((source_file, iid))
    if live_raw != original_line.encode('utf-8'):
        return None
    return (source, iid), record_sha


def validated_duplicate_supersession_winners(root=None,
                                             trusted_archives=None):
    """Return canonical active intents backed by authenticated supersession.

    This is a metadata-only projection of DEC-020 for queue producers.  It
    deliberately does not run the global text auditor: every accepted pair
    still goes through the same archive validator used by ``audit_global``.
    A winner is exposed on exactly two grounds, both fail-closed:

    - tombstone: the intent is the sole active occurrence in the finalized
      stock and exactly one ``duplicate_intent_consolidated`` tombstone in
      another shard authenticates it against a SHA-pinned archive; or
    - restored original (mirror of the Go gate's ``ExactActiveSources``): a
      SHA-pinned archive row proves the active line is byte-identical to the
      archived preimage, lives in its exact ``source_shard`` and the intent
      has no other occurrence anywhere in the stock.

    Malformed or ambiguous chains stay out of the result.
    """
    root = os.path.abspath(ROOT if root is None else os.fspath(root))
    if trusted_archives is None:
        trusted_archives = TRUSTED_SUPERSESSION_ARCHIVE_SHA256
    pages_dir = os.path.join(root, 'data', 'editorial', 'v2_pages')
    from tools import generate_v2_review_queue as queue_producer
    files = sorted(
        path for path in glob.glob(os.path.join(pages_dir, '*.jsonl'))
        if is_finalized_v2_path(path)
    )
    file_set = set(files)
    snapshots = {
        fname: queue_producer.read_regular_file_snapshot(
            fname, max_bytes=64 * 1024 * 1024)
        for fname in files
    }
    active_by_intent = collections.Counter()
    active_by_file_intent = collections.Counter()
    active_line_by_file_intent = {}
    occurrences_by_intent = collections.Counter()
    active_raw_by_file_intent = {}
    supersessions = []
    issues = []
    for fname in files:
        payload = snapshots[fname].payload
        if not payload or not payload.endswith(b'\n'):
            raise ValueError(
                f'{os.path.basename(fname)}: sem newline terminal')
        for line_number, line in enumerate(payload[:-1].split(b'\n'), 1):
            if not line:
                raise ValueError(
                    f'{os.path.basename(fname)}:linha_{line_number}:blank')
            page = queue_producer.decode_json_no_duplicate_keys(
                line, f'{os.path.basename(fname)}:{line_number}')
            if not isinstance(page, dict):
                raise ValueError(
                    f'{os.path.basename(fname)}:linha_{line_number}:not_object')
            iid = (page.get('intent_id') or '').strip()
            if iid:
                occurrences_by_intent[iid] += 1
            if not page.get('skipped'):
                if iid:
                    active_by_intent[iid] += 1
                    active_by_file_intent[(fname, iid)] += 1
                    active_line_by_file_intent[(fname, iid)] = line_number
                    active_raw_by_file_intent[(fname, iid)] = line
                continue
            if (page.get('superseded_by') is not None or
                    (page.get('skip_reason') or '').strip() ==
                    'duplicate_intent_consolidated'):
                supersessions.append((fname, line_number, page))

    archive_cache = {}
    consumed_archive_claims = set()
    valid_claims = collections.defaultdict(list)
    for fname, source_line, page in supersessions:
        source = os.path.basename(fname)
        iid = (page.get('intent_id') or '').strip()
        target = page.get('superseded_by')
        reason = (page.get('skip_reason') or '').strip()
        issue = ''
        if not iid:
            issue = 'intent_empty'
        elif reason != 'duplicate_intent_consolidated':
            issue = 'reason'
        elif not isinstance(target, str) or not target.strip():
            issue = 'target_empty'
        elif (target != target.strip() or
              target != os.path.basename(target) or
              target in ('.', '..')):
            issue = 'target_not_canonical_shard_name'
        else:
            target_file = os.path.join(pages_dir, target)
            if target_file == fname:
                issue = 'target_is_source'
            elif target_file not in file_set:
                issue = 'target_missing'
            elif active_by_intent[iid] != 1:
                issue = 'winner_not_globally_unique'
            elif active_by_file_intent[(target_file, iid)] != 1:
                issue = 'target_active_intent_not_unique'
            else:
                issue = supersession_archive_issue(
                    fname, page, target, source_line,
                    active_line_by_file_intent[(target_file, iid)],
                    archive_cache, consumed_archive_claims,
                    root=root, trusted_archives=trusted_archives)
        if issue:
            issues.append(f'{source}:{iid or "(sem-intent)"}:{issue}')
            continue
        valid_claims[(target, iid)].append((source, source_line))

    # Segunda base de autenticação, espelhando o ExactActiveSources do gate Go
    # (internal/v2supersessionintegrity/integrity.go): um original arquivado em
    # consolidação DEC-020 e depois RESTAURADO byte a byte no próprio
    # source_shard (tools/restore-v2-supersession-originals) é o dono legítimo
    # da linha ativa. Nada aqui adiciona issue: registro que não casa apenas
    # não autentica e o classificador segue fail-closed para aquele lote.
    restored_claims = {}
    restored_conflicts = set()
    for archive_rel in sorted(trusted_archives):
        archive_records = _trusted_supersession_archive_records(
            root, archive_rel, trusted_archives, archive_cache)
        if archive_records is None:
            continue
        for archive_record in archive_records:
            claim = _restored_original_claim(
                archive_record, pages_dir, file_set,
                occurrences_by_intent, active_by_file_intent,
                active_raw_by_file_intent)
            if claim is None:
                continue
            key, record_sha = claim
            if key in valid_claims:
                # Estruturalmente impossível (tombstone exige a ocorrência do
                # próprio tombstone além da ativa; restaurado exige ocorrência
                # única), mas em conflito a projeção não escolhe lado.
                restored_conflicts.add(key)
                continue
            previous = restored_claims.get(key)
            if previous is not None and previous != record_sha:
                restored_conflicts.add(key)
                continue
            restored_claims[key] = record_sha
    for key in restored_conflicts:
        restored_claims.pop(key, None)

    winners = set()
    for key, claims in valid_claims.items():
        if len(claims) == 1:
            winners.add(key)
        else:
            target, iid = key
            issues.append(
                f'{target}:{iid}:valid_tombstone_not_unique:{len(claims)}')
    winners |= set(restored_claims)

    files_after = sorted(
        path for path in glob.glob(os.path.join(pages_dir, '*.jsonl'))
        if is_finalized_v2_path(path)
    )
    if files_after != files:
        raise queue_producer.CASMismatch(
            'conjunto de shards DEC-020 mudou durante validação')
    for fname, snapshot in snapshots.items():
        if queue_producer.snapshot_sha256(
                fname, max_bytes=64 * 1024 * 1024) != snapshot.digest:
            raise queue_producer.CASMismatch(
                f'shard DEC-020 mudou durante validação: {fname}')
    for archive_path, cached_archive in archive_cache.items():
        if cached_archive is None:
            continue
        _, digest = cached_archive
        if queue_producer.snapshot_sha256(
                archive_path, max_bytes=64 * 1024 * 1024) != digest:
            raise queue_producer.CASMismatch(
                f'archive DEC-020 mudou durante validação: {archive_path}')
    return winners, sorted(set(issues))


def _global_batch_endpoint_error(endpoint):
    if not isinstance(endpoint, dict) or set(endpoint) != {
            'shard', 'intent_id'}:
        return 'endpoint_shape'
    if not _canonical_report_shard(endpoint.get('shard')):
        return 'endpoint_shard'
    if not _canonical_report_intent(endpoint.get('intent_id')):
        return 'endpoint_intent'
    return None


def _global_batch_issue_schema_valid(event):
    """Close code/endpoint/field combinations before projection."""
    code = event.get('code')
    common = {
        'type', 'code', 'left', 'publication_allowed', 'index_policy'}
    if not common.issubset(event):
        return False
    exact = {
        'intent_id_dup_global': ('intent_id', 'intent'),
        'title_dup_global': ('title', 'title'),
        'meta_dup_global': ('meta_description', 'meta'),
        'h1_dup_global': ('h1', 'h1'),
    }
    if code in exact:
        field, reason = exact[code]
        return (set(event) == common | {
                    'right', 'field', 'candidate_reasons'} and
                event.get('field') == field and
                event.get('candidate_reasons') == [reason])
    if code == 'heading_reuso_global':
        return (set(event) == common | {
                    'field', 'detail', 'heading_reuse'} and
                event.get('field') == 'heading' and
                isinstance(event.get('detail'), str) and
                bool(event['detail']) and
                _bounded_nonnegative_integer(event.get('heading_reuse')) and
                event['heading_reuse'] > 0)
    if code in {
            'distinctness_candidate_bucket_overflow',
            'distinctness_candidate_budget_exceeded',
            'distinctness_local_pair_budget_exceeded'}:
        return (set(event) == common | {'detail'} and
                isinstance(event.get('detail'), str) and bool(event['detail']))
    if code == 'distinctness_exact_adjudication_budget_exceeded':
        return (set(event) == common | {
                    'right', 'detail', 'candidate_reasons'} and
                isinstance(event.get('detail'), str) and bool(event['detail']))
    if code in {
            'body_jaccard_near_duplicate', 'editorial_span_duplicate',
            'editorial_repeat_density'}:
        allowed_metrics = {
            'body_jaccard', 'max_identical_span_tokens',
            'target_repeated_density', 'peer_repeated_density'}
        required = common | {'right', 'field', 'candidate_reasons'}
        return (required.issubset(event) and
                set(event).issubset(required | allowed_metrics) and
                event.get('field') == 'body')
    return False


def parse_global_distinctness_batch(payload):
    """Validate the complete authenticated JSONL stream or reject it."""
    if (not isinstance(payload, bytes) or not payload or
            len(payload) > FACTORY_GLOBAL_BATCH_STDOUT_MAX_BYTES or
            not payload.endswith(b'\n')):
        return None, 'global_batch_payload_size_or_newline'
    raw_lines = payload.splitlines(keepends=True)
    if len(raw_lines) < 3:
        return None, 'global_batch_too_few_events'
    events = []
    digest = hashlib.sha256()
    for index, raw_line in enumerate(raw_lines):
        if (len(raw_line) > FACTORY_GLOBAL_BATCH_LINE_MAX_BYTES or
                not raw_line.endswith(b'\n') or raw_line == b'\n' or
                b'\r' in raw_line):
            return None, f'global_batch_line_invalid:{index + 1}'
        try:
            event = json.loads(
                raw_line.decode('utf-8'),
                object_pairs_hook=_json_object_without_duplicate_keys)
        except (UnicodeDecodeError, ValueError, json.JSONDecodeError) as exc:
            return None, f'global_batch_json:{index + 1}:{type(exc).__name__}'
        if not isinstance(event, dict):
            return None, f'global_batch_event_not_object:{index + 1}'
        if (event.get('publication_allowed') is not False or
                event.get('index_policy') != 'noindex'):
            return None, f'global_batch_public_flags:{index + 1}'
        if event.get('type') != 'footer':
            digest.update(raw_line)
        events.append(event)
    if events[0].get('type') != 'header' or events[-1].get('type') != 'footer':
        return None, 'global_batch_header_or_footer_missing'
    if any(event.get('type') == 'footer' for event in events[:-1]):
        return None, 'global_batch_early_footer'

    header = events[0]
    header_fields = {
        'type', 'schema_version', 'mode', 'algorithm_fingerprint',
        'batch_fingerprint', 'generation_root', 'stock_root',
        'stock_shards', 'stock_pages', 'visible_surfaces',
        'publication_allowed', 'index_policy'}
    if set(header) != header_fields:
        return None, 'global_batch_header_shape'
    if (header.get('schema_version') != GLOBAL_BATCH_SCHEMA_VERSION or
            header.get('mode') != 'global-distinctness-v3-read-only' or
            header.get('algorithm_fingerprint') !=
            INCREMENTAL_ALGORITHM_FINGERPRINT or
            header.get('batch_fingerprint') !=
            GLOBAL_BATCH_ALGORITHM_FINGERPRINT or
            not isinstance(header.get('generation_root'), str) or
            re.fullmatch(r'[0-9a-f]{64}', header['generation_root']) is None or
            not isinstance(header.get('stock_root'), str) or
            re.fullmatch(r'[0-9a-f]{64}', header['stock_root']) is None or
            not _bounded_nonnegative_integer(header.get('stock_shards')) or
            not _bounded_nonnegative_integer(header.get('stock_pages')) or
            header.get('visible_surfaces') !=
            list(INCREMENTAL_VISIBLE_SURFACES)):
        return None, 'global_batch_header_contract'

    shards = {}
    issues = []
    local = collections.defaultdict(list)
    seen_issues = set()
    seen_local_pairs = set()
    last_shard = ''
    event_phase = 'shard'
    issue_allowed = {
        'type', 'code', 'left', 'right', 'field', 'detail',
        'body_jaccard', 'max_identical_span_tokens',
        'target_repeated_density', 'peer_repeated_density',
        'heading_reuse', 'candidate_reasons',
        'publication_allowed', 'index_policy'}
    for index, event in enumerate(events[1:-1], 2):
        kind = event.get('type')
        if kind == 'shard':
            if event_phase != 'shard' or set(event) != {
                    'type', 'shard', 'digest', 'active_pages',
                    'publication_allowed', 'index_policy'}:
                return None, f'global_batch_shard_shape_or_order:{index}'
            shard = event.get('shard')
            if (not _canonical_report_shard(shard) or shard in shards or
                    shard <= last_shard or
                    not isinstance(event.get('digest'), str) or
                    re.fullmatch(r'[0-9a-f]{64}', event['digest']) is None or
                    not _bounded_nonnegative_integer(
                        event.get('active_pages'))):
                return None, f'global_batch_shard_contract:{index}'
            shards[shard] = event
            last_shard = shard
            continue
        event_phase = 'result'
        if kind == 'issue':
            if not set(event).issubset(issue_allowed):
                return None, f'global_batch_issue_shape:{index}'
            code = event.get('code')
            left_error = _global_batch_endpoint_error(event.get('left'))
            right = event.get('right')
            right_error = (None if right is None else
                           _global_batch_endpoint_error(right))
            issue_contract_error = None
            if code not in GLOBAL_BATCH_ALLOWED_ISSUE_CODES:
                issue_contract_error = 'code'
            elif code == 'ngram_dup_global':
                issue_contract_error = 'legacy_code'
            elif left_error:
                issue_contract_error = 'left_' + left_error
            elif right_error:
                issue_contract_error = 'right_' + right_error
            elif not _global_batch_issue_schema_valid(event):
                schema_code = (code if isinstance(code, str) else 'nonstring')
                schema_field = event.get('field', 'absent')
                if not isinstance(schema_field, str):
                    schema_field = 'nonstring'
                schema_keys = ','.join(sorted(event))
                schema_reasons = event.get('candidate_reasons', 'absent')
                if isinstance(schema_reasons, list) and all(
                        isinstance(item, str) for item in schema_reasons):
                    schema_reasons = ','.join(schema_reasons) or 'empty'
                elif schema_reasons != 'absent':
                    schema_reasons = 'noncanonical'
                issue_contract_error = (
                    f'schema:{schema_code}:{schema_field}:'
                    f'{schema_reasons}:{schema_keys}')
            elif code in GLOBAL_BATCH_PAIR_ISSUE_CODES and right is None:
                issue_contract_error = 'pair_without_right'
            elif event['left']['shard'] not in shards:
                issue_contract_error = 'left_shard_not_in_inventory'
            elif right is not None and event['left'] == right:
                issue_contract_error = 'identical_endpoints'
            elif right is not None and right['shard'] not in shards:
                issue_contract_error = 'right_shard_not_in_inventory'
            if issue_contract_error is not None:
                return (None,
                        f'global_batch_issue_contract:{index}:'
                        f'{issue_contract_error}')
            if ((code in GLOBAL_BATCH_PAIR_ISSUE_CODES and
                 not _valid_global_candidate_reasons(
                     event.get('candidate_reasons'))) or
                    ('candidate_reasons' in event and
                     not _valid_global_candidate_reasons(
                         event['candidate_reasons']))):
                return None, f'global_batch_issue_reasons:{index}'
            for key in ('body_jaccard', 'target_repeated_density',
                        'peer_repeated_density'):
                if key in event and not _bounded_unit_number(event[key]):
                    return None, f'global_batch_issue_metric:{index}:{key}'
            for key in ('max_identical_span_tokens', 'heading_reuse'):
                if key in event and not _bounded_nonnegative_integer(
                        event[key]):
                    return None, f'global_batch_issue_metric:{index}:{key}'
            if (code == 'body_jaccard_near_duplicate' and
                    event.get('body_jaccard', 0) <
                    INCREMENTAL_BODY_JACCARD_THRESHOLD):
                return None, f'global_batch_issue_below_threshold:{index}'
            if (code == 'editorial_span_duplicate' and
                    event.get('max_identical_span_tokens', 0) <
                    INCREMENTAL_IDENTICAL_SPAN_THRESHOLD):
                return None, f'global_batch_issue_below_threshold:{index}'
            if (code == 'editorial_repeat_density' and
                    max(event.get('target_repeated_density', 0),
                        event.get('peer_repeated_density', 0)) <
                    INCREMENTAL_REPEAT_DENSITY_THRESHOLD):
                return None, f'global_batch_issue_below_threshold:{index}'
            issue_identity = json.dumps(
                event, ensure_ascii=False, sort_keys=True,
                separators=(',', ':'))
            if issue_identity in seen_issues:
                return None, f'global_batch_issue_duplicate:{index}'
            seen_issues.add(issue_identity)
            issues.append(event)
            continue
        if kind == 'local_adjudication':
            if set(event) != {
                    'type', 'shard', 'left_intent_id', 'right_intent_id',
                    'max_identical_span_tokens', 'candidate_reasons',
                    'publication_allowed', 'index_policy'}:
                return None, f'global_batch_local_shape:{index}'
            shard = event.get('shard')
            left, right = (event.get('left_intent_id'),
                           event.get('right_intent_id'))
            if (not _canonical_report_shard(shard) or
                    shard not in shards or
                    not _canonical_report_intent(left) or
                    not _canonical_report_intent(right) or left >= right or
                    not _bounded_nonnegative_integer(
                        event.get('max_identical_span_tokens')) or
                    event['max_identical_span_tokens'] < 12 or
                    not _valid_global_candidate_reasons(
                        event.get('candidate_reasons'))):
                return None, f'global_batch_local_contract:{index}'
            local_identity = (shard, left, right)
            if local_identity in seen_local_pairs:
                return None, f'global_batch_local_duplicate:{index}'
            seen_local_pairs.add(local_identity)
            local[shard].append(event)
            continue
        return None, f'global_batch_unknown_event:{index}:{kind}'

    footer = events[-1]
    footer_fields = {
        'type', 'inventory_complete', 'inventory_stable',
        'candidate_routing_complete', 'local_routing_complete',
        'shards_emitted', 'pages_emitted', 'terms_scanned',
        'postings_scanned', 'candidate_pairs_routed',
        'candidate_pairs_compared', 'issues_emitted',
        'local_adjudications_emitted', 'passed', 'payload_sha256',
        'receipt_sha256',
        'publication_allowed', 'index_policy'}
    if set(footer) != footer_fields:
        return None, 'global_batch_footer_shape'
    counters = (
        'shards_emitted', 'pages_emitted', 'terms_scanned',
        'postings_scanned', 'candidate_pairs_routed',
        'candidate_pairs_compared', 'issues_emitted',
        'local_adjudications_emitted')
    candidate_routing_expected = not any(
        issue['code'] in {
            'distinctness_candidate_bucket_overflow',
            'distinctness_candidate_budget_exceeded'}
        for issue in issues)
    local_routing_expected = not any(
        issue['code'] == 'distinctness_local_pair_budget_exceeded'
        for issue in issues)
    receipt_fields = dict(footer)
    receipt_sha256 = receipt_fields.pop('receipt_sha256', None)
    receipt_payload = json.dumps(
        receipt_fields, ensure_ascii=False, sort_keys=True,
        separators=(',', ':')).encode('utf-8')
    if (footer.get('inventory_complete') is not True or
            footer.get('inventory_stable') is not True or
            type(footer.get('candidate_routing_complete')) is not bool or
            type(footer.get('local_routing_complete')) is not bool or
            footer.get('candidate_routing_complete') !=
            candidate_routing_expected or
            footer.get('local_routing_complete') !=
            local_routing_expected or
            type(footer.get('passed')) is not bool or
            any(not _bounded_nonnegative_integer(
                    footer.get(key), INCREMENTAL_COUNTER_MAX)
                for key in counters) or
            footer.get('payload_sha256') != digest.hexdigest() or
            not isinstance(receipt_sha256, str) or
            receipt_sha256 != hashlib.sha256(receipt_payload).hexdigest() or
            header['stock_shards'] == 0 or header['stock_pages'] == 0 or
            header['stock_shards'] != len(shards) or
            header['stock_pages'] != sum(
                event['active_pages'] for event in shards.values()) or
            footer['shards_emitted'] != len(shards) or
            footer['pages_emitted'] != header['stock_pages'] or
            footer['issues_emitted'] != len(issues) or
            footer['local_adjudications_emitted'] !=
            sum(len(values) for values in local.values()) or
            footer['candidate_pairs_compared'] >
            footer['candidate_pairs_routed'] or
            footer['local_adjudications_emitted'] >
            footer['candidate_pairs_compared'] or
            footer['terms_scanned'] > footer['postings_scanned'] or
            footer['postings_scanned'] < 4 * header['stock_pages'] or
            len({
                (issue['left']['shard'], issue['left']['intent_id'],
                 issue['right']['shard'], issue['right']['intent_id'])
                for issue in issues
                if issue['code'] in {
                    'body_jaccard_near_duplicate',
                    'editorial_span_duplicate',
                    'editorial_repeat_density',
                    'distinctness_exact_adjudication_budget_exceeded'}
            }) > footer['candidate_pairs_compared'] or
            footer['passed'] != (
                len(issues) == 0 and
                footer['candidate_routing_complete'] and
                footer['local_routing_complete'])):
        return None, 'global_batch_footer_contract'
    return {
        'header': header, 'shards': shards, 'issues': issues,
        'local_adjudications': dict(local), 'footer': footer,
    }, None


def query_global_distinctness_batch():
    binary_error = cached_factory_binary_error()
    if binary_error:
        return None, binary_error
    command = [
        FACTORY_BINARY, 'audit-distinctness', '--root', ROOT,
        '--scope', 'all', '--format', 'jsonl']
    if FACTORY_DISTINCTNESS_STORE:
        command.extend(['--distinctness-store',
                        FACTORY_DISTINCTNESS_STORE])
    environment = minimal_factory_subprocess_environment()
    # 2026-08-04: o ambiente mínimo aponta ``TMPDIR`` para ``/nonexistent``
    # (defesa contra injeção via ambiente herdado — ver
    # ``minimal_factory_subprocess_environment``). Isso serve às consultas
    # focais, que não gravam nada, mas o lote GLOBAL particiona em disco:
    # ``internal/v2pagedistinctness/global_partition_scratch.go:182`` chama
    # ``os.MkdirTemp("", "factory-distinctness-global-v4-")``, e o diretório
    # vazio resolve por ``os.TempDir()``, que honra ``$TMPDIR``. Resultado
    # medido: ``mkdir /nonexistent/factory-distinctness-global-v4-...:
    # permission denied`` — o lote global era ESTRUTURALMENTE incapaz de rodar
    # por este caminho. O defeito ficou coberto por duas falhas anteriores
    # (binário stale, índice stale) que abortavam antes da partição.
    # A correção não reabre a superfície de injeção: em vez de herdar
    # ``TMPDIR`` do processo pai, criamos um diretório PRÓPRIO, privado
    # (``mkdtemp`` nasce 0o700) e descartável, e o removemos ao fim. O rascunho
    # é transitório de verdade — o produto continua saindo em stdout.
    try:
        scratch_directory = tempfile.mkdtemp(
            prefix='audit-v2-global-batch-scratch-')
    except OSError as exc:
        return None, f'global_batch_scratch_unavailable:{type(exc).__name__}'
    environment['TMPDIR'] = scratch_directory
    try:
        try:
            process = subprocess.Popen(
                command, cwd=ROOT, env=environment, stdin=subprocess.DEVNULL,
                stdout=subprocess.PIPE, stderr=subprocess.PIPE, bufsize=0,
                start_new_session=True)
            stdout, stderr, read_status = _read_process_output_bounded(
                process, FACTORY_GLOBAL_BATCH_TIMEOUT_SECONDS,
                FACTORY_GLOBAL_BATCH_STDOUT_MAX_BYTES,
                FACTORY_QUERY_STDERR_MAX_BYTES)
        except OSError as exc:
            return None, f'global_batch_unavailable:{type(exc).__name__}'
        if read_status:
            return None, f'global_batch_read_failed:{read_status}'
        if process.returncode != 0:
            detail = ' '.join(
                stderr.decode('utf-8', errors='replace').strip().split())
            return None, f'global_batch_process_failed:{detail[:500]}'
        return parse_global_distinctness_batch(stdout)
    finally:
        shutil.rmtree(scratch_directory, ignore_errors=True)


def _remove_adjudicated_local_ngrams(result, adjudications):
    adjudicated = {
        (item['left_intent_id'], item['right_intent_id'])
        for item in adjudications}
    values = result.get('defects', {}).get('ngram_dup') or []
    retained = []
    for value in values:
        left, separator, right = str(value).partition('~')
        pair = tuple(sorted((left, right))) if separator else None
        if pair not in adjudicated:
            retained.append(value)
    if retained:
        result['defects']['ngram_dup'] = retained
    else:
        result.get('defects', {}).pop('ngram_dup', None)
    evidence = result.get('evidence') or {}
    retained_evidence = []
    for item in evidence.get('ngram_dup') or []:
        left, separator, right = str(item.get('target') or '').partition('~')
        pair = tuple(sorted((left, right))) if separator else None
        if pair not in adjudicated:
            retained_evidence.append(item)
    if retained_evidence:
        evidence['ngram_dup'] = retained_evidence
    else:
        evidence.pop('ngram_dup', None)
    if not evidence:
        result.pop('evidence', None)


def _canonical_local_pair(value):
    left, separator, right = str(value).partition('~')
    if (not separator or not _canonical_report_intent(left) or
            not _canonical_report_intent(right) or left == right):
        return None
    return tuple(sorted((left, right)))


def _audited_local_ngram_pairs(result):
    defect_pairs = {
        pair for pair in (
            _canonical_local_pair(value)
            for value in result.get('defects', {}).get('ngram_dup') or [])
        if pair is not None}
    evidence_pairs = {
        pair for pair in (
            _canonical_local_pair(item.get('target'))
            for item in result.get('evidence', {}).get('ngram_dup') or []
            if isinstance(item, dict))
        if pair is not None}
    return defect_pairs.intersection(evidence_pairs)


def _apply_global_distinctness_batch(
        per_file, snapshot_contracts, batch, error):
    if error is None:
        header, footer = batch['header'], batch['footer']
        if (not footer['candidate_routing_complete'] or
                not footer['local_routing_complete']):
            error = 'global_batch_routing_incomplete'
        elif (header['stock_shards'] != len(snapshot_contracts) or
                header['stock_pages'] != sum(
                    item['active_pages']
                    for item in snapshot_contracts.values()) or
                footer['shards_emitted'] != len(snapshot_contracts) or
                footer['pages_emitted'] != header['stock_pages'] or
                set(batch['shards']) != set(snapshot_contracts)):
            error = 'global_batch_inventory_contract'
        else:
            for shard, expected in snapshot_contracts.items():
                actual = batch['shards'][shard]
                if (actual['digest'] != expected['digest'] or
                        actual['active_pages'] != expected['active_pages']):
                    error = f'global_batch_shard_snapshot_mismatch:{shard}'
                    break
                active_intents = expected.get('active_intents')
                if (not isinstance(active_intents, (set, frozenset)) or
                        len(active_intents) != expected['active_pages'] or
                        any(not _canonical_report_intent(intent)
                            for intent in active_intents)):
                    error = f'global_batch_active_intents_invalid:{shard}'
                    break
    if error is None:
        span_pairs = {
            tuple(sorted((
                (issue['left']['shard'], issue['left']['intent_id']),
                (issue['right']['shard'], issue['right']['intent_id']))))
            for issue in batch['issues']
            if (issue['code'] == 'editorial_span_duplicate' and
                issue.get('right') is not None)
        }
        for shard, adjudications in batch['local_adjudications'].items():
            expected_intents = snapshot_contracts[shard]['active_intents']
            audited_pairs = _audited_local_ngram_pairs(per_file[shard])
            for item in adjudications:
                local_pair = (
                    item['left_intent_id'], item['right_intent_id'])
                endpoint_pair = tuple(sorted((
                    (shard, item['left_intent_id']),
                    (shard, item['right_intent_id']))))
                if (item['left_intent_id'] not in expected_intents or
                        item['right_intent_id'] not in expected_intents):
                    error = f'global_batch_local_intent_unknown:{shard}'
                    break
                if local_pair not in audited_pairs:
                    error = f'global_batch_local_candidate_unproven:{shard}'
                    break
                if (item['max_identical_span_tokens'] >=
                        INCREMENTAL_IDENTICAL_SPAN_THRESHOLD and
                        endpoint_pair not in span_pairs):
                    error = f'global_batch_local_span_issue_missing:{shard}'
                    break
            if error is not None:
                break
    if error is None:
        for issue in batch['issues']:
            endpoints = [issue['left']]
            if issue.get('right') is not None:
                endpoints.append(issue['right'])
            unknown = next((
                endpoint for endpoint in endpoints
                if endpoint['intent_id'] not in
                snapshot_contracts[endpoint['shard']]['active_intents']), None)
            if unknown is not None:
                error = ('global_batch_issue_intent_unknown:' +
                         unknown['shard'] + ':' + unknown['intent_id'])
                break
    if error is not None:
        for result in per_file.values():
            result.setdefault('defects', {}).setdefault(
                'distinctness_index_unavailable', []).append(error)
            result['distinctness_index'] = {
                'status': 'global_batch_unavailable_fail_closed',
                'reason': error, 'publication_allowed': False,
                'index_policy': 'noindex'}
        return

    for shard, result in per_file.items():
        adjudications = batch['local_adjudications'].get(shard, [])
        _remove_adjudicated_local_ngrams(result, adjudications)
        result['distinctness_index'] = {
            'status': 'ready',
            'mode': batch['header']['mode'],
            'schema_version': batch['header']['schema_version'],
            'algorithm_fingerprint':
                batch['header']['algorithm_fingerprint'],
            'batch_fingerprint': batch['header']['batch_fingerprint'],
            'generation_root': batch['header']['generation_root'],
            'stock_root': batch['header']['stock_root'],
            'target_digest': batch['shards'][shard]['digest'],
            'target_snapshot_bound': True,
            'inventory_complete': batch['footer']['inventory_complete'],
            'inventory_stable': batch['footer']['inventory_stable'],
            'stock_shards': batch['header']['stock_shards'],
            'stock_pages': batch['header']['stock_pages'],
            'visible_surface_scope_complete': True,
            'visible_surfaces': batch['header']['visible_surfaces'],
            'candidate_routing_complete':
                batch['footer']['candidate_routing_complete'],
            'local_routing_complete':
                batch['footer']['local_routing_complete'],
            'local_ngram_adjudications': adjudications,
            'publication_allowed': False, 'index_policy': 'noindex'}
    for issue in batch['issues']:
        left, right = issue['left'], issue.get('right')
        projections = [(left, right)]
        if right is not None:
            projections.append((right, left))
        for target, peer in projections:
            result = per_file[target['shard']]
            if peer is None:
                detail = str(issue.get('detail') or '')
                value = (f"{target['intent_id']}:{detail}" if detail else
                         target['intent_id'])
            else:
                value = f"{target['intent_id']}~{peer['intent_id']}"
            result.setdefault('defects', {}).setdefault(
                issue['code'], []).append(value)
            result.setdefault('evidence', {}).setdefault(
                'distinctness', []).append({
                    **issue,
                    'projection_target': dict(target),
                    'projection_peer': (
                        dict(peer) if peer is not None else None),
                })


def apply_validated_global_distinctness_batch(
        per_file, snapshot_contracts, batch):
    """Project a caller-supplied, already parsed complete factory batch.

    This is the commit-closure entrypoint: it never consults the cached
    factory binary or its mutable store. Structural authentication remains in
    ``parse_global_distinctness_batch`` and snapshot binding remains in the
    projection core above.
    """
    if not isinstance(batch, dict):
        raise ValueError('validated global distinctness batch is not an object')
    return _apply_global_distinctness_batch(
        per_file, snapshot_contracts, batch, None)


def apply_global_distinctness_batch(per_file, snapshot_contracts):
    batch, error = query_global_distinctness_batch()
    return _apply_global_distinctness_batch(
        per_file, snapshot_contracts, batch, error)


# Cada worker do process pool recebe o portfólio uma única vez via
# ``initializer``/``initargs`` (não é repassado por tarefa), garantindo que a
# auditoria per-shard use exatamente o mesmo portfólio que o processo pai — o
# veredito por shard fica idêntico ao modo serial.
_WORKER_PORTFOLIO = None


def _init_shard_worker(portfolio):
    global _WORKER_PORTFOLIO
    _WORKER_PORTFOLIO = portfolio


def _reduce_shard_for_cross_shard(res):
    """Collapse per-shard page bodies to only the cross-shard metadata.

    ``_audit_global`` reads, per shard, exactly two projections of the loaded
    pages: the stripped ``intent_id`` and line of every active (non-skipped)
    page, and the FULL page dict of every superseded tombstone (``skipped`` com
    ``superseded_by is not None``). It never touches the text bodies of active
    pages. Retaining every ``_loaded_pages`` list of every shard simultaneously
    (the pre-reduction shape) makes the parent's peak memory O(total corpus) and
    OOMs at 10M pages; the corpus is also serialized across IPC per shard.

    Replacing the active bodies with ``(intent, line)`` tuples keeps the O(active
    pages) metadata the cross-shard intent-uniqueness genuinely needs, while
    dropping the ~1000x-heavier prose. The superseded tombstones are kept whole
    (their count is editorially bounded, not O(N)) so ``supersession_archive_issue``
    stays byte-identical. The derived quantities computed by ``_audit_global``
    (active_intents frozenset, supersession order, per-intent counters,
    total_pages) are byte-identical to iterating the original ``_loaded_pages``.

    Defensive by design: shards produced without ``collect_pages`` (test doubles
    or the incremental path) lack the loaded keys and are returned untouched.
    """
    loaded_pages = res.pop('_loaded_pages', None)
    loaded_page_lines = res.pop('_loaded_page_lines', None)
    if loaded_pages is None or loaded_page_lines is None:
        return res
    active_entries = []
    superseded_entries = []
    for page, line_number in zip(loaded_pages, loaded_page_lines):
        if page.get('skipped'):
            if page.get('superseded_by') is not None:
                superseded_entries.append((line_number, page))
            continue
        active_entries.append(
            ((page.get('intent_id') or '').strip(), line_number))
    res['_active_entries'] = active_entries
    res['_superseded_entries'] = superseded_entries
    return res


def _audit_one_shard(path):
    """Audita um shard isolado (per-file) num worker do pool.

    Roda dentro de ``ProcessPoolExecutor``; retorna ``(path, res)`` para que o
    processo pai reagregue na ordem canônica de ``files``. ``_page_gram_sets`` é
    descartado aqui porque ``_audit_global`` já o descarta na agregação — evitar
    serializá-lo entre processos elimina o maior payload de IPC sem alterar
    veredito algum.
    """
    res = audit_file(path, _WORKER_PORTFOLIO, collect_pages=True)
    res.pop('_page_gram_sets', None)
    _reduce_shard_for_cross_shard(res)
    return path, res


def _shard_sidecar_path():
    """Caminho do índice incremental (dinâmico: respeita ``ROOT`` sob teste)."""
    return os.path.join(
        ROOT, '.cache', 'audit-v2-pages', 'per-shard-index.json')


def _shard_sidecar_source_fingerprint():
    """SHA-256 do próprio auditor + dos módulos de fatos legais datados.

    Qualquer mudança na lógica de auditoria ou nos fatos datados troca o
    fingerprint e invalida o índice inteiro — um veredito nunca é servido por
    uma versão de algoritmo/fato diferente da que o produziria agora.
    """
    global _SHARD_SIDECAR_SOURCE_FINGERPRINT
    if _SHARD_SIDECAR_SOURCE_FINGERPRINT is None:
        module_dir = os.path.dirname(os.path.abspath(__file__))
        sources = [os.path.abspath(__file__)]
        sources.extend(sorted(glob.glob(
            os.path.join(module_dir, '*current_legal_facts.py'))))
        digest = hashlib.sha256()
        for source in sources:
            try:
                with open(source, 'rb') as handle:
                    payload = handle.read()
            except OSError:
                # Fonte ilegível: nunca reaproveitar veredito de origem
                # desconhecida. Fingerprint volátil força re-auditoria completa.
                return os.urandom(32).hex()
            digest.update(hashlib.sha256(payload).digest())
            digest.update(len(payload).to_bytes(8, 'big'))
        _SHARD_SIDECAR_SOURCE_FINGERPRINT = digest.hexdigest()
    return _SHARD_SIDECAR_SOURCE_FINGERPRINT


def _shard_sidecar_portfolio_fingerprint(portfolio):
    canonical = json.dumps(
        portfolio, ensure_ascii=False, sort_keys=True, separators=(',', ':'))
    return hashlib.sha256(canonical.encode('utf-8')).hexdigest()


def _shard_sidecar_header(portfolio):
    return {
        'schema_version': SHARD_SIDECAR_SCHEMA_VERSION,
        'source_fingerprint': _shard_sidecar_source_fingerprint(),
        'portfolio_fingerprint': _shard_sidecar_portfolio_fingerprint(
            portfolio),
        'incremental_algorithm_fingerprint': INCREMENTAL_ALGORITHM_FINGERPRINT,
        'global_batch_algorithm_fingerprint': (
            GLOBAL_BATCH_ALGORITHM_FINGERPRINT),
        'utc_date': datetime.datetime.now(
            datetime.timezone.utc).date().isoformat(),
    }


def _shard_cache_identity(path):
    """Assinatura barata do snapshot de disco, sem ler nem hashear o conteúdo.

    Espelha exatamente a identidade que ``read_target_snapshot`` usa para
    detectar reescrita em curso (dev/ino/tamanho/mtime_ns/ctime_ns). Um shard
    reescrito, mesmo com o mesmo tamanho, muda ``mtime_ns``/``ctime_ns`` e é
    reauditado. Devolve ``None`` (nunca cacheável) para não-arquivo/erro.
    """
    try:
        info = os.stat(path, follow_symlinks=False)
    except OSError:
        return None
    if not stat.S_ISREG(info.st_mode):
        return None
    return [info.st_dev, info.st_ino, info.st_size,
            info.st_mtime_ns, info.st_ctime_ns]


def _load_shard_sidecar(header):
    """Lê o índice; ``{}`` em qualquer corrupção/ausência/cabeçalho divergente.

    Fail-safe por design: um índice ilegível, truncado ou de outra época de
    auditoria vira miss total (re-auditoria completa), nunca um veredito velho.
    """
    try:
        with open(_shard_sidecar_path(), 'rb') as handle:
            payload = handle.read()
    except OSError:
        return {}
    try:
        document = json.loads(payload)
    except (ValueError, UnicodeDecodeError):
        return {}
    if (not isinstance(document, dict) or
            document.get('header') != header or
            not isinstance(document.get('shards'), dict)):
        return {}
    shards = {}
    for path, entry in document['shards'].items():
        identity = entry.get('identity') if isinstance(entry, dict) else None
        if (isinstance(identity, list) and len(identity) == 5 and
                all(type(value) is int for value in identity) and
                isinstance(entry.get('res'), dict)):
            shards[path] = entry
    return shards


def _store_shard_sidecar(header, files, results, identities):
    """Persiste atomicamente o índice canônico do conjunto atual de shards.

    Escrita best-effort: só grava quando há ao menos um shard cacheável (com
    identidade de disco real). Falha de I/O nunca quebra a auditoria — o índice
    é otimização, não fonte de verdade.
    """
    persistable = {}
    for path in files:
        identity = identities.get(path)
        res = results.get(path)
        if identity is None or not isinstance(res, dict):
            continue
        persistable[path] = {'identity': identity, 'res': res}
    if not persistable:
        return
    try:
        serialized = json.dumps(
            {'header': header, 'shards': persistable},
            ensure_ascii=False, sort_keys=True).encode('utf-8')
    except (TypeError, ValueError):
        return
    path = _shard_sidecar_path()
    temporary = None
    try:
        os.makedirs(os.path.dirname(path), exist_ok=True)
        temporary = f'{path}.tmp.{os.getpid()}'
        with open(temporary, 'wb') as handle:
            handle.write(serialized)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temporary, path)
    except OSError:
        if temporary is not None:
            try:
                os.unlink(temporary)
            except OSError:
                pass


def _run_per_shard_audits(files, portfolio):
    """Fase per-shard com índice incremental persistente.

    Reaproveita o veredito reduzido de cada shard cujo snapshot de disco não
    mudou desde o índice, reauditando apenas o delta. Delta vazio faz
    short-circuit: zero leitura/hash/parse da prosa, zero re-auditoria e zero
    regravação — apenas ``stat`` de metadados por shard. A equivalência com a
    auditoria fria é garantida pelo cabeçalho (ver ``_shard_sidecar_header``).
    """
    header = _shard_sidecar_header(portfolio)
    cached_index = _load_shard_sidecar(header)
    identities = {}
    cached_results = {}
    stale_files = []
    for path in files:
        identity = _shard_cache_identity(path)
        identities[path] = identity
        entry = cached_index.get(path)
        if (identity is not None and entry is not None and
                entry.get('identity') == identity):
            cached_results[path] = entry['res']
        else:
            stale_files.append(path)
    if not stale_files:
        return cached_results
    fresh_results = _run_per_shard_audits_uncached(stale_files, portfolio)
    results = {}
    for path in files:
        results[path] = (
            cached_results[path] if path in cached_results
            else fresh_results[path])
    _store_shard_sidecar(header, files, results, identities)
    return results


def _run_per_shard_audits_uncached(files, portfolio):
    """Executa a fase per-shard (independente) e devolve ``{path: res}``.

    A fase per-file é embaraçosamente paralela — cada shard é auditado sem
    estado compartilhado. A fase cross-shard (supersessão entre arquivos,
    n-grama/dedup global via fábrica Go) roda depois, serial, no processo pai.

    Guardas: ``AUDIT_V2_SERIAL=1`` força o modo serial (debug/CI); qualquer
    falha do pool (ex.: objeto não-picklable, ``BrokenProcessPool``) cai para o
    modo serial reconstruindo o dicionário completo do zero — a auditoria nunca
    quebra por causa da orquestração.
    """
    def _run_serial():
        serial_results = {}
        for path in files:
            res = audit_file(path, portfolio, collect_pages=True)
            res.pop('_page_gram_sets', None)
            _reduce_shard_for_cross_shard(res)
            serial_results[path] = res
        return serial_results

    if os.environ.get('AUDIT_V2_SERIAL') == '1' or len(files) <= 1:
        return _run_serial()

    max_workers = max(1, min(6, (os.cpu_count() or 3) - 2))
    if max_workers <= 1:
        return _run_serial()

    try:
        results = {}
        with concurrent.futures.ProcessPoolExecutor(
                max_workers=max_workers,
                initializer=_init_shard_worker,
                initargs=(portfolio,)) as executor:
            for path, res in executor.map(_audit_one_shard, files):
                results[path] = res
        # Só aceita o resultado paralelo se cobriu todos os shards.
        if len(results) != len(files):
            raise RuntimeError(
                'per-shard pool returned '
                f'{len(results)} results for {len(files)} shards')
        return results
    except Exception as exc:  # noqa: BLE001 - fallback serial deliberado
        print(
            f'audit_v2_pages: per-shard pool indisponivel, fallback serial: '
            f'{type(exc).__name__}: {exc}',
            file=sys.stderr)
        return _run_serial()


def _audit_global(distinctness_batch):
    portfolio = load_portfolio()
    files = sorted(
        path for path in glob.glob(
            os.path.join(ROOT, 'data/editorial/v2_pages/*.jsonl'))
        if is_finalized_v2_path(path)
    )
    per_shard_results = _run_per_shard_audits(files, portfolio)
    per_file = {}
    snapshot_contracts = {}
    total_pages = 0
    supersessions = []
    active_by_file_intent = collections.Counter()
    active_line_by_file_intent = {}
    for f in files:
        res = per_shard_results[f]
        # ``_reduce_shard_for_cross_shard`` already dropped the corpus bodies of
        # active pages, keeping only (intent, line) tuples plus the whole
        # superseded tombstones — the sole projections consumed below. The
        # derived quantities stay byte-identical to iterating ``_loaded_pages``.
        active_entries = res.pop('_active_entries')
        superseded_entries = res.pop('_superseded_entries')
        res.pop('_page_gram_sets', None)
        snapshot_digest = res.pop('_snapshot_digest')
        per_file[res['file']] = res
        snapshot_contracts[res['file']] = {
            'digest': snapshot_digest,
            'active_pages': res.get('active_pages', 0),
            'active_intents': frozenset(
                intent for intent, _line in active_entries),
        }
        for line_number, p in superseded_entries:
            supersessions.append((res['file'], line_number, p))
        for intent, line_number in active_entries:
            total_pages += 1
            if intent:
                active_by_file_intent[(res['file'], intent)] += 1
                active_line_by_file_intent[(res['file'], intent)] = line_number
    max_heading = max(2, total_pages // 100)
    archive_cache = {}
    consumed_archive_claims = set()
    for fname, source_line, page in supersessions:
        iid = (page.get('intent_id') or '').strip() or '(sem-intent)'
        target = page.get('superseded_by')
        reason = (page.get('skip_reason') or '').strip()
        issue = ''
        if reason != 'duplicate_intent_consolidated':
            issue = 'reason'
        elif not isinstance(target, str) or not target.strip():
            issue = 'target_empty'
        elif (target != target.strip() or
              target != os.path.basename(target) or
              target in ('.', '..')):
            issue = 'target_not_canonical_shard_name'
        else:
            target_file = os.path.join(os.path.dirname(fname), target)
            if target_file == fname:
                issue = 'target_is_source'
            elif target_file not in per_file:
                issue = 'target_missing'
            elif active_by_file_intent[(target_file, iid)] != 1:
                issue = 'target_active_intent_not_unique'
            else:
                issue = supersession_archive_issue(
                    fname, page, target, source_line,
                    active_line_by_file_intent[(target_file, iid)], archive_cache,
                    consumed_archive_claims)
        if issue:
            per_file[fname]['defects'].setdefault(
                'supersession_invalid', []).append(f'{iid}:{issue}')
    if distinctness_batch is None:
        apply_global_distinctness_batch(per_file, snapshot_contracts)
    else:
        apply_validated_global_distinctness_batch(
            per_file, snapshot_contracts, distinctness_batch)
    for res in per_file.values():
        res['defects'] = {k: sorted(set(v)) for k, v in res['defects'].items() if v}
        if res.get('evidence'):
            normalized_evidence = {}
            for key, values in res['evidence'].items():
                if not values:
                    continue
                if key == 'ngram_dup':
                    normalized_evidence[key] = sorted(values, key=lambda item: (
                        item['target'], item['field'], item['peer_field'],
                        item['phrase']))
                else:
                    normalized_evidence[key] = sorted(
                        values, key=lambda item: json.dumps(
                            item, ensure_ascii=False, sort_keys=True))
            res['evidence'] = normalized_evidence
        blocking = {k: v for k, v in res['defects'].items() if k != 'skipped'}
        res['ok'] = not blocking
    return {'total_pages': total_pages, 'max_heading_reuse': max_heading,
            'files': per_file}


def audit_global_with_distinctness_batch(batch):
    """Audit the complete private stock using only an explicit factory batch."""
    if not isinstance(batch, dict):
        raise ValueError('private global distinctness batch is not an object')
    return _audit_global(batch)


def audit_global():
    """Operational worktree audit using the configured cached factory path."""
    return _audit_global(None)


def canonical_incremental_target_shard(path):
    absolute_root = os.path.abspath(ROOT)
    absolute_target = os.path.abspath(os.fspath(path))
    try:
        if os.path.commonpath((absolute_root, absolute_target)) != absolute_root:
            raise ValueError('target escapes repository root')
    except ValueError as exc:
        raise ValueError('target escapes repository root') from exc
    relative = os.path.relpath(absolute_target, absolute_root).replace(
        os.sep, '/')
    expected_directory = 'data/editorial/v2_pages'
    if (posixpath.dirname(relative) != expected_directory or
            not is_finalized_v2_path(relative) or
            posixpath.basename(relative) != os.path.basename(relative)):
        raise ValueError(
            f'target is not a canonical finalized v2 shard: {relative}')
    return relative


def cached_factory_dependency_roots():
    """Prefixos aceitos nos caminhos absolutos de ``deps.list``.

    2026-07-31 (defeito de AMBIENTE medido ao vivo, sandbox Cowork): o cache
    ``.cache/go-cmd-bin/factory`` guarda caminhos ABSOLUTOS
    (``go list -deps -f '{{.Dir}}'``) do root em que o build rodou, mais o
    próprio root em ``deps.build-root``. O MESMO repositório é visível por mais
    de um caminho (``/opt/wiki`` para as ferramentas de arquivo e
    ``/sessions/<sessao>/mnt/wiki`` para o shell). Quando o auditor roda pelo
    caminho B sobre um cache gravado pelo caminho A, NENHUMA linha de
    ``deps.list`` casava com ``ROOT``: ``project_dependency_seen`` ficava falso
    e todo shard reprovava com
    ``distinctness_index_unavailable:cached_factory_dependency_manifest_incomplete``
    — mesmo com binário íntegro e fontes em dia. A correção traduz
    ``build-root -> ROOT`` pelo caminho RELATIVO. O fail-closed NÃO afrouxa: o
    pacote traduzido é verificado de verdade no disco vivo (ausente/ilegível
    continua erro), a frescura por mtime continua valendo e um ``deps.list``
    sem ``cmd/factory`` continua reprovando como manifesto incompleto.
    """
    roots = [os.path.abspath(ROOT)]
    try:
        with open(FACTORY_DEPS_BUILD_ROOT, 'rb') as handle:
            payload = handle.read(FACTORY_DEPS_BUILD_ROOT_MAX_BYTES + 1)
    except OSError:
        return roots
    if not payload or len(payload) > FACTORY_DEPS_BUILD_ROOT_MAX_BYTES:
        return roots
    try:
        lines = payload.decode('utf-8').splitlines()
    except UnicodeDecodeError:
        return roots
    if not lines:
        return roots
    recorded = lines[0].strip()
    # Só um root absoluto, canônico e não-degenerado ("/") pode ser traduzido.
    if (not recorded or not os.path.isabs(recorded) or
            recorded != os.path.normpath(recorded) or
            recorded.rstrip(os.sep) == ''):
        return roots
    if recorded not in roots:
        roots.append(recorded)
    return roots


def cached_factory_binary_error():
    """Return why the cached factory cannot be trusted without rebuilding."""
    try:
        binary_stat = os.lstat(FACTORY_BINARY)
        deps_stat = os.lstat(FACTORY_DEPS_LIST)
    except OSError as exc:
        return f'cached_factory_missing:{type(exc).__name__}'
    if (not stat.S_ISREG(binary_stat.st_mode) or
            not os.access(FACTORY_BINARY, os.X_OK)):
        return 'cached_factory_not_executable_regular_file'
    if not stat.S_ISREG(deps_stat.st_mode):
        return 'cached_factory_dependency_manifest_not_regular'
    try:
        with open(FACTORY_DEPS_LIST, 'rb') as handle:
            dependencies_payload = handle.read(1024 * 1024 + 1)
    except OSError as exc:
        return f'cached_factory_dependency_manifest_unreadable:{type(exc).__name__}'
    if (not dependencies_payload or
            len(dependencies_payload) > 1024 * 1024):
        return 'cached_factory_dependency_manifest_invalid_size'
    try:
        dependency_lines = dependencies_payload.decode('utf-8').splitlines()
    except UnicodeDecodeError:
        return 'cached_factory_dependency_manifest_invalid_utf8'
    binary_mtime_ns = binary_stat.st_mtime_ns
    for required in (os.path.join(ROOT, 'go.mod'),
                     os.path.join(ROOT, 'go.sum')):
        try:
            if os.stat(required, follow_symlinks=False).st_mtime_ns > binary_mtime_ns:
                return 'cached_factory_stale:module_metadata'
        except OSError as exc:
            return f'cached_factory_freshness_unavailable:{type(exc).__name__}'
    project_dependency_seen = False
    command_dependency_seen = False
    source_suffixes = ('.go', '.s', '.S', '.c', '.cc', '.cpp', '.h', '.hh')
    live_root = os.path.abspath(ROOT)
    # 2026-07-31: o prefixo aceito deixa de ser só ``ROOT``; um cache gravado
    # sob outro caminho do MESMO repositório é traduzido pelo relativo (ver
    # ``cached_factory_dependency_roots``). A verificação de frescura continua
    # sempre no root VIVO, nunca no root gravado.
    dependency_roots = cached_factory_dependency_roots()
    for raw_dependency in dependency_lines:
        dependency = raw_dependency.strip()
        relative = None
        for candidate_root in dependency_roots:
            if dependency.startswith(candidate_root + os.sep):
                relative = os.path.relpath(dependency, candidate_root)
                break
        if relative is None:
            continue
        first_component = relative.split(os.sep, 1)[0]
        # Toolchain and module cache sources are not repository inputs.  Every
        # project package emitted by ``go list -deps`` must be checked.
        if first_component not in {'cmd', 'internal', 'pkg'}:
            continue
        # Defesa contra manifesto adulterado: o alvo traduzido tem de continuar
        # DENTRO do root vivo (nada de ``..`` escapando do repositório).
        dependency_directory = os.path.normpath(
            os.path.join(live_root, relative))
        if not dependency_directory.startswith(live_root + os.sep):
            return 'cached_factory_dependency_manifest_escapes_root'
        project_dependency_seen = True
        if relative == os.path.join('cmd', 'factory'):
            command_dependency_seen = True
        try:
            entries = list(os.scandir(dependency_directory))
        except OSError as exc:
            return f'cached_factory_dependency_unreadable:{type(exc).__name__}'
        for entry in entries:
            if (not entry.name.endswith(source_suffixes) or
                    entry.name.endswith('_test.go')):
                continue
            try:
                source_stat = entry.stat(follow_symlinks=False)
            except OSError as exc:
                return f'cached_factory_freshness_unavailable:{type(exc).__name__}'
            if (not stat.S_ISREG(source_stat.st_mode) or
                    source_stat.st_mtime_ns > binary_mtime_ns):
                return f'cached_factory_stale:{relative}/{entry.name}'
    if not project_dependency_seen or not command_dependency_seen:
        return 'cached_factory_dependency_manifest_incomplete'
    return None


def global_distinctness_environment_error():
    """Precondição barata da medição global: o índice é consultável?

    ``_audit_global`` gasta a fase per-shard INTEIRA antes de descobrir, lá no
    fim, em ``query_global_distinctness_batch``, que o binário cacheado da
    fábrica não pode ser usado — e só então reprova TODOS os shards com
    ``distinctness_index_unavailable``. O teste de confiança
    (``cached_factory_binary_error``) é puro ``stat`` mais leitura de um
    manifesto: custa milissegundos. Avaliá-lo ANTES converte uma medição inútil
    de minutos num erro acionável de um segundo.

    Incidente que originou a precondição (medido em 2026-08-04, terceira
    ocorrência da mesma família): ``tools/ensure-audit-ready`` reconstruiu o
    binário às 09:41:04 e um agente concorrente editou
    ``internal/v2stockepoch/lease.go`` às 09:45:45 — arquivo do fecho de
    dependências de ``cmd/factory``. O binário virou stale ANTES de a medição
    começar, e os 852 shards reprovaram por ambiente. 655 deles não tinham
    NENHUM outro defeito: a indisponibilidade mascarou o estoque inteiro e o
    relatório persistido registrou ``files_ok=0``, número que não descreve o
    conteúdo.

    Isto NÃO afrouxa o gate e NÃO repara nada: nenhum veredito muda, e reparar
    dentro do auditor continua proibido (viraria falso-verde — ver o cabeçalho
    de ``tools/ensure-audit-ready``). Apenas antecipamos a MESMA recusa que o
    auditor já faria, entregando o motivo REAL em vez de 852 defeitos opacos.
    A verificação tardia dentro de ``query_global_distinctness_batch``
    permanece intocada: ela ainda apanha a edição que aterrissa no MEIO da
    medição, que é a corrida residual que queremos visível, não encoberta.

    Estoque finalizado vazio não tem medição a proteger — nesse caso a
    precondição se cala e o modo global segue somente-leitura, emitindo JSON.
    """
    finalized = any(
        is_finalized_v2_path(path)
        for path in glob.glob(
            os.path.join(ROOT, 'data/editorial/v2_pages/*.jsonl')))
    if not finalized:
        return None
    return cached_factory_binary_error()


def _json_object_without_duplicate_keys(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError(f'duplicate JSON key: {key}')
        result[key] = value
    return result


def _canonical_report_shard(value):
    if not isinstance(value, str):
        return False
    return bool(re.fullmatch(
        r'data/editorial/v2_pages/[a-z0-9][a-z0-9._-]*\.jsonl',
        value)) and is_finalized_v2_path(value)


def _canonical_report_intent(value):
    return (isinstance(value, str) and
            re.fullmatch(r'[a-z0-9]+(?:-[a-z0-9]+)*', value) is not None)


def _bounded_nonnegative_integer(value, maximum=INCREMENTAL_COUNTER_MAX):
    return type(value) is int and 0 <= value <= maximum


def _bounded_unit_number(value):
    return (type(value) in (int, float) and math.isfinite(value) and
            0 <= value <= 1)


def _valid_candidate_reasons(value):
    return (isinstance(value, list) and len(value) <= 6 and
            len(value) == len(set(value)) and
            all(item in INCREMENTAL_CANDIDATE_REASONS for item in value))


def _valid_global_candidate_reasons(value):
    if (not isinstance(value, list) or not value or
            len(value) != len(set(value)) or
            any(item not in INCREMENTAL_CANDIDATE_REASONS for item in value)):
        return False
    positions = {
        item: index
        for index, item in enumerate(GLOBAL_BATCH_CANDIDATE_REASON_ORDER)}
    return value == sorted(value, key=positions.__getitem__)


def incremental_report_contract_error(
        report, expected_target_shard, expected_target_digest,
        expected_target_pages):
    if not isinstance(report, dict):
        return 'distinctness_not_object'
    if not _bounded_nonnegative_integer(expected_target_pages):
        return 'expected_target_pages'
    if (type(report.get('schema_version')) is not int or
            report.get('schema_version') != INCREMENTAL_REPORT_SCHEMA_VERSION):
        return 'schema_version'
    if type(report.get('passed')) is not bool:
        return 'passed_type'
    if report.get('algorithm_fingerprint') != INCREMENTAL_ALGORITHM_FINGERPRINT:
        return 'algorithm_fingerprint'
    if (not isinstance(report.get('generation_root'), str) or
            re.fullmatch(r'[0-9a-f]{64}', report['generation_root']) is None):
        return 'generation_root_sha256'
    if (not isinstance(report.get('stock_root'), str) or
            re.fullmatch(r'[0-9a-f]{64}', report['stock_root']) is None):
        return 'stock_root_sha256'
    if (report.get('target_shard') != expected_target_shard or
            not _canonical_report_shard(report.get('target_shard'))):
        return 'target_shard'
    if (not isinstance(report.get('target_digest'), str) or
            re.fullmatch(r'[0-9a-f]{64}', report['target_digest']) is None or
            report['target_digest'] != expected_target_digest):
        return 'target_digest_sha256_or_snapshot_mismatch'
    if (report.get('publication_allowed') is not False or
            report.get('index_policy') != 'noindex'):
        return 'public_flags'
    if (report.get('visible_surface_scope_complete') is not True or
            report.get('visible_surfaces') !=
            list(INCREMENTAL_VISIBLE_SURFACES)):
        return 'visible_surface_scope'
    for key in ('inventory_complete', 'candidate_routing_complete',
                'local_routing_complete', 'target_snapshot_bound'):
        if type(report.get(key)) is not bool:
            return f'boolean:{key}'
    if (report['inventory_complete'] is not True or
            report['target_snapshot_bound'] is not True):
        return 'snapshot_or_inventory_incomplete'
    counter_limits = {
        'target_pages': INCREMENTAL_COUNTER_MAX,
        'stock_shards_verified': INCREMENTAL_COUNTER_MAX,
        'overlay_shards_parsed': 32,
        'overlay_pages': INCREMENTAL_COUNTER_MAX,
        'stock_pages_indexed': INCREMENTAL_COUNTER_MAX,
        'stock_bytes_hashed': INCREMENTAL_BYTES_HASHED_MAX,
        'stock_metadata_scanned': INCREMENTAL_COUNTER_MAX,
        'profiles_loaded': INCREMENTAL_COUNTER_MAX,
        'candidates_compared': INCREMENTAL_COUNTER_MAX,
        'stock_candidates_compared': INCREMENTAL_COUNTER_MAX,
        'local_pairs_compared': INCREMENTAL_COUNTER_MAX,
        'candidate_terms_read': INCREMENTAL_COUNTER_MAX,
        'postings_scanned': INCREMENTAL_COUNTER_MAX,
    }
    for key, maximum in counter_limits.items():
        if not _bounded_nonnegative_integer(report.get(key), maximum):
            return f'counter:{key}'
    if report['target_pages'] != expected_target_pages:
        return 'target_pages_snapshot_mismatch'
    if (report['overlay_pages'] > report['stock_pages_indexed'] or
            report['profiles_loaded'] > report['stock_pages_indexed'] or
            report['stock_candidates_compared'] >
            report['candidates_compared'] or
            report['candidates_compared'] !=
            report['stock_candidates_compared'] +
            report['local_pairs_compared'] or
            report['local_pairs_compared'] >
            report['target_pages'] * (report['target_pages'] - 1) // 2):
        return 'counter_coherence'
    if report['stock_metadata_scanned'] < 1:
        return 'inventory_target_missing'
    if (report['stock_shards_verified'] +
            report['overlay_shards_parsed'] !=
            report['stock_metadata_scanned'] - 1):
        return 'inventory_counter_incomplete'
    issues = report.get('issues')
    neighbors = report.get('neighbors')
    local_adjudications = report.get('local_ngram_adjudications')
    if not isinstance(issues, list):
        return 'issues_type'
    if not isinstance(neighbors, list):
        return 'neighbors_type'
    if (not isinstance(local_adjudications, list) or
            len(local_adjudications) > 10_000):
        return 'local_ngram_adjudications_type_or_budget'
    issue_fields = frozenset((
        'code', 'target_intent_id', 'peer_intent_id', 'peer_shard', 'field',
        'body_jaccard', 'max_identical_span_tokens', 'heading_reuse',
        'target_repeated_density', 'peer_repeated_density',
        'candidate_reasons', 'detail'))
    string_issue_fields = (
        'target_intent_id', 'peer_intent_id', 'peer_shard', 'field', 'detail')
    for issue in issues:
        if not isinstance(issue, dict) or not set(issue).issubset(issue_fields):
            return 'issue_shape'
        if issue.get('code') not in INCREMENTAL_ISSUE_CODES:
            return 'issue_code'
        for key in string_issue_fields:
            if key in issue and (not isinstance(issue[key], str) or
                                 len(issue[key]) > 4096):
                return f'issue_field:{key}'
        for key in ('target_intent_id', 'peer_intent_id'):
            if key in issue and not _canonical_report_intent(issue[key]):
                return f'issue_field:{key}'
        if ('peer_shard' in issue and
                not _canonical_report_shard(issue['peer_shard'])):
            return 'issue_field:peer_shard'
        for key in ('body_jaccard', 'target_repeated_density',
                    'peer_repeated_density'):
            if key in issue and not _bounded_unit_number(issue[key]):
                return f'issue_field:{key}'
        for key in ('max_identical_span_tokens', 'heading_reuse'):
            if key in issue and not _bounded_nonnegative_integer(issue[key]):
                return f'issue_field:{key}'
        if ('candidate_reasons' in issue and
                not _valid_candidate_reasons(issue['candidate_reasons'])):
            return 'issue_field:candidate_reasons'
        if issue.get('code') in {
                'body_jaccard_near_duplicate',
                'editorial_span_duplicate', 'editorial_repeat_density',
                'intent_id_dup_global', 'title_dup_global',
                'meta_dup_global', 'h1_dup_global'}:
            if (not _canonical_report_intent(
                    issue.get('target_intent_id')) or
                    not _canonical_report_intent(
                        issue.get('peer_intent_id')) or
                    not _canonical_report_shard(issue.get('peer_shard')) or
                    not _valid_candidate_reasons(
                        issue.get('candidate_reasons'))):
                return 'pair_issue_identity_or_reasons'
    neighbor_fields = frozenset((
        'target_intent_id', 'peer_intent_id', 'peer_shard', 'body_jaccard',
        'max_identical_span_tokens', 'target_repeated_density',
        'peer_repeated_density', 'candidate_reasons'))
    issues_by_identity_code = collections.defaultdict(list)
    for issue in issues:
        identity = (
            issue.get('target_intent_id'), issue.get('peer_intent_id'),
            issue.get('peer_shard'), issue.get('code'))
        issues_by_identity_code[identity].append(issue)
    for neighbor in neighbors:
        if (not isinstance(neighbor, dict) or
                set(neighbor) != neighbor_fields):
            return 'neighbor_shape'
        if (not _canonical_report_intent(neighbor['target_intent_id']) or
                not _canonical_report_intent(neighbor['peer_intent_id']) or
                not _canonical_report_shard(neighbor['peer_shard'])):
            return 'neighbor_identity'
        for key in ('body_jaccard', 'target_repeated_density',
                    'peer_repeated_density'):
            if not _bounded_unit_number(neighbor[key]):
                return f'neighbor_field:{key}'
        if not _bounded_nonnegative_integer(
                neighbor['max_identical_span_tokens']):
            return 'neighbor_field:max_identical_span_tokens'
        if not _valid_candidate_reasons(neighbor['candidate_reasons']):
            return 'neighbor_field:candidate_reasons'
        identity = (
            neighbor['target_intent_id'], neighbor['peer_intent_id'],
            neighbor['peer_shard'])
        required_codes = []
        if neighbor['body_jaccard'] >= INCREMENTAL_BODY_JACCARD_THRESHOLD:
            required_codes.append('body_jaccard_near_duplicate')
        if (neighbor['max_identical_span_tokens'] >=
                INCREMENTAL_IDENTICAL_SPAN_THRESHOLD):
            required_codes.append('editorial_span_duplicate')
        if (neighbor['target_repeated_density'] >=
                INCREMENTAL_REPEAT_DENSITY_THRESHOLD or
                neighbor['peer_repeated_density'] >=
                INCREMENTAL_REPEAT_DENSITY_THRESHOLD):
            required_codes.append('editorial_repeat_density')
        for code in required_codes:
            matches = issues_by_identity_code.get(identity + (code,), ())
            if not matches:
                return f'neighbor_blocker_without_issue:{code}'
            if not any(
                    issue.get('body_jaccard', 0) ==
                    neighbor['body_jaccard'] and
                    issue.get('max_identical_span_tokens', 0) ==
                    neighbor['max_identical_span_tokens'] and
                    issue.get('target_repeated_density', 0) ==
                    neighbor['target_repeated_density'] and
                    issue.get('peer_repeated_density', 0) ==
                    neighbor['peer_repeated_density'] and
                    issue.get('candidate_reasons') ==
                    neighbor['candidate_reasons']
                    for issue in matches):
                return f'neighbor_issue_metric_mismatch:{code}'
    previous_local_pair = None
    local_fields = {
        'left_intent_id', 'right_intent_id',
        'max_identical_span_tokens', 'candidate_reasons'}
    for adjudication in local_adjudications:
        if (not isinstance(adjudication, dict) or
                set(adjudication) != local_fields or
                not _canonical_report_intent(
                    adjudication['left_intent_id']) or
                not _canonical_report_intent(
                    adjudication['right_intent_id']) or
                adjudication['left_intent_id'] >=
                adjudication['right_intent_id'] or
                not _bounded_nonnegative_integer(
                    adjudication['max_identical_span_tokens']) or
                adjudication['max_identical_span_tokens'] < 12 or
                not _valid_candidate_reasons(
                    adjudication['candidate_reasons'])):
            return 'local_ngram_adjudication_shape'
        pair = (adjudication['left_intent_id'],
                adjudication['right_intent_id'])
        if previous_local_pair is not None and pair <= previous_local_pair:
            return 'local_ngram_adjudication_order_or_duplicate'
        previous_local_pair = pair
    for issue in issues:
        code = issue.get('code')
        if (code == 'body_jaccard_near_duplicate' and
                issue.get('body_jaccard', 0) <
                INCREMENTAL_BODY_JACCARD_THRESHOLD):
            return 'issue_metric_below_threshold:body_jaccard'
        if (code == 'editorial_span_duplicate' and
                issue.get('max_identical_span_tokens', 0) <
                INCREMENTAL_IDENTICAL_SPAN_THRESHOLD):
            return 'issue_metric_below_threshold:span'
        if (code == 'editorial_repeat_density' and
                max(issue.get('target_repeated_density', 0),
                    issue.get('peer_repeated_density', 0)) <
                INCREMENTAL_REPEAT_DENSITY_THRESHOLD):
            return 'issue_metric_below_threshold:density'
    if (not report['candidate_routing_complete'] and not any(
            issue.get('code') in {
                'distinctness_candidate_bucket_overflow',
                'distinctness_candidate_budget_exceeded'}
            for issue in issues)):
        return 'candidate_routing_incomplete_without_issue'
    if (not report['local_routing_complete'] and not any(
            issue.get('code') == 'distinctness_local_pair_budget_exceeded'
            for issue in issues)):
        return 'local_routing_incomplete_without_issue'
    if report['passed'] != (len(issues) == 0):
        return 'passed_issues_contradiction'
    if report['passed'] and (not report['candidate_routing_complete'] or
                             not report['local_routing_complete']):
        return 'passed_routing_incomplete'
    if len(neighbors) > report['target_pages'] * 5:
        return 'neighbors_budget'
    return None


def incremental_distinctness_projection_contract_error(
        projection, neighbors, expected_target_shard,
        expected_target_digest, expected_target_pages):
    """Valida a projeção incremental persistida no envelope do auditor.

    ``apply_incremental_distinctness`` não devolve o relatório bruto do
    factory: ele persiste uma projeção fechada e move ``neighbors`` para o
    envelope superior. Reconstruir somente os campos ausentes permite reutilizar
    o contrato canônico do relatório bruto sem fingir que a projeção contém
    ``passed``, ``issues`` ou ``target_pages``.
    """
    if not isinstance(projection, dict):
        return 'projection_not_object'
    expected_fields = {
        'status', 'schema_version', 'stock_root', 'generation_root',
        'algorithm_fingerprint', 'target_digest', 'stock_shards_verified',
        'overlay_shards_parsed', 'overlay_pages', 'stock_pages_indexed',
        'stock_bytes_hashed', 'stock_metadata_scanned', 'profiles_loaded',
        'candidates_compared', 'stock_candidates_compared',
        'local_pairs_compared', 'local_ngram_adjudications',
        'candidate_terms_read', 'postings_scanned', 'inventory_complete',
        'candidate_routing_complete', 'local_routing_complete',
        'target_snapshot_bound', 'visible_surface_scope_complete',
        'visible_surfaces', 'candidate_generation', 'exact_adjudication',
        'publication_allowed', 'index_policy',
    }
    if set(projection) != expected_fields:
        return 'projection_shape'
    if projection.get('status') != 'ready':
        return 'projection_status'
    if (projection.get('candidate_generation') !=
            INCREMENTAL_CANDIDATE_GENERATION):
        return 'projection_candidate_generation'
    if (projection.get('exact_adjudication') !=
            INCREMENTAL_EXACT_ADJUDICATION):
        return 'projection_exact_adjudication'
    raw = dict(projection)
    raw.pop('status')
    raw.pop('candidate_generation')
    raw.pop('exact_adjudication')
    raw.update({
        'passed': True,
        'target_shard': expected_target_shard,
        'target_pages': expected_target_pages,
        'issues': [],
        'neighbors': neighbors,
    })
    return incremental_report_contract_error(
        raw, expected_target_shard, expected_target_digest,
        expected_target_pages)


def incremental_envelope_contract_error(
        payload, expected_target_shard, expected_target_digest,
        expected_target_pages):
    if not isinstance(payload, dict):
        return 'envelope_not_object'
    if (payload.get('mode') != 'incremental-distinctness-read-only' or
            payload.get('scope') != 'shard' or
            payload.get('run_key') != 'v2-distinctness'):
        return 'envelope_identity'
    if (payload.get('publication_allowed') is not False or
            payload.get('index_policy') != 'noindex'):
        return 'envelope_public_flags'
    return incremental_report_contract_error(
        payload.get('distinctness'), expected_target_shard,
        expected_target_digest, expected_target_pages)


def _close_process_pipes(process):
    for stream in (process.stdout, process.stderr):
        if stream is not None:
            try:
                stream.close()
            except OSError:
                pass


def _kill_and_reap_process(process):
    try:
        try:
            os.killpg(process.pid, signal.SIGKILL)
        except (ProcessLookupError, OSError):
            if process.poll() is None:
                process.kill()
    finally:
        try:
            process.wait(timeout=1)
        except subprocess.TimeoutExpired:
            process.kill()
            try:
                process.wait(timeout=1)
            except subprocess.TimeoutExpired:
                pass
        finally:
            _close_process_pipes(process)


def _read_process_output_bounded(
        process, timeout_seconds, stdout_limit, stderr_limit):
    """Drain both pipes concurrently without retaining more than cap + 1."""
    buffers = {'stdout': bytearray(), 'stderr': bytearray()}
    limits = {'stdout': stdout_limit, 'stderr': stderr_limit}
    deadline = time.monotonic() + timeout_seconds
    selector = selectors.DefaultSelector()
    try:
        selector.register(process.stdout, selectors.EVENT_READ, 'stdout')
        selector.register(process.stderr, selectors.EVENT_READ, 'stderr')
        while selector.get_map():
            remaining = deadline - time.monotonic()
            if remaining <= 0:
                _kill_and_reap_process(process)
                return bytes(buffers['stdout']), bytes(buffers['stderr']), 'timeout'
            events = selector.select(remaining)
            if not events:
                _kill_and_reap_process(process)
                return bytes(buffers['stdout']), bytes(buffers['stderr']), 'timeout'
            for key, _ in events:
                label = key.data
                buffer = buffers[label]
                limit = limits[label]
                read_size = min(64 * 1024, limit + 1 - len(buffer))
                chunk = os.read(key.fileobj.fileno(), max(1, read_size))
                if not chunk:
                    selector.unregister(key.fileobj)
                    key.fileobj.close()
                    continue
                buffer.extend(chunk)
                if len(buffer) > limit:
                    _kill_and_reap_process(process)
                    return (bytes(buffers['stdout']),
                            bytes(buffers['stderr']), 'output_limit')
        remaining = deadline - time.monotonic()
        if remaining <= 0:
            _kill_and_reap_process(process)
            return bytes(buffers['stdout']), bytes(buffers['stderr']), 'timeout'
        try:
            process.wait(timeout=remaining)
        except subprocess.TimeoutExpired:
            _kill_and_reap_process(process)
            return bytes(buffers['stdout']), bytes(buffers['stderr']), 'timeout'
        _close_process_pipes(process)
        return bytes(buffers['stdout']), bytes(buffers['stderr']), None
    except OSError:
        _kill_and_reap_process(process)
        return bytes(buffers['stdout']), bytes(buffers['stderr']), 'io_error'
    finally:
        selector.close()


def query_incremental_distinctness(
        path, expected_target_digest, expected_target_pages):
    """Consulta o índice Pebble sem escrever conteúdo, dado ou relatório.

    ``factory run`` e ``factory index-distinctness`` são os produtores do índice. Esta função usa apenas o
    subcomando read-only ``factory status`` e, por isso, nunca tenta reparar um
    índice ausente/stale durante uma auditoria. Indisponibilidade reprova
    rapidamente o shard, sem transformar incerteza em falso-verde nem reabrir
    a varredura linear histórica.
    """
    try:
        expected_target_shard = canonical_incremental_target_shard(path)
    except (TypeError, ValueError) as exc:
        return None, f'incremental_query_target_invalid:{type(exc).__name__}'
    binary_error = cached_factory_binary_error()
    if binary_error:
        return None, binary_error
    command = [
        FACTORY_BINARY, 'status', '--root', ROOT,
        '--distinctness-shard', expected_target_shard,
    ]
    if FACTORY_DISTINCTNESS_STORE:
        command[4:4] = [
            '--distinctness-store', FACTORY_DISTINCTNESS_STORE]
    environment = minimal_factory_subprocess_environment()
    try:
        process = subprocess.Popen(
            command, cwd=ROOT, env=environment, stdin=subprocess.DEVNULL,
            stdout=subprocess.PIPE, stderr=subprocess.PIPE, bufsize=0,
            start_new_session=True)
        stdout, stderr, read_status = _read_process_output_bounded(
            process, FACTORY_QUERY_TIMEOUT_SECONDS,
            FACTORY_QUERY_STDOUT_MAX_BYTES,
            FACTORY_QUERY_STDERR_MAX_BYTES)
        if read_status == 'timeout':
            return None, 'incremental_query_unavailable:TimeoutExpired'
    except OSError as exc:
        return None, f'incremental_query_unavailable:{type(exc).__name__}'
    if read_status == 'output_limit':
        return None, 'incremental_query_output_limit_exceeded'
    if read_status == 'io_error':
        return None, 'incremental_query_unavailable:PipeReadError'
    if process.returncode != 0:
        detail = ' '.join(
            stderr.decode('utf-8', errors='replace').strip().split())
        return None, f'incremental_query_failed:{detail[:500]}'
    try:
        payload = json.loads(
            stdout.decode('utf-8'),
            object_pairs_hook=_json_object_without_duplicate_keys)
    except (UnicodeDecodeError, ValueError, json.JSONDecodeError) as exc:
        return None, f'incremental_query_invalid_json:{type(exc).__name__}'
    contract_error = incremental_envelope_contract_error(
        payload, expected_target_shard, expected_target_digest,
        expected_target_pages)
    if contract_error:
        return None, f'incremental_query_contract_mismatch:{contract_error}'
    return payload['distinctness'], None


def distinctness_issue_value(issue):
    target = str(issue.get('target_intent_id') or '(sem-intent)')
    peer = str(issue.get('peer_intent_id') or '')
    if peer:
        return f'{target}~{peer}'
    detail = str(issue.get('detail') or '')
    return f'{target}:{detail}' if detail else target


def fail_closed_incremental_distinctness(result, defect_code, reason,
                                         status):
    defects = collections.defaultdict(list)
    for key, values in result.get('defects', {}).items():
        defects[key].extend(values)
    defects[defect_code].append(reason)
    result['defects'] = {
        key: sorted(set(values)) for key, values in defects.items() if values}
    result['ok'] = False
    result['distinctness_index'] = {
        'status': status,
        'reason': reason,
        'publication_allowed': False,
        'index_policy': 'noindex',
    }
    return result


def apply_incremental_distinctness(
        result, report, expected_target_shard=None,
        expected_target_digest=None, expected_target_pages=None):
    """Troca o blocker de 12-grama por adjudicação exata versionada."""
    if expected_target_shard is None and isinstance(report, dict):
        expected_target_shard = report.get('target_shard')
    if expected_target_digest is None and isinstance(report, dict):
        expected_target_digest = report.get('target_digest')
    if expected_target_pages is None:
        expected_target_pages = result.get('active_pages')
    contract_error = incremental_report_contract_error(
        report, expected_target_shard, expected_target_digest,
        expected_target_pages)
    if contract_error:
        return fail_closed_incremental_distinctness(
            result, 'distinctness_index_invalid_report', contract_error,
            'invalid_report_fail_closed')
    adjudicated_local_pairs = {
        (item['left_intent_id'], item['right_intent_id'])
        for item in report.get('local_ngram_adjudications') or []}
    defects = collections.defaultdict(list)
    for key, values in result.get('defects', {}).items():
        if key != 'ngram_dup':
            defects[key].extend(values)
            continue
        for value in values:
            left, separator, right = str(value).partition('~')
            pair = tuple(sorted((left, right))) if separator else None
            if pair not in adjudicated_local_pairs:
                defects[key].append(value)
    evidence = result.get('evidence') or {}
    retained_ngram_evidence = []
    for item in evidence.get('ngram_dup') or []:
        left, separator, right = str(item.get('target') or '').partition('~')
        pair = tuple(sorted((left, right))) if separator else None
        if pair not in adjudicated_local_pairs:
            retained_ngram_evidence.append(item)
    if retained_ngram_evidence:
        evidence['ngram_dup'] = retained_ngram_evidence
    else:
        evidence.pop('ngram_dup', None)
    issues = report.get('issues') or []
    for issue in issues:
        if not isinstance(issue, dict) or not issue.get('code'):
            defects['distinctness_index_invalid_issue'].append(
                '(registro_sem_codigo)')
            continue
        defects[str(issue['code'])].append(
            distinctness_issue_value(issue))
    result['defects'] = {
        key: sorted(set(values)) for key, values in defects.items() if values}
    if issues:
        evidence['distinctness'] = issues
    if evidence:
        result['evidence'] = evidence
    else:
        result.pop('evidence', None)
    result['distinctness_index'] = {
        'status': 'ready',
        'schema_version': report.get('schema_version'),
        'stock_root': report.get('stock_root'),
        'generation_root': report.get('generation_root'),
        'algorithm_fingerprint': report.get('algorithm_fingerprint'),
        'target_digest': report.get('target_digest'),
        'stock_shards_verified': report.get('stock_shards_verified', 0),
        'overlay_shards_parsed': report.get('overlay_shards_parsed', 0),
        'overlay_pages': report.get('overlay_pages', 0),
        'stock_pages_indexed': report.get('stock_pages_indexed', 0),
        'stock_bytes_hashed': report.get('stock_bytes_hashed', 0),
        'stock_metadata_scanned': report.get(
            'stock_metadata_scanned', 0),
        'profiles_loaded': report.get('profiles_loaded', 0),
        'candidates_compared': report.get('candidates_compared', 0),
        'stock_candidates_compared': report.get(
            'stock_candidates_compared', 0),
        'local_pairs_compared': report.get('local_pairs_compared', 0),
        'local_ngram_adjudications': report.get(
            'local_ngram_adjudications') or [],
        'candidate_terms_read': report.get('candidate_terms_read', 0),
        'postings_scanned': report.get('postings_scanned', 0),
        'inventory_complete': report.get('inventory_complete'),
        'candidate_routing_complete': report.get(
            'candidate_routing_complete'),
        'local_routing_complete': report.get('local_routing_complete'),
        'target_snapshot_bound': report.get('target_snapshot_bound'),
        'visible_surface_scope_complete': report.get(
            'visible_surface_scope_complete'),
        'visible_surfaces': report.get('visible_surfaces'),
        'candidate_generation': INCREMENTAL_CANDIDATE_GENERATION,
        'exact_adjudication': INCREMENTAL_EXACT_ADJUDICATION,
        'publication_allowed': False,
        'index_policy': 'noindex',
    }
    result['distinctness_neighbors'] = report.get('neighbors') or []
    result['profiles_loaded'] = report['profiles_loaded']
    result['candidates_compared'] = report['candidates_compared']
    result['stock_pages_indexed'] = report.get('stock_pages_indexed', 0)
    result['max_heading_reuse'] = max(
        2, (report.get('stock_pages_indexed', 0) +
            report.get('target_pages', 0)) // 100)
    blocking = {
        key: values for key, values in result['defects'].items()
        if key != 'skipped'}
    result['ok'] = not blocking
    return result


def audit_against_stock(path, expect_n=None):
    """Audita focalmente e consulta o índice sem refazer scan global."""
    try:
        target_shard = canonical_incremental_target_shard(path)
        snapshot_bytes = read_target_snapshot(path)
    except (OSError, TypeError, ValueError) as exc:
        result = {
            'file': os.path.relpath(os.path.abspath(path), ROOT),
            'pages': 0,
            'defects': {},
            'ok': False,
        }
        return fail_closed_incremental_distinctness(
            result, 'distinctness_index_unavailable',
            f'target_snapshot_unavailable:{type(exc).__name__}',
            'unavailable_fail_closed')
    target_digest = hashlib.sha256(snapshot_bytes).hexdigest()
    result = audit_file(
        path, load_portfolio(), expect_n=expect_n,
        snapshot_bytes=snapshot_bytes)
    target_pages = result.get('active_pages')
    report, unavailable = query_incremental_distinctness(
        path, target_digest, target_pages)
    if report is None:
        return fail_closed_incremental_distinctness(
            result, 'distinctness_index_unavailable', unavailable,
            'unavailable_fail_closed')
    return apply_incremental_distinctness(
        result, report, target_shard, target_digest, target_pages)


def audit_against_stock_legacy(path, expect_n=None):
    """Rota histórica linear, mantida apenas para diagnóstico explícito.

    Ela ainda abre e parseia todos os shards do estoque e não é chamada pelo
    fluxo ``--against-stock``. Preservá-la por enquanto permite confrontar a
    migração em testes, sem reintroduzir o scan no caminho de produção.
    """
    portfolio = load_portfolio()
    result = audit_file(
        path, portfolio, expect_n=expect_n, collect_pages=True)
    target_pages = result.pop('_loaded_pages')
    result.pop('_loaded_page_lines')
    result.pop('_page_gram_sets')
    defects = collections.defaultdict(list)
    for key, values in result.get('defects', {}).items():
        defects[key].extend(values)

    active_targets = [
        (index, page) for index, page in enumerate(target_pages)
        if not page.get('skipped')]
    target_gram_owners = collections.defaultdict(set)
    for index, page in active_targets:
        for gram in exact_page_ngrams(page):
            target_gram_owners[gram].add(index)

    stock_files = sorted(
        candidate for candidate in glob.glob(
            os.path.join(ROOT, 'data/editorial/v2_pages/*.jsonl'))
        if (is_finalized_v2_path(candidate) and
            not same_input_file(candidate, path))
    )
    title_ct = collections.Counter()
    meta_ct = collections.Counter()
    h1_ct = collections.Counter()
    intent_ct = collections.Counter()
    stock_head_ct = collections.Counter()
    ngram_peers = collections.defaultdict(set)
    ngram_shared = {}
    target_intent_ct = collections.Counter()
    target_title_ct = collections.Counter()
    target_meta_ct = collections.Counter()
    target_h1_ct = collections.Counter()
    for _, page in active_targets:
        target_intent = (page.get('intent_id') or '').strip()
        if target_intent:
            target_intent_ct[target_intent] += 1
        target_title_ct[norm_key(page.get('title'))] += 1
        target_meta_ct[norm_key(page.get('meta_description'))] += 1
        target_h1_ct[norm_key(page.get('h1'))] += 1
    total_stock_pages = 0
    for stock_path in stock_files:
        rel = os.path.relpath(stock_path, ROOT)
        try:
            handle = open(stock_path, encoding='utf-8')
        except OSError:
            defects['stock_read_error'].append(rel)
            continue
        with handle:
            for line_number, line in enumerate(handle, 1):
                if not line.strip():
                    continue
                try:
                    page = json.loads(line)
                except json.JSONDecodeError:
                    defects['stock_json_invalid'].append(
                        f'{rel}:linha_{line_number}')
                    continue
                if not isinstance(page, dict):
                    defects['stock_json_invalid'].append(
                        f'{rel}:linha_{line_number}')
                    continue
                if page.get('skipped'):
                    continue
                try:
                    peer_intent = ((page.get('intent_id') or '').strip() or
                                   '(sem-intent)')
                    title_key = norm_key(page.get('title'))
                    meta_key = norm_key(page.get('meta_description'))
                    h1_key = norm_key(page.get('h1'))
                    headings = [
                        norm_key(section.get('heading'))
                        for section in page.get('sections', []) or []]
                    stock_grams = exact_page_ngrams(page)
                except (AttributeError, TypeError):
                    defects['stock_json_invalid'].append(
                        f'{rel}:linha_{line_number}')
                    continue
                total_stock_pages += 1
                if peer_intent != '(sem-intent)':
                    intent_ct[peer_intent] += 1
                title_ct[title_key] += 1
                meta_ct[meta_key] += 1
                h1_ct[h1_key] += 1
                stock_head_ct.update(headings)
                matched_targets = set()
                for gram in stock_grams:
                    for target_index in target_gram_owners.get(gram, ()):
                        matched_targets.add(target_index)
                        key = (target_index, peer_intent)
                        previous = ngram_shared.get(key)
                        if previous is None or gram < previous[0]:
                            ngram_shared[key] = (gram, page)
                for target_index in matched_targets:
                    ngram_peers[target_index].add(peer_intent)

    combined_head_ct = stock_head_ct.copy()
    for _, page in active_targets:
        for section in page.get('sections', []) or []:
            combined_head_ct[norm_key(section.get('heading'))] += 1
    max_heading = max(
        2, (total_stock_pages + len(active_targets)) // 100)
    for index, page in active_targets:
        intent = ((page.get('intent_id') or '').strip() or '(sem-intent)')
        if (intent != '(sem-intent)' and
                intent_ct[intent] + target_intent_ct[intent] > 1):
            defects['intent_id_dup_global'].append(intent)
        title_key = norm_key(page.get('title'))
        meta_key = norm_key(page.get('meta_description'))
        h1_key = norm_key(page.get('h1'))
        if title_ct[title_key] + target_title_ct[title_key] > 1:
            defects['title_dup_global'].append(intent)
        if meta_ct[meta_key] + target_meta_ct[meta_key] > 1:
            defects['meta_dup_global'].append(intent)
        if h1_ct[h1_key] + target_h1_ct[h1_key] > 1:
            defects['h1_dup_global'].append(intent)
        if any(combined_head_ct[norm_key(section.get('heading'))] >
               max_heading for section in page.get('sections', []) or []):
            defects['heading_reuso_global'].append(intent)
        for peer_intent in sorted(ngram_peers.get(index, ())):
            defects['ngram_dup_global'].append(
                f'{intent}~{peer_intent}')

    result['defects'] = {
        key: sorted(set(values)) for key, values in defects.items() if values}
    stock_evidence = []
    for index, page in active_targets:
        intent = ((page.get('intent_id') or '').strip() or '(sem-intent)')
        for peer_intent in sorted(ngram_peers.get(index, ())):
            gram, peer_page = ngram_shared[(index, peer_intent)]
            stock_evidence.append(ngram_evidence(
                intent, peer_intent, page, peer_page, gram))
    if stock_evidence:
        evidence = result.setdefault('evidence', {})
        evidence['ngram_dup_global'] = sorted(
            stock_evidence, key=lambda item: (
                item['target'], item['field'], item['peer_field'],
                item['phrase']))
    blocking = {
        key: values for key, values in result['defects'].items()
        if key != 'skipped'}
    result['ok'] = not blocking
    result['stock_pages_compared'] = total_stock_pages
    result['max_heading_reuse'] = max_heading
    return result


def canonical_report_path(value):
    """Resolve um destino explicito, confinado a ROOT e sem symlinks."""
    if not isinstance(value, str) or not value or value != value.strip():
        raise argparse.ArgumentTypeError(
            '--persist-report exige PATH canonico nao vazio')
    root = os.path.abspath(ROOT)
    if os.path.realpath(root) != root:
        raise argparse.ArgumentTypeError(
            '--persist-report recusa raiz do repo com componente simbolico')
    if os.path.isabs(value):
        if os.path.normpath(value) != value:
            raise argparse.ArgumentTypeError(
                '--persist-report exige PATH absoluto normalizado')
        candidate = value
    else:
        normalized = posixpath.normpath(value)
        if (normalized != value or normalized in ('.', '..') or
                normalized.startswith('../')):
            raise argparse.ArgumentTypeError(
                '--persist-report exige PATH relativo canonico sem traversal')
        candidate = os.path.abspath(
            os.path.join(root, *normalized.split('/')))
    try:
        confined = os.path.commonpath((root, candidate)) == root
    except ValueError:
        confined = False
    if not confined or candidate == root:
        raise argparse.ArgumentTypeError(
            '--persist-report recusa destino fora da raiz do repo')

    parent = os.path.dirname(candidate)
    relative_parent = os.path.relpath(parent, root)
    current = root
    if relative_parent != '.':
        for component in relative_parent.split(os.sep):
            current = os.path.join(current, component)
            if not os.path.lexists(current):
                continue
            current_stat = os.lstat(current)
            if stat.S_ISLNK(current_stat.st_mode):
                raise argparse.ArgumentTypeError(
                    '--persist-report recusa componente simbolico')
            if not stat.S_ISDIR(current_stat.st_mode):
                raise argparse.ArgumentTypeError(
                    '--persist-report exige ancestrais diretorios')
    if os.path.lexists(candidate):
        candidate_stat = os.lstat(candidate)
        if stat.S_ISLNK(candidate_stat.st_mode):
            raise argparse.ArgumentTypeError(
                '--persist-report recusa destino simbolico')
        if not stat.S_ISREG(candidate_stat.st_mode):
            raise argparse.ArgumentTypeError(
                '--persist-report exige arquivo regular como destino')
    return candidate


def persist_global_summary(out, report_path):
    """Anexa um resumo por troca atomica, somente após opt-in explícito.

    O lock no diretório serializa os writers cooperativos durante o ciclo
    read/copy/append/replace. O arquivo canônico só muda por ``os.replace``
    depois de o temporário completo estar em disco; falha anterior preserva
    integralmente o snapshot existente.
    """
    import fcntl
    import shutil
    import tempfile

    report_path = canonical_report_path(report_path)
    defect_counts = collections.Counter()
    files_with_defects = {}
    # 2026-08-04: o resumo reduzia cada defeito a ``{chave: quantidade}`` e
    # DESCARTAVA o motivo. Consequência medida: os relatórios de 2026-07-29
    # (687/722) e 2026-08-04 (852/852) são indistinguíveis — ambos dizem apenas
    # ``distinctness_index_unavailable``, e cada diagnóstico exigiu repetir uma
    # medição global inteira só para redescobrir a própria causa. O motivo real
    # já existe em ``res['distinctness_index']`` (``status``/``reason``, gravado
    # tanto no caminho ``ready`` quanto no fail-closed); persisti-lo aqui separa
    # falso-vermelho de AMBIENTE (binário stale, manifesto incompleto, timeout)
    # de defeito de CONTEÚDO, sem alterar nenhum veredito.
    distinctness_status = collections.Counter()
    distinctness_reasons = collections.Counter()
    for fname, res in out['files'].items():
        counts = {k: len(v) for k, v in res['defects'].items() if k != 'skipped'}
        if counts:
            files_with_defects[os.path.basename(fname)] = counts
            defect_counts.update(counts)
        index = res.get('distinctness_index')
        if not isinstance(index, dict):
            index = {}
        distinctness_status[str(index.get('status') or 'ausente')] += 1
        reason = index.get('reason')
        if reason:
            distinctness_reasons[str(reason)[:300]] += 1
    summary = {
        'audited_at': datetime.datetime.now(datetime.timezone.utc)
                      .strftime('%Y-%m-%dT%H:%M:%SZ'),
        'total_pages': out['total_pages'],
        'files_total': len(out['files']),
        'files_ok': sum(1 for r in out['files'].values() if r['ok']),
        'defect_counts': dict(defect_counts.most_common()),
        'files_with_defects': files_with_defects,
        'distinctness_index_status': dict(distinctness_status.most_common()),
        'distinctness_index_reasons': dict(distinctness_reasons.most_common(8)),
    }
    encoded = (json.dumps(summary, ensure_ascii=False) + '\n').encode('utf-8')
    directory = os.path.dirname(report_path)
    # ``canonical_report_path`` autentica todos os ancestrais existentes antes
    # de qualquer criacao. A segunda leitura fecha mudancas ocorridas durante
    # a criacao e impede que o caminho passe a apontar para fora de ROOT.
    os.makedirs(directory, exist_ok=True)
    report_path = canonical_report_path(report_path)
    directory = os.path.abspath(directory)

    directory_flags = os.O_RDONLY
    if hasattr(os, 'O_DIRECTORY'):
        directory_flags |= os.O_DIRECTORY
    directory_fd = os.open(directory, directory_flags)
    temporary_fd = None
    temporary_path = None
    source = None
    lock_acquired = False
    try:
        fcntl.flock(directory_fd, fcntl.LOCK_EX)
        lock_acquired = True
        output_mode = 0o644
        source_flags = os.O_RDONLY
        if hasattr(os, 'O_NOFOLLOW'):
            source_flags |= os.O_NOFOLLOW
        try:
            source_fd = os.open(report_path, source_flags)
        except FileNotFoundError:
            source_fd = None
        if source_fd is not None:
            source_stat = os.fstat(source_fd)
            if not stat.S_ISREG(source_stat.st_mode):
                os.close(source_fd)
                raise ValueError(
                    '--persist-report exige arquivo regular como destino')
            output_mode = stat.S_IMODE(source_stat.st_mode)
            source = os.fdopen(source_fd, 'rb')

        temporary_fd, temporary_path = tempfile.mkstemp(
            prefix='.' + os.path.basename(report_path) + '.',
            suffix='.tmp', dir=directory)
        os.fchmod(temporary_fd, output_mode)
        with os.fdopen(temporary_fd, 'wb') as destination:
            temporary_fd = None
            if source is not None:
                with source:
                    source.seek(0, os.SEEK_END)
                    existing_size = source.tell()
                    if existing_size:
                        source.seek(-1, os.SEEK_END)
                        if source.read(1) != b'\n':
                            raise ValueError(
                                '--persist-report recusa JSONL sem newline terminal')
                    source.seek(0)
                    shutil.copyfileobj(source, destination)
            destination.write(encoded)
            destination.flush()
            os.fsync(destination.fileno())
        os.replace(temporary_path, report_path)
        temporary_path = None
        os.fsync(directory_fd)
    finally:
        if source is not None and not source.closed:
            source.close()
        if temporary_fd is not None:
            os.close(temporary_fd)
        if temporary_path is not None:
            try:
                os.unlink(temporary_path)
            except FileNotFoundError:
                pass
        if lock_acquired:
            fcntl.flock(directory_fd, fcntl.LOCK_UN)
        os.close(directory_fd)


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument('file', nargs='?')
    ap.add_argument('--expect-n', type=int, default=None)
    ap.add_argument('--global', dest='global_mode', action='store_true')
    ap.add_argument('--against-stock', action='store_true')
    ap.add_argument(
        '--persist-report', metavar='PATH', type=canonical_report_path,
        help='persiste resumo global atomicamente no PATH explicito')
    args = ap.parse_args()
    if args.global_mode and args.against_stock:
        ap.error('--global e --against-stock sao mutuamente exclusivos')
    if args.persist_report is not None and not args.global_mode:
        ap.error('--persist-report exige --global')
    if args.global_mode:
        environment_error = global_distinctness_environment_error()
        if environment_error is not None:
            sys.stderr.write(
                'audit_v2_pages: ambiente de auditoria indisponivel: '
                f'{environment_error}\n'
                'audit_v2_pages: medicao global ABORTADA antes da fase '
                'per-shard. Sem isso, todos os shards reprovariam por '
                'distinctness_index_unavailable -- falso-vermelho de '
                'AMBIENTE, nao de conteudo -- depois de gastar minutos de '
                'CPU, e o relatorio registraria files_ok=0 sem dizer o '
                'porque.\n'
                'audit_v2_pages: prepare o ambiente e repita a medicao: '
                'tools/ensure-audit-ready\n')
            sys.exit(2)
        out = audit_global()
        if args.persist_report is not None:
            persist_global_summary(out, args.persist_report)
        print(json.dumps(out, ensure_ascii=False, indent=1))
        sys.exit(0 if all(r['ok'] for r in out['files'].values()) else 1)
    if not args.file:
        ap.error('informe FILE ou --global')
    if args.against_stock:
        # CAUSA-RAIZ 2026-08-12: ate aqui, o modo --against-stock so descobria
        # o binario/indice cacheado stale DENTRO de query_incremental_distinctness
        # (via cached_factory_binary_error), depois de audit_file ja ter rodado
        # a auditoria de conteudo inteira do shard -- e devolvia exatamente o
        # MESMO exit 1 / mesma forma de {ok:false, defects:{...}} que uma pagina
        # com defeito de conteudo real. O chamador (regra 8 do prompt do
        # redator, measure-v2-approval-rate, finalize-v2-review) nao tinha como
        # distinguir "pagina ruim" de "ambiente indisponivel" sem abrir o JSON e
        # comparar a chave do defeito a mao -- e o redator do lote
        # tributario-viz1-01 tratou as duas a mesma coisa. A precondicao espelha
        # EXATAMENTE o que --global ja faz (linhas acima): mesma funcao
        # (cached_factory_binary_error), mesma mensagem, mesmo exit code 2,
        # stdout vazio (nunca um relatorio parcial). Isso NAO afrouxa o gate:
        # nenhum veredito de conteudo muda, e a verificacao tardia dentro de
        # query_incremental_distinctness continua de pe para a corrida residual
        # (edicao Go pousando NO MEIO desta auditoria) -- ver o docstring de
        # query_incremental_distinctness.
        binary_error = cached_factory_binary_error()
        if binary_error is not None:
            sys.stderr.write(
                'audit_v2_pages: ambiente de auditoria indisponivel: '
                f'{binary_error}\n'
                'audit_v2_pages: --against-stock ABORTADO antes da auditoria '
                'de conteudo do shard. Sem isso, a pagina reprovaria com '
                'distinctness_index_unavailable -- falso-vermelho de '
                'AMBIENTE, nao de conteudo -- misturado ao mesmo exit code e '
                'a mesma forma de um defeito real.\n'
                'audit_v2_pages: prepare o ambiente e repita a auditoria: '
                'tools/ensure-audit-ready\n')
            sys.exit(2)
        res = audit_against_stock(args.file, args.expect_n)
        print(json.dumps(res, ensure_ascii=False, indent=1))
        sys.exit(0 if res['ok'] else 1)
    res = audit_file(args.file, load_portfolio(), args.expect_n)
    print(json.dumps(res, ensure_ascii=False, indent=1))
    sys.exit(0 if res['ok'] else 1)


if __name__ == '__main__':
    main()
